        private void requireLargeDownloadResume(List<String> missing) {
            JsonNode payload = largeDownloadAcceptance;
            require(missing, payload != null,
                    "large download acceptance result");
            if (payload != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode", "rootRendered",
                        "flowClientOwned", "opaqueRequestBridgeObserved",
                        "opaqueResponseBridgeObserved", "pushObserved",
                        "largeDownloadInitialResponseObserved",
                        "largeDownloadCancellationObserved",
                        "largeDownloadPartialResponseObserved",
                        "largeDownloadContentRangeObserved",
                        "largeDownloadExactReassemblyObserved",
                        "largeDownloadServerCancellationObserved",
                        "largeDownloadJavaListenerObserved", "errorFree")) {
                    require(missing, bool(payload, field),
                            "large download " + field);
                }
                long totalBytes = payload.path("totalBytes").asLong(-1);
                long cancelledBytes = payload.path("cancelledBytes").asLong(-1);
                long resumedBytes = payload.path("resumedBytes").asLong(-1);
                require(missing, payload.path("initialStatus").asInt() == 200,
                        "large download initial HTTP 200 response");
                require(missing, payload.path("resumeStatus").asInt() == 206,
                        "large download resumed HTTP 206 response");
                require(missing, totalBytes > 4L * 1024 * 1024,
                        "large download total byte count");
                require(missing,
                        cancelledBytes >= 256L * 1024
                                && cancelledBytes < totalBytes,
                        "large download bounded cancellation offset");
                require(missing,
                        resumedBytes == totalBytes - cancelledBytes,
                        "large download resumed byte count");
            }
            require(missing, opaqueResponseCancelCount >= 1,
                    "opaque response cancellation envelope");
            require(missing, opaqueRangeRequestCount >= 1,
                    "opaque Range request envelope");
            require(missing, opaquePartialResponseCount >= 1,
                    "opaque HTTP 206 response envelope");
            require(missing, opaqueLargeResponseEndCount >= 1,
                    "complete large opaque response envelope");
            require(missing,
                    opaqueCancelledRequestIds.stream().anyMatch(
                            opaqueSuccessfulResponseRequestIds::contains),
                    "correlated successful response cancellation");
            require(missing,
                    opaqueRangeRequestIds.stream().anyMatch(requestId ->
                            opaquePartialResponseRequestIds.contains(requestId)
                                    && opaqueLargeResponseEndRequestIds.contains(
                                    requestId)),
                    "correlated Range, HTTP 206 and large response completion");
        }

        private void requireLargeUploadRetry(List<String> missing) {
            JsonNode payload = largeUploadAcceptance;
            require(missing, payload != null,
                    "large upload acceptance result");
            if (payload != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode", "rootRendered",
                        "flowClientOwned", "opaqueRequestBridgeObserved",
                        "opaqueResponseBridgeObserved", "pushObserved",
                        "largeUploadProgressObserved",
                        "largeUploadAbortObserved",
                        "largeUploadRemovalObserved",
                        "largeUploadRetryObserved",
                        "largeUploadSuccessObserved",
                        "largeUploadExactBytesObserved",
                        "largeUploadServerCancellationObserved",
                        "largeUploadJavaListenerObserved", "errorFree")) {
                    require(missing, bool(payload, field),
                            "large upload " + field);
                }
                long totalBytes = payload.path("totalBytes").asLong(-1);
                long cancelThreshold = payload.path("cancelThreshold").asLong(-1);
                long firstProgressBytes =
                        payload.path("firstProgressBytes").asLong(-1);
                long retryProgressBytes =
                        payload.path("retryProgressBytes").asLong(-1);
                long serverCancelledBytes =
                        payload.path("serverCancelledBytes").asLong(-1);
                require(missing, totalBytes > 4L * 1024 * 1024,
                        "large upload total byte count");
                require(missing,
                        cancelThreshold >= 256L * 1024
                                && firstProgressBytes >= cancelThreshold
                                && firstProgressBytes < totalBytes,
                        "large upload bounded progress cancellation");
                require(missing, retryProgressBytes == totalBytes,
                        "large upload retry progress byte count");
                require(missing,
                        serverCancelledBytes >= 128L * 1024
                                && serverCancelledBytes < totalBytes,
                        "large upload server cancellation byte count");
                require(missing,
                        payload.path("serverSuccessBytes").asLong(-1)
                                == totalBytes,
                        "large upload successful body byte count");
                require(missing,
                        payload.path("serverDeclaredBytes").asLong(-1)
                                == totalBytes,
                        "large upload declared body byte count");
                require(missing, payload.path("startEvents").asInt(-1) == 2,
                        "large upload two start events");
                require(missing, payload.path("abortEvents").asInt(-1) == 1,
                        "large upload one abort event");
                require(missing, payload.path("removeEvents").asInt(-1) == 1,
                        "large upload one removal event");
                require(missing, payload.path("successEvents").asInt(-1) == 1,
                        "large upload one success event");
                require(missing, payload.path("errorEvents").asInt(-1) == 0,
                        "large upload zero error events");
            }
            require(missing, opaqueLargeRequestCount >= 2,
                    "two large opaque request open envelopes");
            require(missing, opaqueRawUploadRequestIds.size() >= 2,
                    "two large raw upload request envelopes");
            require(missing, opaqueLargeRequestEndCount >= 1,
                    "complete large opaque request envelope");
            require(missing,
                    opaqueRawUploadRequestIds.stream().anyMatch(
                            opaqueCancelledRequestIds::contains),
                    "correlated large raw upload cancellation");
            require(missing,
                    opaqueRawUploadRequestIds.stream().anyMatch(requestId ->
                            !opaqueCancelledRequestIds.contains(requestId)
                                    && opaqueLargeRequestEndIds.contains(requestId)
                                    && opaqueSuccessfulResponseRequestIds.contains(
                                    requestId)),
                    "correlated large raw upload completion and response");
        }

        private void requireInFlightRequestRecovery(List<String> missing) {
            JsonNode payload = inFlightRequestRecoveryAcceptance;
            require(missing, payload != null,
                    "in-flight request recovery acceptance result");
            if (payload != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode",
                        "interruptedRequestInFlight",
                        "interruptedRequestFailed",
                        "oldDocumentSidecarDisconnected",
                        "oldDocumentLateRequestRejected",
                        "oldDocumentRequestCountStable",
                        "oldDocumentPushRejected", "processRestarted",
                        "windowPreserved", "webViewPreserved",
                        "webViewReloaded", "freshFlowClientOwned",
                        "requestBridgeRecovered", "pushRecovered",
                        "recoveredRequestComplete",
                        "recoveredRequestExactBytes",
                        "javaConfirmationObserved", "errorFree")) {
                    require(missing, bool(payload, field),
                            "in-flight request recovery " + field);
                }
                long totalBytes = payload.path("totalBytes").asLong(-1);
                long interruptThreshold = payload.path(
                        "interruptThreshold").asLong(-1);
                long interruptedProgress = payload.path(
                        "interruptedProgressBytes").asLong(-1);
                require(missing, totalBytes > 4L * 1024 * 1024,
                        "in-flight request total byte count");
                require(missing,
                        interruptThreshold >= 256L * 1024
                                && interruptedProgress >= interruptThreshold
                                && interruptedProgress < totalBytes,
                        "in-flight request bounded interrupted progress");
                require(missing,
                        payload.path("disconnectedRequestCount").asInt() >= 1,
                        "old document disconnected request rejection count");
                require(missing,
                        payload.path("disconnectedPushOutboundCount").asInt()
                                >= 2,
                        "old document disconnected push rejection count");
                require(missing,
                        payload.path("recoveryGeneration").asInt() >= 1,
                        "in-flight request recovery generation");
                int previousProcess = payload.path(
                        "previousProcessIdentifier").asInt();
                int recoveredProcess = payload.path(
                        "processIdentifier").asInt();
                require(missing,
                        previousProcess > 0 && recoveredProcess > 0
                                && previousProcess != recoveredProcess,
                        "in-flight request replaced Java process");
            }

            require(missing, inFlightFailureInjectionOrder > 0,
                    "in-flight request sidecar failure injection");
            require(missing, inFlightSidecarExitOrder
                            > inFlightFailureInjectionOrder,
                    "in-flight request sidecar exit after failure injection");
            require(missing, inFlightRecoveryReadyOrder
                            > inFlightSidecarExitOrder,
                    "replacement sidecar ready after interrupted request");
            require(missing, sidecarRecoveryScheduledAttempts.equals(List.of(1)),
                    "single scheduled recovery attempt");
            require(missing, sidecarRecoveryReadyAttempts.equals(List.of(1)),
                    "single ready recovery attempt");
            require(missing, oldDocumentProbeOpenCount == 0,
                    "no old-document opaque request envelope");
            require(missing,
                    opaqueRequestOpenEventOrders.stream().noneMatch(order ->
                            order > inFlightFailureInjectionOrder
                                    && order < inFlightRecoveryReadyOrder),
                    "no old-document opaque request during recovery");
            require(missing,
                    pushConnectOrders.stream().noneMatch(order ->
                            order > inFlightFailureInjectionOrder
                                    && order < inFlightRecoveryReadyOrder),
                    "no old-document push connect during recovery");
            require(missing,
                    pushDisconnectOrders.stream().noneMatch(order ->
                            order > inFlightFailureInjectionOrder
                                    && order < inFlightRecoveryReadyOrder),
                    "no old-document push disconnect during recovery");

            require(missing, inFlightLargeRawRequests.size() == 2,
                    "exactly two large raw request generations");
            if (inFlightLargeRawRequests.size() == 2) {
                InFlightOpaqueRequestTrace interrupted =
                        inFlightLargeRawRequests.get(0);
                InFlightOpaqueRequestTrace recovered =
                        inFlightLargeRawRequests.get(1);
                require(missing,
                        interrupted.openOrder < inFlightFailureInjectionOrder,
                        "interrupted request opened before sidecar failure");
                require(missing,
                        interrupted.chunkBytes >= 256L * 1024
                                && interrupted.chunkBytes
                                < interrupted.contentLength,
                        "interrupted request partial opaque body");
                require(missing, interrupted.endOrder == 0,
                        "interrupted request has no request end");
                require(missing, interrupted.cancelOrder == 0,
                        "interrupted request emits no cancel to dead sidecar");
                require(missing, interrupted.responseOrder == 0,
                        "interrupted request has no response");
                require(missing,
                        recovered.openOrder > inFlightRecoveryReadyOrder,
                        "recovered request opened after replacement ready");
                require(missing,
                        recovered.contentLength > 4L * 1024 * 1024
                                && recovered.chunkBytes
                                == recovered.contentLength
                                && recovered.endBodyBytes
                                == recovered.contentLength,
                        "recovered request exact opaque body");
                require(missing,
                        recovered.endOrder > recovered.openOrder,
                        "recovered request end after open");
                require(missing,
                        recovered.responseStatus >= 200
                                && recovered.responseStatus < 300,
                        "recovered request successful response");
                require(missing,
                        recovered.responseOrder > recovered.endOrder
                                && recovered.responseEndOrder
                                > recovered.responseOrder,
                        "recovered response completed after request body");
                if (payload != null) {
                    require(missing,
                            interrupted.requestId.equals(
                                    text(payload, "interruptedRequestId")),
                            "interrupted request id correlation");
                    require(missing,
                            recovered.requestId.equals(
                                    text(payload, "recoveredRequestId")),
                            "recovered request id correlation");
                }
            }
        }

        private void requireLargeMultipartUploadRetry(List<String> missing) {
            JsonNode payload = largeMultipartUploadAcceptance;
            require(missing, payload != null,
                    "large multipart upload acceptance result");
            if (payload == null) {
                return;
            }
            for (String field : List.of(
                    "complete", "standardBundleMode", "rootRendered",
                    "flowClientOwned", "opaqueRequestBridgeObserved",
                    "opaqueResponseBridgeObserved", "pushObserved",
                    "largeMultipartUploadRequestObserved",
                    "largeMultipartUploadProgressObserved",
                    "largeMultipartUploadAbortObserved",
                    "largeMultipartUploadRemovalObserved",
                    "largeMultipartUploadRetryObserved",
                    "largeMultipartUploadSuccessObserved",
                    "largeMultipartUploadCancellationIsolationObserved",
                    "largeMultipartUploadExactBytesObserved",
                    "largeMultipartUploadDiskSpillObserved",
                    "largeMultipartUploadTemporaryPartCleanupObserved",
                    "largeMultipartUploadJavaListenersObserved",
                    "errorFree")) {
                require(missing, bool(payload, field),
                        "large multipart upload " + field);
            }

            long totalFileBytes =
                    payload.path("totalFileBytes").asLong(-1);
            long cancelThreshold =
                    payload.path("cancelThreshold").asLong(-1);
            long firstProgressBytes =
                    payload.path("firstProgressBytes").asLong(-1);
            long retryProgressBytes =
                    payload.path("retryProgressBytes").asLong(-1);
            require(missing, totalFileBytes > 4L * 1024 * 1024,
                    "large multipart upload file byte count");
            require(missing,
                    cancelThreshold >= 256L * 1024
                            && firstProgressBytes >= cancelThreshold
                            && firstProgressBytes < totalFileBytes,
                    "large multipart upload bounded progress cancellation");
            require(missing,
                    retryProgressBytes >= totalFileBytes
                            && retryProgressBytes
                            < totalFileBytes + 64L * 1024,
                    "large multipart upload framed retry progress");
            require(missing,
                    payload.path("progressEvents").asInt(-1) >= 3
                            && payload.path("startEvents").asInt(-1) == 2
                            && payload.path("requestEvents").asInt(-1) == 2
                            && payload.path("multipartRequestEvents")
                            .asInt(-1) == 2
                            && payload.path("multipartEntryEvents")
                            .asInt(-1) == 2
                            && payload.path("abortEvents").asInt(-1) == 1
                            && payload.path("removeEvents").asInt(-1) == 1
                            && payload.path("successEvents").asInt(-1) == 1
                            && payload.path("errorEvents").asInt(-1) == 0,
                    "large multipart upload browser event cardinality");
            require(missing,
                    payload.path("serverHandlerCalls").asInt(-1) == 1
                            && payload.path("serverHandlerFailures")
                            .asInt(-1) == 0
                            && payload.path("serverResponseCalls")
                            .asInt(-1) == 1
                            && payload.path("serverFailedResponses")
                            .asInt(-1) == 0
                            && payload.path("serverFailedAcceptedFiles")
                            .asInt(-1) == -1
                            && !bool(payload, "failedResponseHasException")
                            && text(payload, "failureType").isBlank()
                            && payload.path("serverSuccessfulResponses")
                            .asInt(-1) == 1
                            && payload.path("serverSuccessfulAcceptedFiles")
                            .asInt(-1) == 1,
                    "large multipart upload cancellation isolation");
            require(missing,
                    payload.path("serverSuccessfulBytes").asLong(-1)
                            == totalFileBytes
                            && payload.path("serverDeclaredBytes").asLong(-1)
                            == totalFileBytes
                            && payload.path("serverSpillBytes").asLong(-1)
                            == totalFileBytes,
                    "large multipart upload exact parsed part");

            require(missing, opaqueMultipartUploadRequestIds.size() == 2,
                    "two multipart opaque upload request opens");
            Set<String> cancelledIds = new java.util.HashSet<>(
                    opaqueMultipartUploadRequestIds);
            cancelledIds.retainAll(opaqueCancelledRequestIds);
            require(missing, cancelledIds.size() == 1,
                    "one correlated multipart request cancellation");
            if (cancelledIds.size() != 1) {
                return;
            }
            String cancelledId = cancelledIds.iterator().next();
            Set<String> completedIds = new java.util.HashSet<>(
                    opaqueMultipartUploadRequestIds);
            completedIds.remove(cancelledId);
            completedIds.removeIf(requestId ->
                    !opaqueRequestEndBodyBytes.containsKey(requestId)
                            || !opaqueSuccessfulResponseRequestIds.contains(
                            requestId));
            require(missing, completedIds.size() == 1,
                    "one correlated multipart retry completion and response");
            if (completedIds.size() != 1) {
                return;
            }
            String completedId = completedIds.iterator().next();
            require(missing,
                    !opaqueRequestEndBodyBytes.containsKey(cancelledId)
                            && !opaqueSuccessfulResponseRequestIds.contains(
                            cancelledId)
                            && opaqueRequestChunkBytes.getOrDefault(
                            cancelledId, -1L) == firstProgressBytes,
                    "multipart cancellation has no terminal success");
            require(missing,
                    opaqueRequestChunkBytes.getOrDefault(completedId, -1L)
                            == retryProgressBytes
                            && opaqueRequestEndBodyBytes.getOrDefault(
                            completedId, -1L) == retryProgressBytes
                            && opaqueResponseStatuses.getOrDefault(
                            completedId, -1) >= 200
                            && opaqueResponseStatuses.getOrDefault(
                            completedId, -1) < 400,
                    "multipart retry chunk, end and response correlation");
            Integer cancelledTerminal =
                    opaqueRequestCancelOrders.get(cancelledId);
            Integer retryOpen = opaqueRequestOpenOrders.get(completedId);
            require(missing,
                    cancelledTerminal != null && retryOpen != null
                            && cancelledTerminal < retryOpen,
                    "multipart retry opened after cancellation");
        }

        private void requireConcurrentUpload(List<String> missing) {
            JsonNode payload = concurrentUploadAcceptance;
            require(missing, payload != null,
                    "concurrent upload acceptance result");
            if (payload == null) {
                return;
            }
            for (String field : List.of(
                    "complete", "standardBundleMode", "rootRendered",
                    "flowClientOwned", "opaqueRequestBridgeObserved",
                    "opaqueResponseBridgeObserved", "pushObserved",
                    "concurrentUploadBrowserOverlapObserved",
                    "concurrentUploadProgressObserved",
                    "concurrentUploadAbortObserved",
                    "concurrentUploadRemovalObserved",
                    "concurrentUploadSurvivorObserved",
                    "concurrentUploadRequestIsolationObserved",
                    "concurrentUploadExactBytesObserved",
                    "concurrentUploadJavaListenersObserved", "errorFree")) {
                require(missing, bool(payload, field),
                        "concurrent upload " + field);
            }

            long cancelledTotal =
                    payload.path("cancelledTotalBytes").asLong(-1);
            long survivorTotal =
                    payload.path("survivorTotalBytes").asLong(-1);
            long cancelThreshold =
                    payload.path("cancelThreshold").asLong(-1);
            long overlapThreshold =
                    payload.path("overlapThreshold").asLong(-1);
            long cancelledProgress =
                    payload.path("cancelledProgressBytes").asLong(-1);
            long survivorProgress =
                    payload.path("survivorProgressBytes").asLong(-1);
            long serverCancelledBytes =
                    payload.path("serverCancelledBytes").asLong(-1);

            require(missing, cancelledTotal > 4L * 1024 * 1024,
                    "concurrent upload cancelled body size");
            require(missing, survivorTotal > 3L * 1024 * 1024,
                    "concurrent upload survivor body size");
            require(missing,
                    cancelThreshold >= 256L * 1024
                            && overlapThreshold >= 64L * 1024
                            && cancelledProgress >= cancelThreshold
                            && cancelledProgress < cancelledTotal
                            && survivorProgress == survivorTotal,
                    "concurrent upload bounded browser progress");
            require(missing,
                    payload.path("progressEvents").asInt(-1) >= 3
                            && payload.path("startEvents").asInt(-1) == 2
                            && payload.path("abortEvents").asInt(-1) == 1
                            && payload.path("removeEvents").asInt(-1) == 1
                            && payload.path("successEvents").asInt(-1) == 1
                            && payload.path("errorEvents").asInt(-1) == 0,
                    "concurrent upload browser event cardinality");
            require(missing,
                    payload.path("browserMaximumActive").asInt(-1) >= 2
                            && payload.path("serverMaximumActive").asInt(-1) >= 2,
                    "concurrent upload overlapping browser and server requests");
            require(missing,
                    serverCancelledBytes >= overlapThreshold
                            && serverCancelledBytes < cancelledTotal
                            && payload.path("serverCancelledDeclaredBytes")
                            .asLong(-1) == cancelledTotal,
                    "concurrent upload bounded server cancellation");
            require(missing,
                    payload.path("serverSuccessBytes").asLong(-1)
                            == survivorTotal
                            && payload.path("serverSuccessDeclaredBytes")
                            .asLong(-1) == survivorTotal,
                    "concurrent upload exact survivor body");

            Set<String> cancelledIds =
                    rawRequestIdsWithLength(cancelledTotal);
            Set<String> survivorIds = rawRequestIdsWithLength(survivorTotal);
            require(missing, cancelledIds.size() == 1,
                    "one correlated concurrent cancelled request open");
            require(missing, survivorIds.size() == 1,
                    "one correlated concurrent survivor request open");
            if (cancelledIds.size() != 1 || survivorIds.size() != 1) {
                return;
            }

            String cancelledId = cancelledIds.iterator().next();
            String survivorId = survivorIds.iterator().next();
            require(missing, !cancelledId.equals(survivorId),
                    "distinct concurrent opaque request identifiers");
            require(missing,
                    opaqueRequestCancelOrders.containsKey(cancelledId)
                            && !opaqueRequestEndBodyBytes.containsKey(cancelledId)
                            && !opaqueSuccessfulResponseRequestIds.contains(
                            cancelledId),
                    "correlated concurrent request cancellation");
            require(missing,
                    opaqueRequestEndBodyBytes.getOrDefault(survivorId, -1L)
                            == survivorTotal
                            && opaqueSuccessfulResponseRequestIds.contains(
                            survivorId)
                            && opaqueResponseStatuses.getOrDefault(
                            survivorId, -1) >= 200
                            && opaqueResponseStatuses.getOrDefault(
                            survivorId, -1) < 400,
                    "correlated concurrent survivor completion and response");

            Integer cancelledOpen = opaqueRequestOpenOrders.get(cancelledId);
            Integer survivorOpen = opaqueRequestOpenOrders.get(survivorId);
            Integer cancelledTerminal =
                    opaqueRequestCancelOrders.get(cancelledId);
            Integer survivorTerminal = opaqueRequestEndOrders.get(survivorId);
            require(missing,
                    cancelledOpen != null && survivorOpen != null
                            && cancelledTerminal != null
                            && survivorTerminal != null
                            && Math.max(cancelledOpen, survivorOpen)
                            < Math.min(cancelledTerminal, survivorTerminal),
                    "concurrent requests opened before either terminal frame");
        }

        private void requireRequestFanout(List<String> missing) {
            JsonNode payload = requestFanoutAcceptance;
            require(missing, payload != null,
                    "request fan-out acceptance result");
            if (payload == null) {
                return;
            }
            int batchSize = 6;
            int batchCount = 10;
            int requestCount = batchSize * batchCount;
            int cancelledCount = 2 * batchCount;
            int survivorCount = requestCount - cancelledCount;
            for (String field : List.of(
                    "complete", "standardBundleMode", "rootRendered",
                    "flowClientOwned", "opaqueRequestBridgeObserved",
                    "opaqueResponseBridgeObserved", "pushObserved",
                    "requestFanoutBrowserOverlapObserved",
                    "requestFanoutQueueReplenishmentObserved",
                    "requestFanoutBeyondInitialCreditObserved",
                    "requestFanoutCancellationObserved",
                    "requestFanoutSurvivorsObserved",
                    "requestFanoutServerIsolationObserved",
                    "requestFanoutExactBytesObserved",
                    "requestFanoutJavaListenersObserved",
                    "requestFanoutRegistryTurnoverObserved",
                    "requestFanoutLateResponseIsolationObserved",
                    "requestFanoutCancellationTombstoneExpiryObserved",
                    "requestIdsUnique", "cancelledLateFramesIgnored",
                    "completedRequestReclaimed",
                    "cancellationTombstoneRetained",
                    "cancellationTombstoneExpired", "errorFree")) {
                require(missing, bool(payload, field),
                        "request fan-out " + field);
            }

            JsonNode lengthsNode = payload.path("fileLengths");
            JsonNode cancelledLengthsNode =
                    payload.path("cancelledFileLengths");
            JsonNode survivorLengthsNode =
                    payload.path("survivorFileLengths");
            JsonNode cancelThresholdsNode =
                    payload.path("cancelThresholds");
            JsonNode progressNode = payload.path("progressBytes");
            JsonNode requestIdsNode = payload.path("requestIds");
            JsonNode firstBatchRequestIdsNode =
                    payload.path("firstBatchRequestIds");
            JsonNode secondBatchRequestIdsNode =
                    payload.path("secondBatchRequestIds");
            JsonNode batchStartEventsNode = payload.path("batchStartEvents");
            JsonNode batchTerminalEventsNode =
                    payload.path("batchTerminalEvents");
            require(missing,
                    lengthsNode.isArray()
                            && lengthsNode.size() == requestCount,
                    "sixty request fan-out body lengths");
            require(missing,
                    cancelledLengthsNode.isArray()
                            && cancelledLengthsNode.size() == cancelledCount,
                    "twenty request fan-out cancellation lengths");
            require(missing,
                    survivorLengthsNode.isArray()
                            && survivorLengthsNode.size() == survivorCount,
                    "forty request fan-out survivor lengths");
            require(missing,
                    cancelThresholdsNode.isArray()
                            && cancelThresholdsNode.size() == requestCount
                            && progressNode.isArray()
                            && progressNode.size() == requestCount,
                    "sixty request fan-out thresholds and progress values");
            require(missing,
                    requestIdsNode.isArray()
                            && requestIdsNode.size() == requestCount
                            && firstBatchRequestIdsNode.isArray()
                            && firstBatchRequestIdsNode.size() == batchSize
                            && secondBatchRequestIdsNode.isArray()
                            && secondBatchRequestIdsNode.size() == batchSize,
                    "sixty correlated requests across ten fan-out batches");
            require(missing,
                    payload.path("batchCount").asInt(-1) == batchCount
                            && payload.path("completedBatches").asInt(-1)
                            == batchCount
                            && batchCountsEqual(
                            batchStartEventsNode, batchCount, batchSize)
                            && batchCountsEqual(
                            batchTerminalEventsNode, batchCount, batchSize),
                    "ten completed request fan-out batch boundaries");
            if (!lengthsNode.isArray()
                    || lengthsNode.size() != requestCount
                    || !cancelledLengthsNode.isArray()
                    || cancelledLengthsNode.size() != cancelledCount
                    || !survivorLengthsNode.isArray()
                    || survivorLengthsNode.size() != survivorCount
                    || !cancelThresholdsNode.isArray()
                    || cancelThresholdsNode.size() != requestCount
                    || !progressNode.isArray()
                    || progressNode.size() != requestCount
                    || !requestIdsNode.isArray()
                    || requestIdsNode.size() != requestCount
                    || !firstBatchRequestIdsNode.isArray()
                    || firstBatchRequestIdsNode.size() != batchSize
                    || !secondBatchRequestIdsNode.isArray()
                    || secondBatchRequestIdsNode.size() != batchSize) {
                return;
            }

            Set<Long> lengths = new java.util.LinkedHashSet<>();
            Set<Long> firstBatchLengths = new java.util.LinkedHashSet<>();
            Set<Long> secondBatchLengths = new java.util.LinkedHashSet<>();
            Set<Long> churnLengths = new java.util.LinkedHashSet<>();
            Set<Long> cancelledLengths = new java.util.LinkedHashSet<>();
            Set<Long> survivorLengths = new java.util.LinkedHashSet<>();
            for (int index = 0; index < lengthsNode.size(); index++) {
                long length = lengthsNode.get(index).asLong(-1);
                lengths.add(length);
                if (index < batchSize) {
                    firstBatchLengths.add(length);
                } else if (index < 2 * batchSize) {
                    secondBatchLengths.add(length);
                } else {
                    churnLengths.add(length);
                }
            }
            for (JsonNode length : cancelledLengthsNode) {
                cancelledLengths.add(length.asLong(-1));
            }
            for (JsonNode length : survivorLengthsNode) {
                survivorLengths.add(length.asLong(-1));
            }
            Set<Long> partitionedLengths = new java.util.LinkedHashSet<>();
            partitionedLengths.addAll(cancelledLengths);
            partitionedLengths.addAll(survivorLengths);
            require(missing,
                    lengths.size() == requestCount
                            && firstBatchLengths.size() == batchSize
                            && firstBatchLengths.stream().allMatch(length ->
                            length > 4L * 1024 * 1024)
                            && secondBatchLengths.size() == batchSize
                            && secondBatchLengths.stream().allMatch(length ->
                            length > 2L * 1024 * 1024)
                            && churnLengths.size()
                            == requestCount - 2 * batchSize
                            && churnLengths.stream().allMatch(length ->
                            length > 256L * 1024),
                    "sixty unique raw request lengths across ten batches");
            require(missing,
                    cancelledLengths.size() == cancelledCount
                            && survivorLengths.size() == survivorCount
                            && partitionedLengths.equals(lengths),
                    "request fan-out cancellation and survivor partition");

            Map<Long, Long> cancelMinimumByLength = new LinkedHashMap<>();
            boolean progressValid = true;
            for (int index = 0; index < lengthsNode.size(); index++) {
                long length = lengthsNode.get(index).asLong(-1);
                long cancelThreshold =
                        cancelThresholdsNode.get(index).asLong(-1);
                long progress = progressNode.get(index).asLong(-1);
                long expectedThreshold = index < 2 * batchSize
                        ? 512L * 1024 : 192L * 1024;
                progressValid &= cancelThreshold == expectedThreshold
                        && cancelThreshold > 128L * 1024;
                cancelMinimumByLength.put(length,
                        index < 2 * batchSize
                                ? 512L * 1024 : 160L * 1024);
                if (cancelledLengths.contains(length)) {
                    progressValid &= progress >= cancelThreshold
                            && progress < length;
                } else {
                    progressValid &= progress == length;
                }
            }
            require(missing, progressValid,
                    "request fan-out progress beyond initial credit");
            require(missing,
                    payload.path("startEvents").asInt(-1) == requestCount
                            && payload.path("abortEvents").asInt(-1)
                            == cancelledCount
                            && payload.path("removeEvents").asInt(-1)
                            == cancelledCount
                            && payload.path("successEvents").asInt(-1)
                            == survivorCount
                            && payload.path("errorEvents").asInt(-1) == 0
                            && payload.path("cancelIssuedCount").asInt(-1)
                            == cancelledCount,
                    "request fan-out browser event cardinality");
            require(missing,
                    payload.path("maxConcurrentUploads").asInt(-1) == 3
                            && payload.path("browserMaximumActive").asInt(-1)
                            == 3
                            && payload.path("serverMaximumActive").asInt(-1)
                            == 3
                            && payload.path("allBeyondThreshold").asBoolean(),
                    "request fan-out bounded browser and Java queue overlap");
            long serverCancelledMinimum =
                    payload.path("serverCancelledMinimum").asLong(-1);
            long serverCancelledMaximum =
                    payload.path("serverCancelledMaximum").asLong(-1);
            long maximumCancelledLength = cancelledLengths.stream()
                    .mapToLong(Long::longValue).max().orElse(-1);
            require(missing,
                    serverCancelledMinimum >= 160L * 1024
                            && serverCancelledMaximum >= 512L * 1024
                            && serverCancelledMaximum
                            < maximumCancelledLength,
                    "request fan-out bounded Java cancellation");
            long expectedSuccessBytes = survivorLengths.stream()
                    .mapToLong(Long::longValue).sum();
            require(missing,
                    payload.path("serverSuccessBytes").asLong(-1)
                            == expectedSuccessBytes
                            && payload.path("serverExpectedSuccessBytes")
                            .asLong(-1) == expectedSuccessBytes,
                    "request fan-out exact Java survivor bytes");

            Map<Long, String> requestIdsByLength = new LinkedHashMap<>();
            for (long length : lengths) {
                Set<String> requestIds = rawRequestIdsWithLength(length);
                require(missing, requestIds.size() == 1,
                        "one raw request with fan-out length " + length);
                if (requestIds.size() == 1) {
                    requestIdsByLength.put(
                            length, requestIds.iterator().next());
                }
            }
            require(missing, requestIdsByLength.size() == requestCount
                            && new java.util.HashSet<>(
                            requestIdsByLength.values()).size() == requestCount,
                    "sixty distinct correlated fan-out request identifiers");
            if (requestIdsByLength.size() != requestCount) {
                return;
            }

            boolean browserRequestIdsMatchTrace = true;
            List<Set<String>> requestIdBatches = new ArrayList<>();
            for (int batch = 0; batch < batchCount; batch++) {
                requestIdBatches.add(new java.util.LinkedHashSet<>());
            }
            Set<String> cancelledRequestIds = new java.util.LinkedHashSet<>();
            Set<String> survivorRequestIds = new java.util.LinkedHashSet<>();
            for (int index = 0; index < lengthsNode.size(); index++) {
                long length = lengthsNode.get(index).asLong(-1);
                String requestId = requestIdsByLength.get(length);
                browserRequestIdsMatchTrace &= requestId != null
                        && requestId.equals(requestIdsNode.get(index).asText(""));
                if (requestId == null) {
                    continue;
                }
                requestIdBatches.get(index / batchSize).add(requestId);
                if (index < batchSize) {
                    browserRequestIdsMatchTrace &= requestId.equals(
                            firstBatchRequestIdsNode.get(index).asText(""));
                } else if (index < 2 * batchSize) {
                    browserRequestIdsMatchTrace &= requestId.equals(
                            secondBatchRequestIdsNode.get(index - batchSize)
                                    .asText(""));
                }
                (cancelledLengths.contains(length)
                        ? cancelledRequestIds : survivorRequestIds).add(requestId);
            }
            Set<String> firstBatchRequestIds = requestIdBatches.get(0);
            Set<String> secondBatchRequestIds = requestIdBatches.get(1);
            require(missing,
                    browserRequestIdsMatchTrace
                            && requestIdBatches.stream().allMatch(
                            requestIds -> requestIds.size() == batchSize)
                            && requestIdBatches.stream()
                            .flatMap(Set::stream).distinct().count()
                            == requestCount
                            && java.util.Collections.disjoint(
                            firstBatchRequestIds, secondBatchRequestIds),
                    "browser request registry ids correlated across ten batches");

            for (Map.Entry<Long, String> entry
                    : requestIdsByLength.entrySet()) {
                long length = entry.getKey();
                String requestId = entry.getValue();
                long chunkBytes =
                        opaqueRequestChunkBytes.getOrDefault(requestId, -1L);
                if (cancelledLengths.contains(length)) {
                    long cancelMinimum = cancelMinimumByLength
                            .getOrDefault(length, -1L);
                    Integer cancelOrder =
                            opaqueRequestCancelOrders.get(requestId);
                    require(missing,
                            cancelOrder != null
                                    && !opaqueRequestEndBodyBytes.containsKey(
                                    requestId)
                                    && !opaqueSuccessfulResponseRequestIds
                                    .contains(requestId)
                                    && chunkBytes >= cancelMinimum
                                    && chunkBytes < length,
                            "correlated fan-out request cancellation for "
                                    + length);
                } else {
                    Integer endOrder = opaqueRequestEndOrders.get(requestId);
                    require(missing,
                            endOrder != null
                                    && chunkBytes == length
                                    && opaqueRequestEndBodyBytes.getOrDefault(
                                    requestId, -1L) == length
                                    && opaqueSuccessfulResponseRequestIds
                                    .contains(requestId)
                                    && opaqueResponseStatuses.getOrDefault(
                                    requestId, -1) >= 200
                                    && opaqueResponseStatuses.getOrDefault(
                                    requestId, -1) < 400,
                            "correlated fan-out survivor completion for "
                                    + length);
                }
            }

            String ignoredLateResponseRequestId = payload.path(
                    "ignoredLateResponseRequestId").asText("");
            String reclaimedRequestId =
                    payload.path("reclaimedRequestId").asText("");
            require(missing,
                    payload.path("lateFrameProbeCount").asInt(-1) == 4
                            && firstBatchRequestIds.contains(
                            ignoredLateResponseRequestId)
                            && cancelledRequestIds.contains(
                            ignoredLateResponseRequestId)
                            && firstBatchRequestIds.contains(reclaimedRequestId)
                            && survivorRequestIds.contains(reclaimedRequestId)
                            && payload.path("registryProbeExpectedError")
                            .asText("").replaceAll("\\s+", "").equals(
                                    "unknownrequest" + reclaimedRequestId),
                    "request registry reclamation and cancelled late-response isolation");

            long tombstoneRetentionElapsedMillis = payload.path(
                    "tombstoneRetentionElapsedMillis").asLong(-1);
            long tombstoneExpiryElapsedMillis = payload.path(
                    "tombstoneExpiryElapsedMillis").asLong(-1);
            require(missing,
                    payload.path("tombstoneBoundaryProbeCount").asInt(-1) == 2
                            && tombstoneRetentionElapsedMillis >= 54_000
                            && tombstoneRetentionElapsedMillis < 60_000
                            && tombstoneExpiryElapsedMillis >= 60_000
                            && payload.path("tombstoneExpiryExpectedError")
                            .asText("").replaceAll("\\s+", "").equals(
                                    "unknownrequest"
                                            + ignoredLateResponseRequestId),
                    "bounded cancellation tombstone retention and expiry");

            require(missing,
                    requestIdBatches.stream().allMatch(
                            this::boundedRequestBatch),
                    "bounded queue replenishment in all ten fan-out batches");
            boolean batchesStrictlySequential = true;
            for (int batch = 1; batch < requestIdBatches.size(); batch++) {
                int latestPreviousTerminal = requestIdBatches.get(batch - 1)
                        .stream()
                        .map(this::opaqueRequestTerminalOrder)
                        .filter(java.util.Objects::nonNull)
                        .mapToInt(Integer::intValue).max().orElse(-1);
                int earliestCurrentOpen = requestIdBatches.get(batch).stream()
                        .map(opaqueRequestOpenOrders::get)
                        .filter(java.util.Objects::nonNull)
                        .mapToInt(Integer::intValue).min().orElse(-1);
                batchesStrictlySequential &= latestPreviousTerminal >= 0
                        && earliestCurrentOpen > latestPreviousTerminal;
            }
            require(missing,
                    batchesStrictlySequential,
                    "every fan-out batch terminated before the next opened");
        }

        private static boolean batchCountsEqual(
                JsonNode values, int count, int expected) {
            if (!values.isArray() || values.size() != count) {
                return false;
            }
            for (JsonNode value : values) {
                if (value.asInt(-1) != expected) {
                    return false;
                }
            }
            return true;
        }

        private Integer opaqueRequestTerminalOrder(String requestId) {
            Integer cancelOrder = opaqueRequestCancelOrders.get(requestId);
            return cancelOrder == null
                    ? opaqueRequestEndOrders.get(requestId) : cancelOrder;
        }

        private boolean boundedRequestBatch(Set<String> requestIds) {
            if (requestIds.size() != 6) {
                return false;
            }
            Map<Integer, Integer> activeDeltas = new java.util.TreeMap<>();
            int earliestTerminal = Integer.MAX_VALUE;
            int latestOpen = -1;
            int latestTerminal = -1;
            for (String requestId : requestIds) {
                Integer openOrder = opaqueRequestOpenOrders.get(requestId);
                Integer terminalOrder = opaqueRequestTerminalOrder(requestId);
                if (openOrder == null || terminalOrder == null) {
                    return false;
                }
                activeDeltas.merge(openOrder, 1, Integer::sum);
                activeDeltas.merge(terminalOrder, -1, Integer::sum);
                earliestTerminal = Math.min(earliestTerminal, terminalOrder);
                latestOpen = Math.max(latestOpen, openOrder);
                latestTerminal = Math.max(latestTerminal, terminalOrder);
            }
            int activeRequests = 0;
            int maximumActiveRequests = 0;
            for (int delta : activeDeltas.values()) {
                activeRequests += delta;
                maximumActiveRequests = Math.max(
                        maximumActiveRequests, activeRequests);
            }
            int opensBeforeFirstTerminal = 0;
            for (String requestId : requestIds) {
                if (opaqueRequestOpenOrders.get(requestId) < earliestTerminal) {
                    opensBeforeFirstTerminal++;
                }
            }
            return maximumActiveRequests == 3
                    && activeRequests == 0
                    && opensBeforeFirstTerminal == 3
                    && earliestTerminal < latestOpen
                    && latestOpen < latestTerminal;
        }

        private void requireConcurrentMultipartUpload(List<String> missing) {
            JsonNode payload = concurrentMultipartUploadAcceptance;
            require(missing, payload != null,
                    "concurrent multipart upload acceptance result");
            if (payload == null) {
                return;
            }
            for (String field : List.of(
                    "complete", "standardBundleMode", "rootRendered",
                    "flowClientOwned", "opaqueRequestBridgeObserved",
                    "opaqueResponseBridgeObserved", "pushObserved",
                    "concurrentMultipartUploadRequestObserved",
                    "concurrentMultipartUploadBrowserOverlapObserved",
                    "concurrentMultipartUploadProgressObserved",
                    "concurrentMultipartUploadAbortObserved",
                    "concurrentMultipartUploadRemovalObserved",
                    "concurrentMultipartUploadSurvivorObserved",
                    "concurrentMultipartUploadSessionSerializationObserved",
                    "concurrentMultipartUploadCancellationIsolationObserved",
                    "concurrentMultipartUploadExactBytesObserved",
                    "concurrentMultipartUploadDiskSpillObserved",
                    "concurrentMultipartUploadTemporaryPartCleanupObserved",
                    "concurrentMultipartUploadJavaListenersObserved",
                    "errorFree")) {
                require(missing, bool(payload, field),
                        "concurrent multipart upload " + field);
            }

            long cancelledTotal =
                    payload.path("cancelledTotalBytes").asLong(-1);
            long survivorTotal =
                    payload.path("survivorTotalBytes").asLong(-1);
            long cancelThreshold =
                    payload.path("cancelThreshold").asLong(-1);
            long overlapThreshold =
                    payload.path("overlapThreshold").asLong(-1);
            long cancelledProgress =
                    payload.path("cancelledProgressBytes").asLong(-1);
            long survivorProgress =
                    payload.path("survivorProgressBytes").asLong(-1);

            require(missing, cancelledTotal > 4L * 1024 * 1024,
                    "concurrent multipart cancelled file size");
            require(missing, survivorTotal > 3L * 1024 * 1024,
                    "concurrent multipart survivor file size");
            require(missing,
                    cancelThreshold >= 256L * 1024
                            && overlapThreshold >= 64L * 1024
                            && cancelledProgress >= cancelThreshold
                            && cancelledProgress
                            < cancelledTotal + 64L * 1024
                            && survivorProgress >= survivorTotal
                            && survivorProgress
                            < survivorTotal + 64L * 1024,
                    "concurrent multipart bounded browser progress");
            require(missing,
                    payload.path("progressEvents").asInt(-1) >= 3
                            && payload.path("startEvents").asInt(-1) == 2
                            && payload.path("requestEvents").asInt(-1) == 2
                            && payload.path("multipartRequestEvents")
                            .asInt(-1) == 2
                            && payload.path("multipartEntryEvents")
                            .asInt(-1) == 2
                            && payload.path("abortEvents").asInt(-1) == 1
                            && payload.path("removeEvents").asInt(-1) == 1
                            && payload.path("successEvents").asInt(-1) == 1
                            && payload.path("errorEvents").asInt(-1) == 0
                            && payload.path("browserMaximumActive")
                            .asInt(-1) >= 2,
                    "concurrent multipart browser event cardinality");
            require(missing,
                    payload.path("serverMaximumTemporaryDirectories")
                            .asInt(-1) == 1
                            && payload.path("serverMaximumTemporaryFiles")
                            .asInt(-1) == 1
                            && text(payload, "serverMonitorError").isBlank(),
                    "upstream session-locked multipart parsing");
            require(missing,
                    payload.path("serverHandlerCalls").asInt(-1) == 1
                            && payload.path("serverHandlerFailures")
                            .asInt(-1) == 0
                            && "flow-ipc-concurrent-multipart-survivor.bin"
                            .equals(text(payload, "serverHandlerFile"))
                            && text(payload, "serverFailedHandlerFile")
                            .isBlank()
                            && payload.path("serverResponseCalls")
                            .asInt(-1) == 1
                            && payload.path("serverFailedResponses")
                            .asInt(-1) == 0
                            && payload.path("serverSuccessfulResponses")
                            .asInt(-1) == 1
                            && payload.path("serverSuccessfulAcceptedFiles")
                            .asInt(-1) == 1
                            && "flow-ipc-concurrent-multipart-survivor.bin"
                            .equals(text(
                                    payload,
                                    "serverSuccessfulAcceptedFile")),
                    "concurrent multipart application-handler isolation");
            require(missing,
                    payload.path("serverSuccessBytes").asLong(-1)
                            == survivorTotal
                            && payload.path("serverSuccessDeclaredBytes")
                            .asLong(-1) == survivorTotal
                            && payload.path("serverSpillBytes").asLong(-1)
                            == survivorTotal,
                    "concurrent multipart exact survivor part");

            require(missing, opaqueMultipartUploadRequestIds.size() == 2,
                    "two concurrent multipart opaque request opens");
            Set<String> cancelledIds = new java.util.HashSet<>(
                    opaqueMultipartUploadRequestIds);
            cancelledIds.retainAll(opaqueCancelledRequestIds);
            require(missing, cancelledIds.size() == 1,
                    "one correlated concurrent multipart cancellation");
            if (cancelledIds.size() != 1) {
                return;
            }
            String cancelledId = cancelledIds.iterator().next();
            Set<String> completedIds = new java.util.HashSet<>(
                    opaqueMultipartUploadRequestIds);
            completedIds.remove(cancelledId);
            completedIds.removeIf(requestId ->
                    !opaqueRequestEndBodyBytes.containsKey(requestId)
                            || !opaqueSuccessfulResponseRequestIds.contains(
                            requestId));
            require(missing, completedIds.size() == 1,
                    "one concurrent multipart survivor response");
            if (completedIds.size() != 1) {
                return;
            }
            String survivorId = completedIds.iterator().next();
            require(missing,
                    !opaqueRequestEndBodyBytes.containsKey(cancelledId)
                            && !opaqueSuccessfulResponseRequestIds.contains(
                            cancelledId)
                            && opaqueRequestChunkBytes.getOrDefault(
                            cancelledId, -1L) == cancelledProgress,
                    "concurrent multipart cancellation has no terminal success");
            require(missing,
                    opaqueRequestChunkBytes.getOrDefault(survivorId, -1L)
                            == survivorProgress
                            && opaqueRequestEndBodyBytes.getOrDefault(
                            survivorId, -1L) == survivorProgress
                            && opaqueResponseStatuses.getOrDefault(
                            survivorId, -1) >= 200
                            && opaqueResponseStatuses.getOrDefault(
                            survivorId, -1) < 400,
                    "concurrent multipart survivor completion correlation");

            Integer cancelledOpen = opaqueRequestOpenOrders.get(cancelledId);
            Integer survivorOpen = opaqueRequestOpenOrders.get(survivorId);
            Integer cancelledTerminal =
                    opaqueRequestCancelOrders.get(cancelledId);
            Integer survivorTerminal = opaqueRequestEndOrders.get(survivorId);
            require(missing,
                    cancelledOpen != null && survivorOpen != null
                            && cancelledTerminal != null
                            && survivorTerminal != null
                            && Math.max(cancelledOpen, survivorOpen)
                            < Math.min(cancelledTerminal, survivorTerminal),
                    "concurrent multipart requests overlap before termination");
        }

        private void requireCrossSessionMultipartUpload(
                List<String> missing) {
            JsonNode payload = crossSessionMultipartUploadAcceptance;
            require(missing, payload != null,
                    "cross-session multipart upload acceptance result");
            if (payload == null) {
                return;
            }
            for (String field : List.of(
                    "complete", "standardBundleMode", "rootRendered",
                    "flowClientOwned", "opaqueRequestBridgeObserved",
                    "opaqueResponseBridgeObserved", "pushObserved",
                    "crossSessionMultipartUploadIdentityIsolationObserved",
                    "crossSessionMultipartUploadRequestObserved",
                    "crossSessionMultipartUploadTransportOverlapObserved",
                    "crossSessionMultipartUploadParserConcurrencyObserved",
                    "crossSessionMultipartUploadCancellationIsolationObserved",
                    "crossSessionMultipartUploadSurvivorObserved",
                    "crossSessionMultipartUploadExactBytesObserved",
                    "crossSessionMultipartUploadDiskSpillObserved",
                    "crossSessionMultipartUploadTemporaryPartCleanupObserved",
                    "crossSessionMultipartUploadJavaListenersObserved",
                    "crossWindowProgressOverlapObserved", "errorFree")) {
                require(missing, bool(payload, field),
                        "cross-session multipart upload " + field);
            }

            String mainWindowId = text(payload, "mainWindowId");
            String secondaryWindowId = text(payload, "secondaryWindowId");
            String mainSessionId = text(payload, "mainSessionId");
            String secondarySessionId = text(payload, "secondarySessionId");
            String mainUiId = text(payload, "mainUiId");
            String secondaryUiId = text(payload, "secondaryUiId");
            require(missing,
                    "main".equals(mainWindowId)
                            && "multipart-secondary".equals(
                            secondaryWindowId)
                            && !mainSessionId.isBlank()
                            && !secondarySessionId.isBlank()
                            && !mainSessionId.equals(secondarySessionId)
                            && !mainUiId.isBlank()
                            && !secondaryUiId.isBlank()
                            && !mainUiId.equals(secondaryUiId),
                    "distinct cross-session multipart window scope");

            long cancelledTotal =
                    payload.path("cancelledTotalBytes").asLong(-1);
            long survivorTotal =
                    payload.path("survivorTotalBytes").asLong(-1);
            long overlapThreshold =
                    payload.path("overlapThreshold").asLong(-1);
            long mainProgress =
                    payload.path("mainProgressBytes").asLong(-1);
            long secondaryProgress =
                    payload.path("secondaryProgressBytes").asLong(-1);
            require(missing, cancelledTotal > 12L * 1024 * 1024,
                    "cross-session multipart cancelled file size");
            require(missing, survivorTotal > 10L * 1024 * 1024,
                    "cross-session multipart survivor file size");
            require(missing,
                    payload.path("mainTotalBytes").asLong(-1)
                            == cancelledTotal
                            && payload.path("secondaryTotalBytes").asLong(-1)
                            == survivorTotal
                            && overlapThreshold >= 512L * 1024
                            && mainProgress >= overlapThreshold
                            && mainProgress < cancelledTotal + 64L * 1024
                            && secondaryProgress >= survivorTotal
                            && secondaryProgress
                            < survivorTotal + 64L * 1024,
                    "bounded cross-session multipart browser progress");
            require(missing,
                    payload.path("mainStartEvents").asInt(-1) == 1
                            && payload.path("mainRequestEvents").asInt(-1) == 1
                            && payload.path("mainMultipartRequestEvents")
                            .asInt(-1) == 1
                            && payload.path("mainMultipartEntryEvents")
                            .asInt(-1) == 1
                            && payload.path("mainProgressEvents").asInt(-1) > 1
                            && payload.path("mainAbortEvents").asInt(-1) == 1
                            && payload.path("mainRemoveEvents").asInt(-1) == 1
                            && payload.path("mainSuccessEvents").asInt(-1) == 0
                            && payload.path("mainErrorEvents").asInt(-1) == 0
                            && payload.path("secondaryStartEvents")
                            .asInt(-1) == 1
                            && payload.path("secondaryRequestEvents")
                            .asInt(-1) == 1
                            && payload.path("secondaryMultipartRequestEvents")
                            .asInt(-1) == 1
                            && payload.path("secondaryMultipartEntryEvents")
                            .asInt(-1) == 1
                            && payload.path("secondaryProgressEvents")
                            .asInt(-1) > 1
                            && payload.path("secondaryAbortEvents")
                            .asInt(-1) == 0
                            && payload.path("secondaryRemoveEvents")
                            .asInt(-1) == 0
                            && payload.path("secondarySuccessEvents")
                            .asInt(-1) == 1
                            && payload.path("secondaryErrorEvents")
                            .asInt(-1) == 0,
                    "cross-session multipart browser event cardinality");
            require(missing,
                    "flow-ipc-cross-session-multipart-cancel.bin".equals(
                            text(payload, "mainAbortFileName"))
                            && "flow-ipc-cross-session-multipart-cancel.bin"
                            .equals(text(payload, "mainRemovedFileName"))
                            && "flow-ipc-cross-session-multipart-survivor.bin"
                            .equals(text(payload, "secondarySuccessFileName")),
                    "cross-session multipart browser file identity");
            require(missing,
                    payload.path("maximumTemporaryDirectories").asInt(-1) >= 2
                            && payload.path("maximumTemporaryFiles")
                            .asInt(-1) >= 2
                            && text(payload, "mainServerMonitorError").isBlank()
                            && text(payload, "secondaryServerMonitorError")
                            .isBlank(),
                    "parallel request-scoped multipart temporary storage");
            require(missing,
                    payload.path("mainServerHandlerCalls").asInt(-1) == 0
                            && payload.path("mainServerHandlerFailures")
                            .asInt(-1) == 0
                            && text(payload, "mainServerHandlerFile").isBlank()
                            && text(payload, "mainServerFailedHandlerFile")
                            .isBlank()
                            && payload.path("mainServerResponseCalls")
                            .asInt(-1) == 0
                            && payload.path("mainServerFailedResponses")
                            .asInt(-1) == 0,
                    "canceled session avoids application handler dispatch");
            require(missing,
                    payload.path("secondaryServerHandlerCalls")
                            .asInt(-1) == 1
                            && payload.path("secondaryServerHandlerFailures")
                            .asInt(-1) == 0
                            && "flow-ipc-cross-session-multipart-survivor.bin"
                            .equals(text(payload, "secondaryServerHandlerFile"))
                            && text(payload, "secondaryServerFailedHandlerFile")
                            .isBlank()
                            && payload.path("secondaryServerResponseCalls")
                            .asInt(-1) == 1
                            && payload.path("secondaryServerFailedResponses")
                            .asInt(-1) == 0
                            && payload.path("secondaryServerSuccessfulResponses")
                            .asInt(-1) == 1
                            && payload.path("secondaryServerAcceptedFiles")
                            .asInt(-1) == 1
                            && "flow-ipc-cross-session-multipart-survivor.bin"
                            .equals(text(payload, "secondaryServerAcceptedFile")),
                    "survivor session application handler result");
            require(missing,
                    payload.path("secondaryServerSuccessBytes").asLong(-1)
                            == survivorTotal
                            && payload.path("secondaryServerDeclaredBytes")
                            .asLong(-1) == survivorTotal
                            && payload.path("secondaryServerSpillBytes")
                            .asLong(-1) == survivorTotal
                            && bool(payload, "secondaryServerPatternValid")
                            && bool(payload,
                            "secondaryServerDiskSpillObserved")
                            && bool(payload,
                            "mainServerTemporaryPartCleanupObserved")
                            && bool(payload,
                            "secondaryServerTemporaryPartCleanupObserved"),
                    "exact cross-session multipart survivor and cleanup");

            Set<ScopedRequestKey> mainKeys = scopedMultipartKeys(
                    mainWindowId, mainSessionId, mainUiId);
            Set<ScopedRequestKey> secondaryKeys = scopedMultipartKeys(
                    secondaryWindowId, secondarySessionId, secondaryUiId);
            require(missing, scopedMultipartUploadRequestKeys.size() == 2,
                    "two scoped multipart request opens");
            require(missing, mainKeys.size() == 1,
                    "one main-window multipart request open");
            require(missing, secondaryKeys.size() == 1,
                    "one secondary-window multipart request open");
            if (mainKeys.size() != 1 || secondaryKeys.size() != 1) {
                return;
            }
            ScopedRequestKey cancelledKey = mainKeys.iterator().next();
            ScopedRequestKey survivorKey = secondaryKeys.iterator().next();
            require(missing, !cancelledKey.equals(survivorKey),
                    "distinct scoped multipart request keys");
            require(missing,
                    scopedCancelledRequestKeys.contains(cancelledKey)
                            && !scopedRequestEndBodyBytes.containsKey(
                            cancelledKey)
                            && !scopedSuccessfulResponseKeys.contains(
                            cancelledKey)
                            && scopedRequestChunkBytes.getOrDefault(
                            cancelledKey, -1L) == mainProgress,
                    "scoped main-window multipart cancellation");
            require(missing,
                    !scopedCancelledRequestKeys.contains(survivorKey)
                            && scopedRequestChunkBytes.getOrDefault(
                            survivorKey, -1L) == secondaryProgress
                            && scopedRequestEndBodyBytes.getOrDefault(
                            survivorKey, -1L) == secondaryProgress
                            && scopedSuccessfulResponseKeys.contains(
                            survivorKey)
                            && scopedResponseStatuses.getOrDefault(
                            survivorKey, -1) >= 200
                            && scopedResponseStatuses.getOrDefault(
                            survivorKey, -1) < 400,
                    "scoped secondary-window multipart completion");

            Integer cancelledOpen =
                    scopedRequestOpenOrders.get(cancelledKey);
            Integer survivorOpen = scopedRequestOpenOrders.get(survivorKey);
            Integer cancelledTerminal =
                    scopedRequestCancelOrders.get(cancelledKey);
            Integer survivorTerminal =
                    scopedRequestEndOrders.get(survivorKey);
            require(missing,
                    cancelledOpen != null && survivorOpen != null
                            && cancelledTerminal != null
                            && survivorTerminal != null
                            && Math.max(cancelledOpen, survivorOpen)
                            < Math.min(cancelledTerminal, survivorTerminal),
                    "cross-window multipart requests overlap before termination");
        }

        private Set<ScopedRequestKey> scopedMultipartKeys(
                String windowId,
                String sessionId,
                String uiId) {
            Set<ScopedRequestKey> matches = new java.util.HashSet<>();
            for (ScopedRequestKey key : scopedMultipartUploadRequestKeys) {
                if (key.windowId.equals(windowId)
                        && key.sessionId.equals(sessionId)
                        && key.uiId.equals(uiId)) {
                    matches.add(key);
                }
            }
            return matches;
        }

        private Set<String> rawRequestIdsWithLength(long contentLength) {
            Set<String> matches = new java.util.HashSet<>();
            for (String requestId : opaqueRawRequestIds) {
                if (opaqueRequestContentLengths.getOrDefault(requestId, -1L)
                        == contentLength) {
                    matches.add(requestId);
                }
            }
            return matches;
        }

        private static boolean isRetiredScopeProductionHostEnvelopeType(
                String type) {
            return switch (type) {
                case "command", "capabilityResult", "opaqueHttpStreamOpen",
                        "opaqueHttpStreamResponse",
                        "opaqueHttpStreamResponseCredit",
                        "opaqueHttpStreamResponseChunk",
                        "opaqueHttpStreamResponseEnd", "opaquePush" -> true;
                default -> false;
            };
        }

        private void acceptRetiredScopeProductionHostEnvelope(
                JsonNode root,
                JsonNode payload,
                String type) {
            JsonNode envelope = payload.path("envelope");
            JsonNode envelopePayload = envelope.path("payload");
            String direction = text(root, "direction");
            int generation = payload.path("sidecarGeneration").asInt(-1);
            boolean receivedFromSidecar = "recv".equals(direction)
                    && "java-sidecar".equals(text(payload, "source"))
                    && generation == 1;
            boolean sentToSidecar = "send".equals(direction)
                    && "java-sidecar".equals(text(payload, "target"));
            retiredScopeProductionHostEnvelopes.add(
                    new FlowIpcEnvelopeTrace(
                            type,
                            direction,
                            text(envelope, "windowId"),
                            text(envelope, "sessionId"),
                            text(envelope, "uiId"),
                            text(envelopePayload, "requestId"),
                            envelopePayload,
                            messageCount,
                            "flow-ipc".equals(text(payload, "transport"))
                                    && (receivedFromSidecar || sentToSidecar)
                                    && envelope.path("version").asInt(-1) == 1
                                    && type.equals(text(envelope, "type"))
                                    && envelope.path("error").isNull()));
        }

        private void acceptDesktopCommand(JsonNode root, JsonNode payload) {
            JsonNode envelope = payload.path("envelope");
            JsonNode commandPayload = envelope.path("payload");
            int generation = payload.path("sidecarGeneration").asInt(-1);
            desktopCommands.add(new DesktopCommandTrace(
                    text(commandPayload, "command"),
                    text(envelope, "id"),
                    text(envelope, "correlationId"),
                    text(envelope, "windowId"),
                    text(envelope, "sessionId"),
                    text(envelope, "uiId"),
                    generation,
                    commandPayload.path("args"),
                    messageCount,
                    "recv".equals(text(root, "direction"))
                            && "java-sidecar".equals(text(payload, "source"))
                            && "flow-ipc".equals(text(payload, "transport"))
                            && generation > 0
                            && envelope.path("version").asInt(-1) == 1
                            && "command".equals(text(envelope, "type"))
                            && envelope.path("error").isNull()));
        }

        private void acceptDesktopResult(JsonNode root, JsonNode payload) {
            JsonNode envelope = payload.path("envelope");
            JsonNode resultPayload = envelope.path("payload");
            String outerCommand = text(payload, "command");
            String resultCommand = text(resultPayload, "command");
            int generation = payload.path("sidecarGeneration").asInt(-1);
            desktopResults.add(new DesktopResultTrace(
                    resultCommand,
                    text(envelope, "id"),
                    text(envelope, "correlationId"),
                    text(envelope, "windowId"),
                    text(envelope, "sessionId"),
                    text(envelope, "uiId"),
                    generation,
                    resultPayload,
                    messageCount,
                    "send".equals(text(root, "direction"))
                            && "java-sidecar".equals(text(payload, "target"))
                            && "flow-ipc".equals(text(payload, "transport"))
                            && generation > 0
                            && outerCommand.equals(resultCommand)
                            && envelope.path("version").asInt(-1) == 1
                            && "capabilityResult".equals(text(envelope, "type"))
                            && envelope.path("error").isNull()));
        }

        private void acceptCapabilityGenerationCommand(
                JsonNode root,
                JsonNode payload) {
            JsonNode envelope = payload.path("envelope");
            JsonNode commandPayload = envelope.path("payload");
            if (!"fileDialog.openFile".equals(text(commandPayload, "command"))) {
                return;
            }
            int generation = payload.path("sidecarGeneration").asInt(-1);
            capabilityGenerationCommands.add(new CapabilityGenerationCommandTrace(
                    text(envelope, "id"),
                    text(envelope, "correlationId"),
                    text(envelope, "windowId"),
                    text(envelope, "sessionId"),
                    text(envelope, "uiId"),
                    text(commandPayload.path("args"), "title"),
                    generation,
                    messageCount,
                    "recv".equals(text(root, "direction"))
                            && "java-sidecar".equals(text(payload, "source"))
                            && "flow-ipc".equals(text(payload, "transport"))
                            && generation > 0
                            && envelope.path("version").asInt(-1) == 1
                            && "command".equals(text(envelope, "type"))
                            && envelope.path("error").isNull()));
        }

        private void acceptCapabilityGenerationResult(
                JsonNode root,
                JsonNode payload) {
            JsonNode envelope = payload.path("envelope");
            JsonNode resultPayload = envelope.path("payload");
            String outerCommand = text(payload, "command");
            String resultCommand = text(resultPayload, "command");
            if (!"fileDialog.openFile".equals(outerCommand)
                    && !"fileDialog.openFile".equals(resultCommand)) {
                return;
            }
            int generation = payload.path("sidecarGeneration").asInt(-1);
            capabilityGenerationResults.add(new CapabilityGenerationResultTrace(
                    text(envelope, "id"),
                    text(envelope, "correlationId"),
                    text(envelope, "windowId"),
                    text(envelope, "sessionId"),
                    text(envelope, "uiId"),
                    generation,
                    resultPayload,
                    messageCount,
                    "send".equals(text(root, "direction"))
                            && "java-sidecar".equals(text(payload, "target"))
                            && "flow-ipc".equals(text(payload, "transport"))
                            && "fileDialog.openFile".equals(outerCommand)
                            && generation > 0
                            && envelope.path("version").asInt(-1) == 1
                            && "capabilityResult".equals(text(envelope, "type"))
                            && envelope.path("error").isNull()));
        }

        private void requireFlowCapabilityGenerationRecovery(
                List<String> missing) {
            JsonNode acceptance = flowCapabilityGenerationRecoveryAcceptance;
            int firstCommandOrder = desktopCommands.stream()
                    .filter(command -> "fileDialog.openFile".equals(command.command))
                    .mapToInt(command -> command.order).min().orElse(messageCount);
            String mainCommands = permissionManifestCommands("main", firstCommandOrder, missing);
            require(missing, List.of(mainCommands.split(",")).contains("fileDialog.openFile"),
                    "generation main manifest grants openFile");
            require(missing, acceptance != null,
                    "capability generation recovery acceptance result");
            if (acceptance != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode",
                        "rootRendered", "flowClientOwned",
                        "opaqueRequestObserved", "opaqueResponseObserved",
                        "firstPanelObserved",
                        "firstPanelProductInvalidatedObserved",
                        "firstPanelHiddenObserved", "secondPanelObserved",
                        "secondPanelDistinctObserved",
                        "secondPanelAcceptanceCanceledObserved",
                        "generationOnePanelObserved",
                        "generationOnePanelInvalidated",
                        "generationOnePanelClosed",
                        "generationTwoPanelObserved",
                        "generationTwoPanelCanceled",
                        "panelIdentityDistinct", "windowRetainedObserved",
                        "webViewRetainedObserved", "processReplacedObserved",
                        "windowPreserved", "webViewPreserved", "processRestarted",
                        "scopeRetainedObserved", "commandIdReused",
                        "commandScopeReused", "generationOneResultAbsent",
                        "generationTwoResultObserved", "staleResultDropped",
                        "javaListenerObserved", "uidlPatchObserved",
                        "nativePointerObserved", "nativePointerTrustedObserved",
                        "browserProgrammaticSetupObserved",
                        "balancedDrainObserved", "resultStableAfterDrain",
                        "generationTwoTestCancelInjected", "errorFree")) {
                    require(missing, bool(acceptance, field),
                            "capability generation recovery " + field);
                }
                require(missing,
                        acceptance.path("generationOneTestCancelInjected")
                                .isBoolean()
                                && !acceptance.path(
                                "generationOneTestCancelInjected").asBoolean(),
                        "capability generation recovery product-owned first panel cancellation");
                require(missing,
                        acceptance.path("pushObserved").isBoolean()
                                && !acceptance.path("pushObserved").asBoolean(),
                        "capability generation recovery focused push boundary");
                require(missing,
                        acceptance.path("recoveryGeneration").asInt(-1) == 1,
                        "capability generation recovery exact recovery generation");
                require(missing,
                        "main".equals(text(acceptance, "windowId"))
                                && "flow-ipc-session".equals(text(
                                acceptance, "sessionId"))
                                && "main".equals(text(acceptance, "uiId"))
                                && "fileDialog.openFile".equals(text(
                                acceptance, "command")),
                        "capability generation recovery exact command scope");
                require(missing,
                        "File dialog generation result: selected=none client=true change=1"
                                .equals(text(acceptance, "status")),
                        "capability generation recovery exact Java result status");
                require(missing,
                        acceptance.path("nativePointerEventCount").asInt(-1) == 2
                                && acceptance.path(
                                "nativePointerTrustedEventCount").asInt(-1) == 2
                                && "generation-one,generation-two".equals(text(
                                acceptance, "nativePointerStages")),
                        "capability generation recovery trusted AppKit pointer stages");
                String browserStages = text(
                        acceptance, "browserProgrammaticStages");
                require(missing,
                        "first-navigate,second-navigate".equals(browserStages)
                                && !browserStages.contains("invoke"),
                        "capability generation recovery browser-programmatic stages");
                int initialProcess = acceptance.path(
                        "initialProcessIdentifier").asInt();
                int previousProcess = acceptance.path(
                        "failedProcessIdentifier").asInt();
                int process = acceptance.path(
                        "recoveredProcessIdentifier").asInt();
                require(missing,
                        initialProcess > 0
                                && initialProcess == previousProcess
                                && process > 0
                                && previousProcess != process,
                        "capability generation recovery replaced Java process");
            }

            require(missing, windowCreated,
                    "capability generation recovery native window created");
            require(missing, sidecarRecoveryScheduledAttempts.equals(List.of(1)),
                    "capability generation recovery single scheduled attempt");
            require(missing, sidecarRecoveryReadyAttempts.equals(List.of(1)),
                    "capability generation recovery single ready attempt");

            require(missing, capabilityGenerationCommands.size() == 2,
                    "exactly two fileDialog.openFile generation commands");
            CapabilityGenerationCommandTrace generationOne =
                    capabilityGenerationCommand(1);
            CapabilityGenerationCommandTrace generationTwo =
                    capabilityGenerationCommand(2);
            require(missing, generationOne != null && generationTwo != null,
                    "one fileDialog.openFile command per sidecar generation");

            require(missing, capabilityGenerationResults.size() == 1,
                    "exactly one normal fileDialog.openFile capability result");
            CapabilityGenerationResultTrace generationTwoResult =
                    capabilityGenerationResults.size() == 1
                            ? capabilityGenerationResults.getFirst()
                            : null;

            List<OrderedEventTrace> invalidations = capabilityOperationEvents(
                    nativeCapabilityInvalidations);
            List<OrderedEventTrace> completionDrops = capabilityOperationEvents(
                    nativeCapabilityCompletionDrops);
            List<OrderedEventTrace> staleDrops = capabilityOperationEvents(
                    staleCapabilityResultDrops);
            require(missing, invalidations.size() == 1,
                    "one file dialog operation invalidation");
            require(missing, completionDrops.size() == 1,
                    "one invalidated file dialog completion drop");
            require(missing, staleDrops.size() == 1,
                    "one stale generation-one capability result drop");
            require(missing, nativePanelCancelInjections.size() == 1,
                    "one generation-two acceptance panel cancellation injection");
            require(missing,
                    capabilityGenerationFailureInjections.size() == 1,
                    "one in-flight native capability sidecar failure injection");

            OrderedEventTrace launchOne = uniqueGenerationEvent(
                    sidecarLaunches, 1);
            OrderedEventTrace launchTwo = uniqueGenerationEvent(
                    sidecarLaunches, 2);
            OrderedEventTrace startOne = uniqueGenerationEvent(
                    sidecarStarts, 1);
            OrderedEventTrace startTwo = uniqueGenerationEvent(
                    sidecarStarts, 2);
            OrderedEventTrace exitOne = uniqueUnexpectedGenerationExit(1);
            OrderedEventTrace recoveryReady =
                    sidecarRecoveryReadyEvents.size() == 1
                            ? sidecarRecoveryReadyEvents.getFirst()
                            : null;
            require(missing,
                    sidecarLaunches.size() == 2
                            && launchOne != null && launchTwo != null,
                    "exactly two generation-shaped sidecar launches");
            require(missing,
                    sidecarStarts.size() == 2
                            && startOne != null && startTwo != null,
                    "exactly two generation-shaped sidecar starts");
            require(missing, exitOne != null,
                    "unexpected generation-one sidecar exit");
            require(missing, recoveryReady != null,
                    "one generation recovery ready event");

            if (generationOne == null || generationTwo == null
                    || generationTwoResult == null
                    || invalidations.size() != 1
                    || completionDrops.size() != 1
                    || staleDrops.size() != 1
                    || nativePanelCancelInjections.size() != 1
                    || capabilityGenerationFailureInjections.size() != 1
                    || launchOne == null || launchTwo == null
                    || startOne == null || startTwo == null
                    || exitOne == null || recoveryReady == null) {
                return;
            }

            OrderedEventTrace invalidation = invalidations.getFirst();
            OrderedEventTrace completionDrop = completionDrops.getFirst();
            OrderedEventTrace staleDrop = staleDrops.getFirst();
            OrderedEventTrace cancelInjection =
                    nativePanelCancelInjections.getFirst();
            OrderedEventTrace failureInjection =
                    capabilityGenerationFailureInjections.getFirst();
            require(missing,
                    generationOne.traceShape && generationTwo.traceShape
                            && generationTwoResult.traceShape,
                    "full generation command/result transport trace shape");
            require(missing,
                    exactGenerationCommand(generationOne, 1,
                            "Flow file dialog generation one")
                            && exactGenerationCommand(generationTwo, 2,
                            "Flow file dialog generation two"),
                    "exact reused command identity, scope and generations");
            require(missing,
                    generationOne.id.equals(generationTwo.id)
                            && generationOne.correlationId.equals(
                            generationTwo.correlationId)
                            && generationOne.windowId.equals(
                            generationTwo.windowId)
                            && generationOne.sessionId.equals(
                            generationTwo.sessionId)
                            && generationOne.uiId.equals(generationTwo.uiId),
                    "reused command correlation and Flow IPC scope");
            require(missing,
                    exactSecondPanelCancelInjection(
                            cancelInjection,
                            startTwo.payload.path("processIdentifier").asInt()),
                    "exact generation-two acceptance panel cancellation");
            require(missing,
                    exactCapabilityGenerationFailureInjection(
                            failureInjection,
                            startOne.payload.path("processIdentifier").asInt()),
                    "exact generation-one sidecar failure injection");
            require(missing,
                    generationTwoResult.sidecarGeneration == 2
                            && correlated(generationTwo, generationTwoResult),
                    "generation-two command/result correlation and scope");
            require(missing,
                    exactCanceledOpenPanelPayload(generationTwoResult.payload, mainCommands),
                    "exact canceled generation-two open panel result");

            require(missing,
                    exactInvalidation(invalidation)
                            && exactCompletionDrop(
                            completionDrop,
                            invalidation.payload.path("operationToken").asInt(-1))
                            && exactStaleDrop(staleDrop, generationOne),
                    "exact generation-one invalidation and stale drop traces");
            require(missing,
                    exactSidecarLaunch(launchOne, 1)
                            && exactSidecarLaunch(launchTwo, 2)
                            && exactSidecarStart(startOne, 1)
                            && exactSidecarStart(startTwo, 2)
                            && exitOne.traceShape && recoveryReady.traceShape,
                    "full generation lifecycle trace shape");

            int previousProcess = startOne.payload.path(
                    "processIdentifier").asInt();
            int process = startTwo.payload.path("processIdentifier").asInt();
            require(missing,
                    previousProcess > 0 && process > 0
                            && previousProcess != process
                            && exitOne.payload.path("processIdentifier").asInt()
                            == previousProcess
                            && recoveryReady.payload.path(
                            "previousProcessIdentifier").asInt()
                            == previousProcess
                            && recoveryReady.payload.path(
                            "processIdentifier").asInt() == process
                            && bool(recoveryReady.payload, "processReplaced")
                            && recoveryReady.payload.path(
                            "recoveryGeneration").asInt(-1) >= 1,
                    "trace-correlated replaced sidecar process generations");
            if (acceptance != null) {
                require(missing,
                        previousProcess == acceptance.path(
                                "failedProcessIdentifier").asInt()
                                && process == acceptance.path(
                                "recoveredProcessIdentifier").asInt()
                                && generationOne.windowId.equals(text(
                                acceptance, "windowId"))
                                && generationOne.sessionId.equals(text(
                                acceptance, "sessionId"))
                                && generationOne.uiId.equals(text(
                                acceptance, "uiId")),
                        "acceptance and generation trace correlation");
            }

            require(missing,
                    launchOne.order < startOne.order
                            && startOne.order < generationOne.order
                            && generationOne.order < failureInjection.order
                            && failureInjection.order < exitOne.order
                            && exitOne.order < invalidation.order
                            && invalidation.order < completionDrop.order
                            && completionDrop.order < staleDrop.order
                            && staleDrop.order
                            < flowCapabilityGenerationRecoveryAcceptanceOrder,
                    "generation-one command exit invalidation and stale-drop order");
            require(missing,
                    exitOne.order < launchTwo.order
                            && launchTwo.order < startTwo.order
                            && startTwo.order < recoveryReady.order
                            && recoveryReady.order < generationTwo.order
                            && generationTwo.order < cancelInjection.order
                            && cancelInjection.order < generationTwoResult.order
                            && generationTwoResult.order
                            < flowCapabilityGenerationRecoveryAcceptanceOrder,
                    "generation-two launch recovery command result and acceptance order");
            require(missing,
                    shutdownSidecarCount == 1
                            && gracefulShutdownSidecarOrder
                            > flowCapabilityGenerationRecoveryAcceptanceOrder,
                    "one graceful recv shutdown after generation recovery acceptance");
        }

        private void requireFlowCapabilityOwnerWindowClose(
                List<String> missing) {
            JsonNode acceptance = flowCapabilityOwnerWindowCloseAcceptance;
            require(missing, acceptance != null,
                    "capability owner-window-close acceptance result");
            if (acceptance != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode", "rootRendered",
                        "flowClientOwned", "opaqueRequestObserved",
                        "opaqueResponseObserved", "ownerSecondaryOpenedObserved",
                        "secondaryScopeIsolatedObserved", "ownerPanelObserved",
                        "ownerPanelAttachedObserved", "ownerPanelVisibleObserved",
                        "ownerPanelProductInvalidatedObserved",
                        "ownerPanelDetachedObserved", "ownerPanelHiddenObserved",
                        "ownerWindowClosedObserved",
                        "ownerWindowContextReleasedObserved",
                        "windowCloseCommandObserved", "javaListenerObserved",
                        "javaTypedInvalidatedOutcomeObserved",
                        "capabilityContextCapturedObserved",
                        "backgroundSessionAbsentObserved",
                        "ownerCloseResultVisibleInMain",
                        "mainWindowRetainedObserved",
                        "mainWebViewRetainedObserved",
                        "mainProcessRetainedObserved",
                        "mainHealthJavaListenerObserved",
                        "mainHealthUidlPatchObserved", "nativePointerObserved",
                        "nativePointerTrustedObserved",
                        "browserProgrammaticSetupObserved",
                        "balancedDrainObserved", "resultStableAfterDrain",
                        "errorFree")) {
                    require(missing, bool(acceptance, field),
                            "capability owner-window-close " + field);
                }
                require(missing,
                        acceptance.path("ownerPanelTestCancelInjected")
                                .isBoolean()
                                && !acceptance.path(
                                "ownerPanelTestCancelInjected").asBoolean(),
                        "capability owner-window-close product-owned panel cancellation");
                require(missing,
                        acceptance.path("pushObserved").isBoolean()
                                && !acceptance.path("pushObserved").asBoolean(),
                        "capability owner-window-close focused push boundary");
                require(missing,
                        "fileDialog.openFile".equals(text(
                                acceptance, "command"))
                                && "INVALIDATED".equals(text(
                                acceptance, "typedOutcome"))
                                && "owner-window-closed".equals(text(
                                acceptance, "cancelReason")),
                        "capability owner-window-close exact typed outcome and reason");
                require(missing,
                        validOwnerSessionId(text(
                                acceptance, "ownerSessionId"))
                                && ownerScope(acceptance,
                                "ownerWindowId", "ownerSessionId", "ownerUiId",
                                text(acceptance, "ownerSessionId"))
                                && mainScope(acceptance,
                                "mainWindowId", "mainSessionId", "mainUiId")
                                && !text(acceptance, "ownerSessionId").equals(
                                text(acceptance, "mainSessionId")),
                        "capability owner-window-close exact owner and main scopes");
                require(missing,
                        "Owner close window: closing=true client=true error=none"
                                .equals(text(acceptance, "windowStatus")),
                        "capability owner-window-close exact window status");
                require(missing,
                        ("Owner close main health: result=outcome=INVALIDATED "
                                + "selected=none "
                                + "cancelReason=owner-window-closed "
                                + "operationInvalidated=true "
                                + "capabilityContextCaptured=true "
                                + "backgroundSessionAbsent=true "
                                + "secondaryClient=true change=1 "
                                + "client=true change=1")
                                .equals(text(acceptance, "javaOutcome")),
                        "capability owner-window-close exact Java health result");
                require(missing,
                        acceptance.path("nativePointerEventCount").asInt(-1) == 3
                                && acceptance.path(
                                "nativePointerTrustedEventCount").asInt(-1) == 3
                                && "secondary-dialog-open,main-owner-close,main-health"
                                .equals(text(acceptance, "nativePointerStages")),
                        "capability owner-window-close trusted AppKit pointer stages");
                require(missing,
                        "route-navigate,secondary-open".equals(text(
                                acceptance, "browserProgrammaticStages")),
                        "capability owner-window-close browser-programmatic setup stages");
                int requests = acceptance.path("requestCount").asInt(-1);
                int responses = acceptance.path("responseCount").asInt(-1);
                require(missing,
                        requests >= 2 && requests == responses
                                && acceptance.path(
                                "healthRequestBaseline").asInt(-1) < requests
                                && acceptance.path(
                                "healthResponseBaseline").asInt(-1) < responses,
                        "capability owner-window-close balanced quiet drain");
                int initialProcess = acceptance.path(
                        "initialProcessIdentifier").asInt();
                int currentProcess = acceptance.path(
                        "currentProcessIdentifier").asInt();
                require(missing,
                        initialProcess > 0 && initialProcess == currentProcess
                                && acceptance.path(
                                "recoveryGeneration").asInt(-1) == 0,
                        "capability owner-window-close retained process without recovery");
            }

            require(missing, capabilityGenerationCommands.size() == 1,
                    "exactly one secondary fileDialog.openFile command");
            require(missing, capabilityGenerationResults.size() == 1,
                    "exactly one owner-close fileDialog.openFile capability result");
            CapabilityGenerationCommandTrace command =
                    capabilityGenerationCommands.size() == 1
                            ? capabilityGenerationCommands.getFirst() : null;
            CapabilityGenerationResultTrace result =
                    capabilityGenerationResults.size() == 1
                            ? capabilityGenerationResults.getFirst() : null;

            List<OrderedEventTrace> invalidations = capabilityOperationEvents(
                    nativeCapabilityInvalidations);
            List<OrderedEventTrace> completionDrops = capabilityOperationEvents(
                    nativeCapabilityCompletionDrops);
            List<OrderedEventTrace> closeRequests = scopedEvents(
                    windowCloseRequests, "owner-close-secondary");
            List<OrderedEventTrace> closedEvents = scopedEvents(
                    windowClosedEvents, "owner-close-secondary");
            require(missing, invalidations.size() == 1,
                    "one owner-close file dialog operation invalidation");
            require(missing, completionDrops.size() == 1,
                    "one owner-close invalidated completion drop");
            require(missing, closeRequests.size() == 1,
                    "one owner-window close request trace");
            require(missing, closedEvents.size() == 1,
                    "one owner-window windowClosed send trace");
            require(missing, ownerWindowClosePanelEvents.size() == 1,
                    "one owner-panel observation trace");
            require(missing, ownerWindowCloseReleaseEvents.size() == 1,
                    "one owner-window native release trace");
            require(missing, ownerWindowClosePointerEvents.size() == 3,
                    "three owner-close native pointer dispatch traces");
            require(missing, nativePanelCancelInjections.isEmpty(),
                    "no owner-close acceptance panel cancellation injection");
            require(missing, staleCapabilityResultDrops.isEmpty(),
                    "no owner-close stale capability result drop");
            require(missing,
                    sidecarRecoveryScheduledAttempts.isEmpty()
                            && sidecarRecoveryReadyAttempts.isEmpty()
                            && sidecarRecoveryReadyEvents.isEmpty()
                            && capabilityGenerationFailureInjections.isEmpty()
                            && sidecarExits.stream().noneMatch(event ->
                            event.order
                                    < flowCapabilityOwnerWindowCloseAcceptanceOrder)
                            && sidecarReplacementRequestedCount == 0,
                    "no owner-close sidecar failure, replacement or recovery");

            OrderedEventTrace launch = uniqueGenerationEvent(sidecarLaunches, 1);
            OrderedEventTrace start = uniqueGenerationEvent(sidecarStarts, 1);
            require(missing,
                    sidecarLaunches.size() == 1 && launch != null
                            && exactSidecarLaunch(launch, 1),
                    "one owner-close generation-one sidecar launch");
            require(missing,
                    sidecarStarts.size() == 1 && start != null
                            && exactSidecarStart(start, 1),
                    "one owner-close generation-one sidecar start");

            if (command == null || result == null
                    || invalidations.size() != 1
                    || completionDrops.size() != 1
                    || closeRequests.size() != 1 || closedEvents.size() != 1
                    || ownerWindowClosePanelEvents.size() != 1
                    || ownerWindowCloseReleaseEvents.size() != 1
                    || ownerWindowClosePointerEvents.size() != 3
                    || launch == null || start == null) {
                return;
            }

            String ownerSessionId = command.sessionId;
            OrderedEventTrace invalidation = invalidations.getFirst();
            OrderedEventTrace completionDrop = completionDrops.getFirst();
            OrderedEventTrace closeRequest = closeRequests.getFirst();
            OrderedEventTrace windowClosed = closedEvents.getFirst();
            OrderedEventTrace panel = ownerWindowClosePanelEvents.getFirst();
            OrderedEventTrace release = ownerWindowCloseReleaseEvents.getFirst();
            OrderedEventTrace secondaryPointer = uniqueStageEvent(
                    ownerWindowClosePointerEvents, "secondary-dialog-open");
            OrderedEventTrace closePointer = uniqueStageEvent(
                    ownerWindowClosePointerEvents, "main-owner-close");
            OrderedEventTrace healthPointer = uniqueStageEvent(
                    ownerWindowClosePointerEvents, "main-health");
            require(missing,
                    command.traceShape && result.traceShape
                            && exactOwnerCloseCommand(command)
                            && command.sidecarGeneration == 1,
                    "exact secondary owner-close command transport and scope");
            require(missing,
                    result.sidecarGeneration == command.sidecarGeneration
                            && correlated(command, result),
                    "owner-close command/result correlation, generation and scope");
            require(missing, exactOwnerCloseResultPayload(result.payload),
                    "exact unsuccessful owner-close file dialog result payload");
            require(missing,
                    exactOwnerCloseInvalidation(invalidation)
                            && exactOwnerCloseCompletionDrop(
                            completionDrop,
                            invalidation.payload.path(
                                    "operationToken").asInt(-1)),
                    "exact owner-close invalidation and same-token completion drop");
            require(missing,
                    exactOwnerCloseRequest(closeRequest, ownerSessionId),
                    "exact owner-window close request scope");
            require(missing,
                    exactOwnerWindowClosed(windowClosed, ownerSessionId),
                    "exact owner-window windowClosed send scope");
            require(missing,
                    exactOwnerPanelObserved(panel, ownerSessionId),
                    "exact attached visible owner panel observation");
            require(missing, exactOwnerReleased(release),
                    "exact detached hidden panel and retained main context");
            require(missing,
                    exactOwnerPointerEvent(secondaryPointer,
                            "secondary-dialog-open", true, ownerSessionId)
                            && exactOwnerPointerEvent(closePointer,
                            "main-owner-close", false, ownerSessionId)
                            && exactOwnerPointerEvent(healthPointer,
                            "main-health", false, ownerSessionId),
                    "exact scoped owner-close native pointer dispatch stages");

            int processIdentifier = start.payload.path(
                    "processIdentifier").asInt();
            if (acceptance != null) {
                require(missing,
                        processIdentifier == acceptance.path(
                                "initialProcessIdentifier").asInt()
                                && processIdentifier == acceptance.path(
                                "currentProcessIdentifier").asInt()
                                && ownerSessionId.equals(text(
                                acceptance, "ownerSessionId")),
                        "owner-close acceptance and sidecar process correlation");
            }
            if (secondaryPointer == null || closePointer == null
                    || healthPointer == null) {
                return;
            }
            require(missing,
                    launch.order < start.order
                            && start.order < secondaryPointer.order
                            && secondaryPointer.order < command.order
                            && command.order < panel.order
                            && panel.order < closePointer.order
                            && closePointer.order < closeRequest.order
                            && closeRequest.order < invalidation.order
                            && invalidation.order < completionDrop.order
                            && completionDrop.order < result.order
                            && result.order < windowClosed.order
                            && windowClosed.order < release.order
                            && release.order < healthPointer.order
                            && healthPointer.order
                            < flowCapabilityOwnerWindowCloseAcceptanceOrder,
                    "owner-close command, release, result, close and health order");
            require(missing,
                    shutdownSidecarCount == 1
                            && gracefulShutdownSidecarOrder
                            > flowCapabilityOwnerWindowCloseAcceptanceOrder,
                    "one graceful recv shutdown after owner-close acceptance");
        }

        private void requireFlowCapabilityContextReopen(
                List<String> missing) {
            JsonNode acceptance = flowCapabilityContextReopenAcceptance;
            require(missing, acceptance != null,
                    "capability context reopen acceptance result");
            String firstSessionId = acceptance == null
                    ? "" : text(acceptance, "firstSessionId");
            String reopenedSessionId = acceptance == null
                    ? "" : text(acceptance, "reopenedSessionId");
            String thirdSessionId = acceptance == null
                    ? "" : text(acceptance, "thirdSessionId");
            if (acceptance != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode", "rootRendered",
                        "flowClientOwned", "samePublicId", "differentSession",
                        "threeDistinctSessionsObserved",
                        "threeDistinctWindowIdentitiesObserved",
                        "threeDistinctWebViewIdentitiesObserved",
                        "firstContextReleasedObserved",
                        "firstWindowHiddenObserved",
                        "reopenedContextReleasedObserved",
                        "reopenedWindowHiddenObserved",
                        "windowIdentityRecreatedObserved",
                        "webViewIdentityRecreatedObserved",
                        "firstCaptureSuccess", "retiredBeforeInvalidated",
                        "freshSuccess", "retiredAfterInvalidated",
                        "firstBeforeInvalidated",
                        "reopenedBeforeInvalidated", "thirdFreshSuccess",
                        "firstAfterInvalidated",
                        "reopenedAfterInvalidated",
                        "backgroundSessionAbsent",
                        "firstBackgroundSessionAbsent",
                        "reopenedBackgroundSessionAbsent",
                        "thirdBackgroundSessionAbsent",
                        "mainWindowRetainedObserved",
                        "mainWebViewRetainedObserved",
                        "mainProcessRetainedObserved",
                        "nativePointerObserved",
                        "nativePointerTrustedObserved",
                        "browserProgrammaticSetupObserved",
                        "balancedDrainObserved", "resultStableAfterDrain",
                        "errorFree")) {
                    require(missing, bool(acceptance, field),
                            "capability context reopen " + field);
                }
                require(missing,
                        contextReopenScope(
                                acceptance,
                                "firstWindowId", "firstSessionId", "firstUiId",
                                firstSessionId)
                                && contextReopenScope(
                                acceptance,
                                "reopenedWindowId", "reopenedSessionId",
                                "reopenedUiId", reopenedSessionId)
                                && contextReopenScope(
                                acceptance,
                                "thirdWindowId", "thirdSessionId",
                                "thirdUiId", thirdSessionId)
                                && validOwnerSessionId(firstSessionId)
                                && validOwnerSessionId(reopenedSessionId)
                                && validOwnerSessionId(thirdSessionId)
                                && !firstSessionId.equals(reopenedSessionId)
                                && !firstSessionId.equals(thirdSessionId)
                                && !reopenedSessionId.equals(thirdSessionId),
                        "same public window id with three distinct opaque sessions");
                require(missing,
                        "owner-window-closed".equals(text(
                                acceptance, "retiredBeforeReason"))
                                && "owner-window-closed".equals(text(
                                acceptance, "retiredAfterReason"))
                                && "owner-window-closed".equals(text(
                                acceptance, "firstBeforeReason"))
                                && "owner-window-closed".equals(text(
                                acceptance, "reopenedBeforeReason"))
                                && "owner-window-closed".equals(text(
                                acceptance, "firstAfterReason"))
                                && "owner-window-closed".equals(text(
                                acceptance, "reopenedAfterReason")),
                        "both retired contexts stay owner-window-closed around fresh use");
                require(missing,
                        "Flow capability context incarnation A".equals(text(
                                acceptance, "firstTitle"))
                                && "Flow capability context incarnation B".equals(
                                text(acceptance, "reopenedTitle"))
                                && "Flow capability context incarnation C".equals(
                                text(acceptance, "thirdTitle")),
                        "exact first, reopened and third native titles");
                require(missing,
                        expectedCapabilityContextFirstStatus().equals(text(
                                acceptance, "firstStatus"))
                                && expectedCapabilityContextReopenedStatus()
                                .equals(text(acceptance, "reopenedStatus"))
                                && expectedCapabilityContextThirdStatus()
                                .equals(text(acceptance, "thirdStatus")),
                        "exact Java three-incarnation capability-context status");
                require(missing,
                        acceptance.path("firstPushBaseline").asInt(-1) >= 0
                                && acceptance.path(
                                "firstPushMessageCount").asInt(-1)
                                > acceptance.path(
                                "firstPushBaseline").asInt(-1)
                                && acceptance.path(
                                "reopenedPushBaseline").asInt(-1) >= 0
                                && acceptance.path(
                                "reopenedPushMessageCount").asInt(-1)
                                > acceptance.path(
                                "reopenedPushBaseline").asInt(-1)
                                && acceptance.path(
                                "thirdPushBaseline").asInt(-1) >= 0
                                && acceptance.path(
                                "thirdPushMessageCount").asInt(-1)
                                > acceptance.path(
                                "thirdPushBaseline").asInt(-1),
                        "all three incarnations advance scoped push after background results");
                require(missing,
                        balancedCounts(acceptance,
                                "firstRequestCount", "firstResponseCount", 1)
                                && balancedCounts(acceptance,
                                "mainRequestCount", "mainResponseCount", 2)
                                && balancedCounts(acceptance,
                                "reopenedRequestCount",
                                "reopenedResponseCount", 1)
                                && balancedCounts(acceptance,
                                "thirdRequestCount",
                                "thirdResponseCount", 1),
                        "balanced first, main, reopened and third request drains");
                require(missing,
                        acceptance.path("nativePointerEventCount").asInt(-1) == 5
                                && acceptance.path(
                                "nativePointerTrustedEventCount").asInt(-1) == 5
                                && "first-capture,close-a,reopened-probe,close-b,third-probe".equals(
                                text(acceptance, "nativePointerStages")),
                        "five trusted capability-context pointer stages");
                require(missing,
                        "route-navigate,open-a,reopen-b,reopen-c".equals(text(
                                acceptance, "browserProgrammaticStages")),
                        "capability-context browser setup stages");
                require(missing,
                        acceptance.path("initialProcessIdentifier").asInt() > 0
                                && acceptance.path(
                                "initialProcessIdentifier").asInt()
                                == acceptance.path(
                                "currentProcessIdentifier").asInt()
                                && acceptance.path(
                                "recoveryGeneration").asInt(-1) == 0,
                        "capability-context retained sidecar generation");
            }

            List<DesktopCommandTrace> openCommands = desktopCommands.stream()
                    .filter(command -> "window.open".equals(command.command)
                            && "capability-reopen-secondary".equals(text(
                            command.args, "id")))
                    .toList();
            List<DesktopResultTrace> openResults = desktopResults.stream()
                    .filter(result -> "window.open".equals(result.command)
                            && "capability-reopen-secondary".equals(text(
                            result.payload, "windowId")))
                    .toList();
            List<DesktopCommandTrace> closeCommands = desktopCommands.stream()
                    .filter(command -> "window.close".equals(command.command)
                            && "capability-reopen-secondary".equals(text(
                            command.args, "id")))
                    .toList();
            List<DesktopResultTrace> closeResults = desktopResults.stream()
                    .filter(result -> "window.close".equals(result.command)
                            && "capability-reopen-secondary".equals(text(
                            result.payload, "windowId")))
                    .toList();
            List<DesktopCommandTrace> titleCommands = desktopCommands.stream()
                    .filter(command -> "window.setTitle".equals(command.command))
                    .toList();
            List<DesktopResultTrace> titleResults = desktopResults.stream()
                    .filter(result -> "window.setTitle".equals(result.command))
                    .toList();
            List<OrderedEventTrace> secondaryCreates = scopedEvents(
                    windowCreateEvents, "capability-reopen-secondary");
            List<OrderedEventTrace> secondaryCloseRequests = scopedEvents(
                    windowCloseRequests, "capability-reopen-secondary");
            List<OrderedEventTrace> secondaryWindowClosed = scopedEvents(
                    windowClosedEvents, "capability-reopen-secondary");
            List<OrderedEventTrace> mainCreates = scopedEvents(
                    windowCreateEvents, "main");

            require(missing, openCommands.size() == 3,
                    "exactly three same-id window.open commands");
            require(missing, openResults.size() == 3,
                    "exactly three same-id window.open results");
            require(missing, closeCommands.size() == 2,
                    "exactly two retired-incarnation window.close commands");
            require(missing, closeResults.size() == 2,
                    "exactly two retired-incarnation window.close results");
            require(missing, titleCommands.size() == 3,
                    "exactly three visible incarnation title commands");
            require(missing, titleResults.size() == 3,
                    "exactly three visible incarnation title results");
            require(missing, secondaryCreates.size() == 3,
                    "exactly three same-id native window creates");
            require(missing, secondaryCloseRequests.size() == 3,
                    "exactly three same-id native window close requests");
            require(missing, secondaryWindowClosed.size() == 3,
                    "exactly three same-id windowClosed envelopes");
            require(missing, mainCreates.size() == 1,
                    "one retained main native window create");
            require(missing, capabilityContextReopenPointerEvents.size() == 5,
                    "five capability-context native pointer dispatch traces");
            require(missing,
                    titleCommands.stream().allMatch(command -> Set.of(
                            "Flow capability context incarnation A",
                            "Flow capability context incarnation B",
                            "Flow capability context incarnation C")
                            .contains(text(command.args, "title"))),
                    "no retired capability-context title command reached the host");
            require(missing,
                    nativeCapabilityInvalidations.isEmpty()
                            && nativeCapabilityCompletionDrops.isEmpty()
                            && staleCapabilityResultDrops.isEmpty(),
                    "no native operation or result drop during reincarnation");
            require(missing,
                    sidecarLaunches.size() == 1
                            && sidecarStarts.size() == 1
                            && sidecarRecoveryReadyEvents.isEmpty()
                            && sidecarReplacementRequestedCount == 0,
                    "one uninterrupted capability-context sidecar generation");

            if (acceptance == null || openCommands.size() != 3
                    || openResults.size() != 3 || closeCommands.size() != 2
                    || closeResults.size() != 2 || titleCommands.size() != 3
                    || titleResults.size() != 3 || secondaryCreates.size() != 3
                    || secondaryCloseRequests.size() != 3
                    || secondaryWindowClosed.size() != 3
                    || mainCreates.size() != 1
                    || capabilityContextReopenPointerEvents.size() != 5) {
                return;
            }

            DesktopCommandTrace firstOpen = openCommands.get(0);
            DesktopCommandTrace reopenedOpen = openCommands.get(1);
            DesktopCommandTrace thirdOpen = openCommands.get(2);
            DesktopResultTrace firstOpenResult = correlatedResult(
                    firstOpen, openResults);
            DesktopResultTrace reopenedOpenResult = correlatedResult(
                    reopenedOpen, openResults);
            DesktopResultTrace thirdOpenResult = correlatedResult(
                    thirdOpen, openResults);
            DesktopCommandTrace firstCloseCommand = closeCommands.get(0);
            DesktopCommandTrace reopenedCloseCommand = closeCommands.get(1);
            DesktopResultTrace firstCloseResult = correlatedResult(
                    firstCloseCommand, closeResults);
            DesktopResultTrace reopenedCloseResult = correlatedResult(
                    reopenedCloseCommand, closeResults);
            DesktopCommandTrace firstTitle = titleCommand(
                    titleCommands, "Flow capability context incarnation A");
            DesktopCommandTrace reopenedTitle = titleCommand(
                    titleCommands, "Flow capability context incarnation B");
            DesktopCommandTrace thirdTitle = titleCommand(
                    titleCommands, "Flow capability context incarnation C");
            DesktopResultTrace firstTitleResult = correlatedResult(
                    firstTitle, titleResults);
            DesktopResultTrace reopenedTitleResult = correlatedResult(
                    reopenedTitle, titleResults);
            DesktopResultTrace thirdTitleResult = correlatedResult(
                    thirdTitle, titleResults);
            OrderedEventTrace firstCreate = secondaryCreates.get(0);
            OrderedEventTrace reopenedCreate = secondaryCreates.get(1);
            OrderedEventTrace thirdCreate = secondaryCreates.get(2);
            OrderedEventTrace firstCloseRequest = scopedLifecycleEvent(
                    windowCloseRequests, firstSessionId, true);
            OrderedEventTrace firstWindowClosed = scopedLifecycleEvent(
                    windowClosedEvents, firstSessionId, true);
            OrderedEventTrace reopenedCloseRequest = scopedLifecycleEvent(
                    windowCloseRequests, reopenedSessionId, true);
            OrderedEventTrace reopenedWindowClosed = scopedLifecycleEvent(
                    windowClosedEvents, reopenedSessionId, true);
            OrderedEventTrace thirdCloseRequest = scopedLifecycleEvent(
                    windowCloseRequests, thirdSessionId, true);
            OrderedEventTrace thirdWindowClosed = scopedLifecycleEvent(
                    windowClosedEvents, thirdSessionId, true);
            OrderedEventTrace firstPointer = uniqueStageEvent(
                    capabilityContextReopenPointerEvents, "first-capture");
            OrderedEventTrace closePointer = uniqueStageEvent(
                    capabilityContextReopenPointerEvents, "close-a");
            OrderedEventTrace reopenedPointer = uniqueStageEvent(
                    capabilityContextReopenPointerEvents, "reopened-probe");
            OrderedEventTrace reopenedClosePointer = uniqueStageEvent(
                    capabilityContextReopenPointerEvents, "close-b");
            OrderedEventTrace thirdPointer = uniqueStageEvent(
                    capabilityContextReopenPointerEvents, "third-probe");

            require(missing,
                    firstOpenResult != null && reopenedOpenResult != null
                            && thirdOpenResult != null
                            && firstCloseResult != null
                            && reopenedCloseResult != null
                            && firstTitle != null && reopenedTitle != null
                            && thirdTitle != null
                            && firstTitleResult != null
                            && reopenedTitleResult != null
                            && thirdTitleResult != null,
                    "correlated result for every reincarnation command");
            require(missing,
                    firstCloseRequest != null && firstWindowClosed != null
                            && reopenedCloseRequest != null
                            && reopenedWindowClosed != null
                            && thirdCloseRequest != null
                            && thirdWindowClosed != null,
                    "exact close lifecycle for all three native incarnations");
            require(missing,
                    firstPointer != null && closePointer != null
                            && reopenedPointer != null
                            && reopenedClosePointer != null
                            && thirdPointer != null,
                    "one pointer trace for each reincarnation stage");
            if (firstOpenResult == null || reopenedOpenResult == null
                    || thirdOpenResult == null || firstCloseResult == null
                    || reopenedCloseResult == null || firstTitle == null
                    || reopenedTitle == null || thirdTitle == null
                    || firstTitleResult == null
                    || reopenedTitleResult == null
                    || thirdTitleResult == null || firstCloseRequest == null
                    || firstWindowClosed == null || reopenedCloseRequest == null
                    || reopenedWindowClosed == null
                    || thirdCloseRequest == null || thirdWindowClosed == null
                    || firstPointer == null || closePointer == null
                    || reopenedPointer == null || reopenedClosePointer == null
                    || thirdPointer == null) {
                return;
            }

            require(missing,
                    exactContextReopenOpenCommand(firstOpen)
                            && exactContextReopenOpenCommand(reopenedOpen)
                            && exactContextReopenOpenCommand(thirdOpen)
                            && exactContextReopenOpenResult(firstOpenResult)
                            && exactContextReopenOpenResult(reopenedOpenResult)
                            && exactContextReopenOpenResult(thirdOpenResult)
                            && correlated(firstOpen, firstOpenResult)
                            && correlated(reopenedOpen, reopenedOpenResult)
                            && correlated(thirdOpen, thirdOpenResult),
                    "exact same-id open command and result pairs");
            require(missing,
                    exactContextReopenCloseCommand(firstCloseCommand)
                            && exactContextReopenCloseCommand(
                            reopenedCloseCommand)
                            && exactContextReopenCloseResult(firstCloseResult)
                            && exactContextReopenCloseResult(
                            reopenedCloseResult)
                            && correlated(
                            firstCloseCommand, firstCloseResult)
                            && correlated(
                            reopenedCloseCommand, reopenedCloseResult),
                    "exact retired-incarnation close command and results");
            require(missing,
                    exactContextReopenCreate(firstCreate, firstSessionId)
                            && exactContextReopenCreate(
                            reopenedCreate, reopenedSessionId)
                            && exactContextReopenCreate(
                            thirdCreate, thirdSessionId),
                    "exact three distinct same-id native window creates");
            require(missing,
                    exactContextReopenTitleCommand(
                            firstTitle, firstSessionId,
                            "Flow capability context incarnation A")
                            && exactContextReopenTitleCommand(
                            reopenedTitle, reopenedSessionId,
                            "Flow capability context incarnation B")
                            && exactContextReopenTitleCommand(
                            thirdTitle, thirdSessionId,
                            "Flow capability context incarnation C")
                            && exactContextReopenTitleResult(
                            firstTitleResult,
                            "Flow capability context incarnation A")
                            && exactContextReopenTitleResult(
                            reopenedTitleResult,
                            "Flow capability context incarnation B")
                            && exactContextReopenTitleResult(
                            thirdTitleResult,
                            "Flow capability context incarnation C")
                            && correlated(firstTitle, firstTitleResult)
                            && correlated(reopenedTitle, reopenedTitleResult)
                            && correlated(thirdTitle, thirdTitleResult),
                    "exact scoped title command/result for all incarnations");
            require(missing,
                    exactContextReopenLifecycle(
                            firstCloseRequest, firstSessionId, false)
                            && exactContextReopenLifecycle(
                            firstWindowClosed, firstSessionId, true)
                            && exactContextReopenLifecycle(
                            reopenedCloseRequest, reopenedSessionId, false)
                            && exactContextReopenLifecycle(
                            reopenedWindowClosed, reopenedSessionId, true)
                            && exactContextReopenLifecycle(
                            thirdCloseRequest, thirdSessionId, false)
                            && exactContextReopenLifecycle(
                            thirdWindowClosed, thirdSessionId, true),
                    "exact first, reopened and third window close scopes");
            require(missing,
                    exactContextReopenPointer(
                            firstPointer, "first-capture", firstSessionId)
                            && exactContextReopenPointer(
                            closePointer, "close-a", "flow-ipc-session")
                            && exactContextReopenPointer(
                            reopenedPointer, "reopened-probe",
                            reopenedSessionId)
                            && exactContextReopenPointer(
                            reopenedClosePointer, "close-b",
                            "flow-ipc-session")
                            && exactContextReopenPointer(
                            thirdPointer, "third-probe", thirdSessionId),
                    "exact scoped trusted reincarnation pointer events");

            List<PushDeliveryTrace> firstResultPushes = acknowledgedPushes(
                    firstSessionId,
                    firstTitleResult.order,
                    firstCloseCommand.order);
            List<PushDeliveryTrace> reopenedResultPushes = acknowledgedPushes(
                    reopenedSessionId,
                    reopenedTitleResult.order,
                    reopenedCloseCommand.order);
            List<PushDeliveryTrace> thirdResultPushes = acknowledgedPushes(
                    thirdSessionId,
                    thirdTitleResult.order,
                    flowCapabilityContextReopenAcceptanceOrder);
            require(missing, !firstResultPushes.isEmpty(),
                    "first incarnation scoped acknowledged result push");
            require(missing, !reopenedResultPushes.isEmpty(),
                    "reopened incarnation scoped acknowledged result push");
            require(missing, !thirdResultPushes.isEmpty(),
                    "third incarnation scoped acknowledged result push");
            require(missing,
                    firstOpen.order < firstCreate.order
                            && firstCreate.order < firstOpenResult.order
                            && firstOpenResult.order < firstPointer.order
                            && firstPointer.order < firstTitle.order
                            && firstTitle.order < firstTitleResult.order
                            && firstResultPushes.stream().allMatch(push ->
                            firstTitleResult.order < push.deliveryOrder
                                    && push.acknowledgementOrder
                                    < closePointer.order)
                            && closePointer.order < firstCloseCommand.order
                            && firstCloseCommand.order < firstCloseResult.order
                            && firstCloseResult.order < firstCloseRequest.order
                            && firstCloseRequest.order < firstWindowClosed.order
                            && firstWindowClosed.order < reopenedOpen.order
                            && reopenedOpen.order < reopenedCreate.order
                            && reopenedCreate.order < reopenedOpenResult.order
                            && reopenedOpenResult.order < reopenedPointer.order
                            && reopenedPointer.order < reopenedTitle.order
                            && reopenedTitle.order < reopenedTitleResult.order
                            && reopenedResultPushes.stream().allMatch(push ->
                            reopenedTitleResult.order < push.deliveryOrder
                                    && push.acknowledgementOrder
                                    < reopenedClosePointer.order)
                            && reopenedClosePointer.order
                            < reopenedCloseCommand.order
                            && reopenedCloseCommand.order
                            < reopenedCloseResult.order
                            && reopenedCloseResult.order
                            < reopenedCloseRequest.order
                            && reopenedCloseRequest.order
                            < reopenedWindowClosed.order
                            && reopenedWindowClosed.order < thirdOpen.order
                            && thirdOpen.order < thirdCreate.order
                            && thirdCreate.order < thirdOpenResult.order
                            && thirdOpenResult.order < thirdPointer.order
                            && thirdPointer.order < thirdTitle.order
                            && thirdTitle.order < thirdTitleResult.order
                            && thirdResultPushes.stream().allMatch(push ->
                            thirdTitleResult.order < push.deliveryOrder
                                    && push.acknowledgementOrder
                                    < flowCapabilityContextReopenAcceptanceOrder)
                            && flowCapabilityContextReopenAcceptanceOrder
                            < thirdCloseRequest.order
                            && thirdCloseRequest.order
                            < thirdWindowClosed.order,
                    "same-id repeated close, reincarnation and fresh-result order");
            require(missing,
                    shutdownSidecarCount == 1
                            && gracefulShutdownSidecarOrder
                            > thirdWindowClosed.order,
                    "one graceful shutdown after the third incarnation closes");
        }

        private List<String> flowRetiredScopeProductionHostMissing() {
            List<String> missing = new ArrayList<>();
            List<OrderedEventTrace> productionHostReadyEvents =
                    sidecarReadyEvents.stream()
                            .filter(TraceFacts::exactRetiredScopeProductionHostReady)
                            .toList();
            require(missing, standardLaunch, "standard flow-ipc launch");
            require(missing,
                    sidecarLaunches.size() == 1
                            && sidecarStarts.size() == 1
                            && productionHostReadyEvents.size() == 1
                            && exactSidecarLaunch(sidecarLaunches.get(0), 1)
                            && exactSidecarStart(sidecarStarts.get(0), 1)
                            && exactRetiredScopeProductionHostReady(
                            productionHostReadyEvents.get(0)),
                    "one production-host sidecar generation and ready");
            require(missing,
                    sidecarRecoveryScheduledAttempts.isEmpty()
                            && sidecarRecoveryReadyEvents.isEmpty()
                            && sidecarRecoveryStabilityDeadlineCount == 0
                            && sidecarRecoveryBudgetReset == null
                            && sidecarReplacementRequestedCount == 0
                            && sidecarReplacementReadyCount == 0
                            && sidecarReplacementFailed == null
                            && sidecarRollbackReady == null
                            && !hostControlReceived
                            && !hostRollbackControlReceived,
                    "no sidecar recovery or replacement");
            require(missing,
                    !errorObserved
                            && nativeCapabilityInvalidations.isEmpty()
                            && nativeCapabilityCompletionDrops.isEmpty()
                            && staleCapabilityResultDrops.isEmpty()
                            && noRetiredScopeProductionHostForbiddenType(),
                    "no unknown delivery stale or lifecycle errors");

            List<OrderedEventTrace> mainCreates = scopedEvents(
                    windowCreateEvents, "main");
            List<OrderedEventTrace> secondaryCreates = scopedEvents(
                    windowCreateEvents, "capability-reopen-secondary");
            require(missing, mainCreates.size() == 1,
                    "one main production-host window create");
            require(missing, secondaryCreates.size() == 3,
                    "three same-id production-host window creates");
            if (mainCreates.size() != 1 || secondaryCreates.size() != 3) {
                return missing;
            }

            OrderedEventTrace mainCreate = mainCreates.get(0);
            OrderedEventTrace firstCreate = secondaryCreates.get(0);
            OrderedEventTrace secondCreate = secondaryCreates.get(1);
            OrderedEventTrace thirdCreate = secondaryCreates.get(2);
            String firstSessionId = text(firstCreate.payload, "sessionId");
            String secondSessionId = text(secondCreate.payload, "sessionId");
            String thirdSessionId = text(thirdCreate.payload, "sessionId");
            require(missing,
                    exactRetiredScopeProductionHostCreate(
                            mainCreate, "main", "flow-ipc-session", "main")
                            && exactRetiredScopeProductionHostCreate(
                            firstCreate, "capability-reopen-secondary",
                            firstSessionId, "capability-reopen-secondary")
                            && exactRetiredScopeProductionHostCreate(
                            secondCreate, "capability-reopen-secondary",
                            secondSessionId, "capability-reopen-secondary")
                            && exactRetiredScopeProductionHostCreate(
                            thirdCreate, "capability-reopen-secondary",
                            thirdSessionId, "capability-reopen-secondary"),
                    "exact main and three secondary create scopes");
            require(missing,
                    validOwnerSessionId(firstSessionId)
                            && validOwnerSessionId(secondSessionId)
                            && validOwnerSessionId(thirdSessionId)
                            && new java.util.HashSet<>(List.of(
                            firstSessionId, secondSessionId,
                            thirdSessionId)).size() == 3,
                    "three pairwise-distinct host UUID sessions");

            OrderedEventTrace mainWindowReady = uniqueLifecycleEvent(
                    windowReadyEvents, "main", "flow-ipc-session", "main");
            OrderedEventTrace firstWindowReady = uniqueLifecycleEvent(
                    windowReadyEvents, "capability-reopen-secondary",
                    firstSessionId, "capability-reopen-secondary");
            OrderedEventTrace secondWindowReady = uniqueLifecycleEvent(
                    windowReadyEvents, "capability-reopen-secondary",
                    secondSessionId, "capability-reopen-secondary");
            OrderedEventTrace thirdWindowReady = uniqueLifecycleEvent(
                    windowReadyEvents, "capability-reopen-secondary",
                    thirdSessionId, "capability-reopen-secondary");
            OrderedEventTrace mainWebViewLoaded = uniqueLifecycleEvent(
                    webViewLoadedEvents, "main", "flow-ipc-session", "main");
            OrderedEventTrace firstWebViewLoaded = uniqueLifecycleEvent(
                    webViewLoadedEvents, "capability-reopen-secondary",
                    firstSessionId, "capability-reopen-secondary");
            OrderedEventTrace secondWebViewLoaded = uniqueLifecycleEvent(
                    webViewLoadedEvents, "capability-reopen-secondary",
                    secondSessionId, "capability-reopen-secondary");
            OrderedEventTrace thirdWebViewLoaded = uniqueLifecycleEvent(
                    webViewLoadedEvents, "capability-reopen-secondary",
                    thirdSessionId, "capability-reopen-secondary");
            long rootResourceCount = standardBundleResourceEvents.stream()
                    .filter(TraceFacts::exactRetiredScopeProductionHostResource)
                    .filter(event -> "/".equals(text(event.payload, "path")))
                    .count();
            long javascriptResourceCount = standardBundleResourceEvents.stream()
                    .filter(TraceFacts::exactRetiredScopeProductionHostResource)
                    .filter(event -> text(event.payload, "path")
                            .startsWith("/VAADIN/build/"))
                    .filter(event -> text(event.payload, "path")
                            .endsWith(".js"))
                    .count();
            require(missing,
                    flowWebAppReadyEvents.size() == 4
                            && flowWebAppReadyEvents.stream().allMatch(
                            TraceFacts::exactRetiredScopeProductionHostWebAppReady)
                            && standardBundleReadyEvents.size() == 4
                            && standardBundleReadyEvents.stream().allMatch(
                            TraceFacts::exactRetiredScopeProductionHostBundleReady)
                            && standardBundleResourceEvents.stream().allMatch(
                            TraceFacts::exactRetiredScopeProductionHostResource)
                            && rootResourceCount == 4
                            && javascriptResourceCount >= 4
                            && windowReadyEvents.size() == 4
                            && exactRetiredScopeProductionHostWindowReady(
                            mainWindowReady, "main", "flow-ipc-session", "main")
                            && exactRetiredScopeProductionHostWindowReady(
                            firstWindowReady, "capability-reopen-secondary",
                            firstSessionId, "capability-reopen-secondary")
                            && exactRetiredScopeProductionHostWindowReady(
                            secondWindowReady, "capability-reopen-secondary",
                            secondSessionId, "capability-reopen-secondary")
                            && exactRetiredScopeProductionHostWindowReady(
                            thirdWindowReady, "capability-reopen-secondary",
                            thirdSessionId, "capability-reopen-secondary")
                            && webViewLoadedEvents.size() == 4
                            && exactRetiredScopeProductionHostWebViewLoaded(
                            mainWebViewLoaded, "main", "flow-ipc-session", "main")
                            && exactRetiredScopeProductionHostWebViewLoaded(
                            firstWebViewLoaded, "capability-reopen-secondary",
                            firstSessionId, "capability-reopen-secondary")
                            && exactRetiredScopeProductionHostWebViewLoaded(
                            secondWebViewLoaded, "capability-reopen-secondary",
                            secondSessionId, "capability-reopen-secondary")
                            && exactRetiredScopeProductionHostWebViewLoaded(
                            thirdWebViewLoaded, "capability-reopen-secondary",
                            thirdSessionId, "capability-reopen-secondary"),
                    "four production standard-bundle WebView readiness groups");
            if (mainWindowReady == null || firstWindowReady == null
                    || secondWindowReady == null || thirdWindowReady == null
                    || mainWebViewLoaded == null || firstWebViewLoaded == null
                    || secondWebViewLoaded == null
                    || thirdWebViewLoaded == null) {
                return missing;
            }

            List<DesktopCommandTrace> openCommands = desktopCommands.stream()
                    .filter(command -> "window.open".equals(command.command)
                            && "capability-reopen-secondary".equals(text(
                            command.args, "id")))
                    .toList();
            List<DesktopResultTrace> openResults = desktopResults.stream()
                    .filter(result -> "window.open".equals(result.command)
                            && "capability-reopen-secondary".equals(text(
                            result.payload, "windowId")))
                    .toList();
            List<DesktopCommandTrace> closeCommands = desktopCommands.stream()
                    .filter(command -> "window.close".equals(command.command)
                            && Set.of("capability-reopen-secondary", "main")
                            .contains(text(command.args, "id")))
                    .toList();
            List<DesktopResultTrace> closeResults = desktopResults.stream()
                    .filter(result -> "window.close".equals(result.command)
                            && Set.of("capability-reopen-secondary", "main")
                            .contains(text(result.payload, "windowId")))
                    .toList();
            require(missing,
                    openCommands.size() == 3 && openResults.size() == 3,
                    "three exact correlated production-host opens");
            require(missing,
                    closeCommands.size() == 4 && closeResults.size() == 4,
                    "four exact correlated production-host closes");
            if (openCommands.size() != 3 || openResults.size() != 3
                    || closeCommands.size() != 4
                    || closeResults.size() != 4) {
                return missing;
            }
            DesktopCommandTrace firstOpenCommand = openCommands.get(0);
            DesktopCommandTrace secondOpenCommand = openCommands.get(1);
            DesktopCommandTrace thirdOpenCommand = openCommands.get(2);
            DesktopResultTrace firstOpenResult = correlatedResult(
                    firstOpenCommand, openResults);
            DesktopResultTrace secondOpenResult = correlatedResult(
                    secondOpenCommand, openResults);
            DesktopResultTrace thirdOpenResult = correlatedResult(
                    thirdOpenCommand, openResults);
            DesktopCommandTrace firstCloseCommand = closeCommands.get(0);
            DesktopCommandTrace secondCloseCommand = closeCommands.get(1);
            DesktopCommandTrace thirdCloseCommand = closeCommands.get(2);
            DesktopCommandTrace mainCloseCommand = closeCommands.get(3);
            DesktopResultTrace firstCloseResult = correlatedResult(
                    firstCloseCommand, closeResults);
            DesktopResultTrace secondCloseResult = correlatedResult(
                    secondCloseCommand, closeResults);
            DesktopResultTrace thirdCloseResult = correlatedResult(
                    thirdCloseCommand, closeResults);
            DesktopResultTrace mainCloseResult = correlatedResult(
                    mainCloseCommand, closeResults);
            require(missing,
                    exactRetiredScopeOpenPair(
                            firstOpenCommand, firstOpenResult)
                            && exactRetiredScopeOpenPair(
                            secondOpenCommand, secondOpenResult)
                            && exactRetiredScopeOpenPair(
                            thirdOpenCommand, thirdOpenResult),
                    "three exact correlated production-host opens");
            require(missing,
                    exactRetiredScopeClosePair(
                            firstCloseCommand, firstCloseResult,
                            "capability-reopen-secondary")
                            && exactRetiredScopeClosePair(
                            secondCloseCommand, secondCloseResult,
                            "capability-reopen-secondary")
                            && exactRetiredScopeClosePair(
                            thirdCloseCommand, thirdCloseResult,
                            "capability-reopen-secondary")
                            && exactRetiredScopeClosePair(
                            mainCloseCommand, mainCloseResult, "main"),
                    "four exact correlated production-host closes");
            if (firstOpenResult == null || secondOpenResult == null
                    || thirdOpenResult == null || firstCloseResult == null
                    || secondCloseResult == null || thirdCloseResult == null
                    || mainCloseResult == null) {
                return missing;
            }

            OrderedEventTrace firstCloseRequest = uniqueLifecycleEvent(
                    windowCloseRequests,
                    "capability-reopen-secondary", firstSessionId,
                    "capability-reopen-secondary");
            OrderedEventTrace firstWindowClosed = uniqueLifecycleEvent(
                    windowClosedEvents,
                    "capability-reopen-secondary", firstSessionId,
                    "capability-reopen-secondary");
            OrderedEventTrace secondCloseRequest = uniqueLifecycleEvent(
                    windowCloseRequests,
                    "capability-reopen-secondary", secondSessionId,
                    "capability-reopen-secondary");
            OrderedEventTrace secondWindowClosed = uniqueLifecycleEvent(
                    windowClosedEvents,
                    "capability-reopen-secondary", secondSessionId,
                    "capability-reopen-secondary");
            OrderedEventTrace thirdCloseRequest = uniqueLifecycleEvent(
                    windowCloseRequests,
                    "capability-reopen-secondary", thirdSessionId,
                    "capability-reopen-secondary");
            OrderedEventTrace thirdWindowClosed = uniqueLifecycleEvent(
                    windowClosedEvents,
                    "capability-reopen-secondary", thirdSessionId,
                    "capability-reopen-secondary");
            OrderedEventTrace mainCloseRequest = uniqueLifecycleEvent(
                    windowCloseRequests,
                    "main", "flow-ipc-session", "main");
            OrderedEventTrace mainWindowClosed = uniqueLifecycleEvent(
                    windowClosedEvents,
                    "main", "flow-ipc-session", "main");
            require(missing,
                    exactRetiredScopeProductionHostLifecycle(
                            firstCloseRequest, false)
                            && exactRetiredScopeProductionHostLifecycle(
                            firstWindowClosed, true)
                            && exactRetiredScopeProductionHostLifecycle(
                            secondCloseRequest, false)
                            && exactRetiredScopeProductionHostLifecycle(
                            secondWindowClosed, true)
                            && exactRetiredScopeProductionHostLifecycle(
                            thirdCloseRequest, false)
                            && exactRetiredScopeProductionHostLifecycle(
                            thirdWindowClosed, true)
                            && exactRetiredScopeProductionHostLifecycle(
                            mainCloseRequest, false)
                            && exactRetiredScopeProductionHostLifecycle(
                            mainWindowClosed, true),
                    "exact A B C and main close lifecycle scopes");
            if (firstCloseRequest == null || firstWindowClosed == null
                    || secondCloseRequest == null
                    || secondWindowClosed == null
                    || thirdCloseRequest == null
                    || thirdWindowClosed == null
                    || mainCloseRequest == null || mainWindowClosed == null) {
                return missing;
            }
            require(missing,
                    mainCreate.order < mainWindowReady.order
                            && mainWindowReady.order < mainWebViewLoaded.order
                            && mainWebViewLoaded.order < mainCloseCommand.order
                            && firstCreate.order < firstWindowReady.order
                            && firstWindowReady.order < firstWebViewLoaded.order
                            && firstWebViewLoaded.order < firstCloseCommand.order
                            && secondCreate.order < secondWindowReady.order
                            && secondWindowReady.order < secondWebViewLoaded.order
                            && secondWebViewLoaded.order < secondCloseCommand.order
                            && thirdCreate.order < thirdWindowReady.order
                            && thirdWindowReady.order < thirdWebViewLoaded.order
                            && thirdWebViewLoaded.order < thirdCloseCommand.order,
                    "production standard-bundle readiness precedes every close");
            require(missing,
                    mainCreate.order < firstOpenCommand.order
                            && firstOpenCommand.order < firstCreate.order
                            && firstCreate.order < firstOpenResult.order
                            && firstOpenResult.order < firstCloseCommand.order
                            && firstCloseCommand.order < firstCloseResult.order
                            && firstCloseResult.order < firstCloseRequest.order
                            && firstCloseRequest.order < firstWindowClosed.order
                            && firstWindowClosed.order < secondOpenCommand.order
                            && secondOpenCommand.order < secondCreate.order
                            && secondCreate.order < secondOpenResult.order
                            && secondOpenResult.order < secondCloseCommand.order
                            && secondCloseCommand.order < secondCloseResult.order
                            && secondCloseResult.order < secondCloseRequest.order
                            && secondCloseRequest.order < secondWindowClosed.order,
                    "strict A then B retirement order");

            DesktopCommandTrace firstRetiredCommand = uniqueTitleCommand(
                    firstSessionId);
            DesktopCommandTrace secondRetiredCommand = uniqueTitleCommand(
                    secondSessionId);
            DesktopCommandTrace thirdLiveCommand = uniqueTitleCommand(
                    thirdSessionId);
            DesktopResultTrace firstRetiredResult = uniqueTitleResult(
                    firstSessionId);
            DesktopResultTrace secondRetiredResult = uniqueTitleResult(
                    secondSessionId);
            DesktopResultTrace thirdLiveResult = uniqueTitleResult(
                    thirdSessionId);
            OrderedEventTrace firstRejection = uniqueRetiredCommandRejection(
                    firstSessionId);
            OrderedEventTrace secondRejection = uniqueRetiredCommandRejection(
                    secondSessionId);
            require(missing,
                    exactRetiredScopeCommand(
                            firstRetiredCommand, firstSessionId)
                            && exactRetiredScopeCommand(
                            secondRetiredCommand, secondSessionId)
                            && exactRetiredScopeCommand(
                            thirdLiveCommand, thirdSessionId),
                    "exact A B retired and C live setTitle commands");
            require(missing,
                    exactRetiredScopeCommandRejection(
                            firstRejection, firstRetiredCommand)
                            && exactRetiredScopeCommandRejection(
                            secondRejection, secondRetiredCommand),
                    "scope-exact retired command rejections");
            require(missing,
                    exactRetiredScopeTypedResult(
                            firstRetiredCommand, firstRetiredResult)
                            && exactRetiredScopeTypedResult(
                            secondRetiredCommand, secondRetiredResult),
                    "scope-correlated owner-window-closed typed results");
            require(missing,
                    exactRetiredScopeLiveResult(
                            thirdLiveCommand, thirdLiveResult),
                    "scope-correlated successful C setTitle result");
            require(missing,
                    closedWindowCapabilityCommandRejections.size() == 2,
                    "exactly two retired command rejections");
            if (firstRetiredCommand == null || secondRetiredCommand == null
                    || thirdLiveCommand == null || firstRetiredResult == null
                    || secondRetiredResult == null || thirdLiveResult == null
                    || firstRejection == null || secondRejection == null) {
                return missing;
            }

            RetiredTransportProbe firstProbe = retiredTransportProbe(
                    firstSessionId, firstCloseRequest.order,
                    secondWindowClosed.order, thirdCreate.order);
            RetiredTransportProbe secondProbe = retiredTransportProbe(
                    secondSessionId, secondCloseRequest.order,
                    secondWindowClosed.order, thirdCreate.order);
            require(missing,
                    firstProbe != null && firstProbe.exact(),
                    "A exact retired HTTP and push inputs and drops");
            require(missing,
                    secondProbe != null && secondProbe.exact(),
                    "B exact retired HTTP and push inputs and drops");
            require(missing,
                    flowIpcClosedWindowEnvelopeDrops.size() == 4,
                    "exactly four retired transport drops");

            LiveTransportProbe liveProbe = liveTransportProbe(
                    thirdSessionId,
                    thirdCreate.order,
                    thirdCloseRequest.order);
            require(missing,
                    liveProbe != null && liveProbe.exact(),
                    "C scope-correlated streamed response credit chunk and end");
            require(missing,
                    flowIpcClosedWindowEnvelopeDrops.stream().noneMatch(
                            event -> thirdSessionId.equals(text(
                                    event.payload, "sessionId"))),
                    "C transport is not classified as retired");

            int lastRetiredProbeOrder = Math.max(
                    Math.max(firstRejection.order, secondRejection.order),
                    Math.max(firstRetiredResult.order,
                            secondRetiredResult.order));
            if (firstProbe != null) {
                lastRetiredProbeOrder = Math.max(
                        lastRetiredProbeOrder, firstProbe.lastOrder());
            }
            if (secondProbe != null) {
                lastRetiredProbeOrder = Math.max(
                        lastRetiredProbeOrder, secondProbe.lastOrder());
            }
            require(missing,
                    secondWindowClosed.order < firstRetiredCommand.order
                            && secondWindowClosed.order
                            < secondRetiredCommand.order
                            && firstRetiredCommand.order < firstRejection.order
                            && firstRejection.order < firstRetiredResult.order
                            && secondRetiredCommand.order
                            < secondRejection.order
                            && secondRejection.order
                            < secondRetiredResult.order
                            && lastRetiredProbeOrder < thirdOpenCommand.order
                            && thirdOpenCommand.order < thirdCreate.order
                            && thirdCreate.order < thirdOpenResult.order,
                    "retire A and B probe both then create C order");
            require(missing,
                    thirdOpenResult.order < thirdLiveCommand.order
                            && thirdLiveCommand.order < thirdLiveResult.order
                            && thirdLiveResult.order < thirdCloseCommand.order
                            && thirdCloseCommand.order < thirdCloseResult.order
                            && thirdCloseResult.order < thirdCloseRequest.order
                            && (liveProbe == null
                            || thirdCreate.order < liveProbe.firstOrder()
                            && liveProbe.lastOrder()
                            < thirdCloseRequest.order)
                            && thirdCloseRequest.order
                            < thirdWindowClosed.order
                            && thirdWindowClosed.order < mainCloseCommand.order
                            && mainCloseCommand.order < mainCloseResult.order
                            && mainCloseResult.order < mainCloseRequest.order
                            && mainCloseRequest.order < mainWindowClosed.order,
                    "fresh C health then C and main close order");
            require(missing,
                    shutdownSidecarCount == 1
                            && gracefulShutdownSidecarOrder
                            > mainWindowClosed.order,
                    "one graceful shutdown after main windowClosed");
            return missing;
        }

        private boolean noRetiredScopeProductionHostForbiddenType() {
            for (String type : List.of(
                    "staleCapabilityCommandDropped",
                    "windowClosedDropped",
                    "window.closeDropped",
                    "sidecar.protocolRejected",
                    "sidecar.recoveryScheduled",
                    "sidecar.recoveryReady",
                    "sidecar.replacementRequested",
                    "sidecar.replacementReady",
                    "sidecar.replacementFailed",
                    "sidecar.rollbackReady")) {
                if (typeCounts.getOrDefault(type, 0) > 0) {
                    return false;
                }
            }
            return true;
        }

        private static boolean exactRetiredScopeProductionHostReady(
                OrderedEventTrace event) {
            if (event == null || !event.traceShape) {
                return false;
            }
            JsonNode envelope = event.payload.path("envelope");
            return "java-sidecar".equals(text(event.payload, "source"))
                    && "flow-ipc".equals(text(event.payload, "transport"))
                    && event.payload.path("sidecarGeneration").asInt(-1) == 1
                    && envelope.path("version").asInt(-1) == 1
                    && "ready".equals(text(envelope, "type"))
                    && "main".equals(text(envelope, "windowId"))
                    && "flow-ipc-session".equals(text(
                    envelope, "sessionId"))
                    && "main".equals(text(envelope, "uiId"))
                    && envelope.path("error").isNull();
        }

