        private RetiredTransportProbe retiredTransportProbe(
                String sessionId,
                int closeRequestOrder,
                int bothRetiredOrder,
                int freshCreateOrder) {
            FlowIpcEnvelopeTrace response = uniqueProductionHostEnvelope(
                    "opaqueHttpStreamResponse", "recv",
                    "capability-reopen-secondary", sessionId,
                    "capability-reopen-secondary", null);
            FlowIpcEnvelopeTrace push = uniqueProductionHostEnvelope(
                    "opaquePush", "recv",
                    "capability-reopen-secondary", sessionId,
                    "capability-reopen-secondary", null);
            OrderedEventTrace responseDrop = uniqueRetiredTransportDrop(
                    sessionId, "opaqueHttpStreamResponse");
            OrderedEventTrace pushDrop = uniqueRetiredTransportDrop(
                    sessionId, "opaquePush");
            if (response == null || push == null
                    || responseDrop == null || pushDrop == null) {
                return null;
            }
            boolean matchingOpen = retiredScopeProductionHostEnvelopes.stream()
                    .anyMatch(event -> "opaqueHttpStreamOpen".equals(
                            event.type)
                            && "send".equals(event.direction)
                            && event.traceShape
                            && response.windowId.equals(event.windowId)
                            && response.sessionId.equals(event.sessionId)
                            && response.uiId.equals(event.uiId)
                            && response.requestId.equals(event.requestId)
                            && event.order < closeRequestOrder);
            boolean exact = response.traceShape && push.traceShape
                    && !response.requestId.isBlank()
                    && response.payload.path("status").isNumber()
                    && matchingOpen
                    && exactRetiredTransportDrop(
                    responseDrop, response, "opaqueHttpStreamResponse")
                    && exactRetiredTransportDrop(
                    pushDrop, push, "opaquePush")
                    && bothRetiredOrder < response.order
                    && bothRetiredOrder < push.order
                    && responseDrop.order < freshCreateOrder
                    && pushDrop.order < freshCreateOrder;
            return new RetiredTransportProbe(
                    response.order,
                    push.order,
                    responseDrop.order,
                    pushDrop.order,
                    exact);
        }

        private OrderedEventTrace uniqueRetiredTransportDrop(
                String sessionId,
                String type) {
            OrderedEventTrace match = null;
            for (OrderedEventTrace event
                    : flowIpcClosedWindowEnvelopeDrops) {
                if (!type.equals(text(event.payload, "type"))
                        || !"capability-reopen-secondary".equals(text(
                        event.payload, "windowId"))
                        || !sessionId.equals(text(
                        event.payload, "sessionId"))
                        || !"capability-reopen-secondary".equals(text(
                        event.payload, "uiId"))) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = event;
            }
            return match;
        }

        private static boolean exactRetiredTransportDrop(
                OrderedEventTrace drop,
                FlowIpcEnvelopeTrace input,
                String type) {
            return drop.traceShape
                    && drop.payload.isObject()
                    && drop.payload.size() == 4
                    && type.equals(text(drop.payload, "type"))
                    && input.windowId.equals(text(
                    drop.payload, "windowId"))
                    && input.sessionId.equals(text(
                    drop.payload, "sessionId"))
                    && input.uiId.equals(text(drop.payload, "uiId"))
                    && input.order < drop.order;
        }

        private LiveTransportProbe liveTransportProbe(
                String sessionId,
                int afterOrder,
                int beforeOrder) {
            List<FlowIpcEnvelopeTrace> responses =
                    productionHostEnvelopes(
                            "opaqueHttpStreamResponse", "recv",
                            "capability-reopen-secondary", sessionId,
                            "capability-reopen-secondary");
            if (responses.size() != 1) {
                return null;
            }
            FlowIpcEnvelopeTrace response = responses.get(0);
            List<FlowIpcEnvelopeTrace> opens = productionHostEnvelopes(
                    "opaqueHttpStreamOpen", "send", response.windowId,
                    response.sessionId, response.uiId).stream()
                    .filter(event -> response.requestId.equals(
                            event.requestId))
                    .filter(event -> event.order < response.order)
                    .toList();
            List<FlowIpcEnvelopeTrace> credits = productionHostEnvelopes(
                    "opaqueHttpStreamResponseCredit", "send",
                    response.windowId, response.sessionId,
                    response.uiId).stream()
                    .filter(event -> response.requestId.equals(
                            event.requestId))
                    .toList();
            List<FlowIpcEnvelopeTrace> chunks = productionHostEnvelopes(
                    "opaqueHttpStreamResponseChunk", "recv",
                    response.windowId, response.sessionId,
                    response.uiId).stream()
                    .filter(event -> response.requestId.equals(
                            event.requestId))
                    .toList();
            List<FlowIpcEnvelopeTrace> ends = productionHostEnvelopes(
                    "opaqueHttpStreamResponseEnd", "recv",
                    response.windowId, response.sessionId,
                    response.uiId).stream()
                    .filter(event -> response.requestId.equals(
                            event.requestId))
                    .toList();
            if (opens.isEmpty() || credits.isEmpty()
                    || chunks.isEmpty() || ends.size() != 1) {
                return null;
            }
            FlowIpcEnvelopeTrace firstCredit = credits.stream()
                    .filter(event -> event.order > response.order)
                    .findFirst().orElse(null);
            FlowIpcEnvelopeTrace firstChunk = chunks.get(0);
            FlowIpcEnvelopeTrace end = ends.get(0);
            if (firstCredit == null) {
                return null;
            }
            long chunkBytes = chunks.stream().mapToLong(event ->
                    event.payload.path("bodyBytes").asLong(-1)).sum();
            boolean exact = response.traceShape
                    && response.payload.path("status").asInt(-1) == 200
                    && !response.requestId.isBlank()
                    && opens.stream().allMatch(event -> event.traceShape)
                    && credits.stream().allMatch(event -> event.traceShape
                    && event.payload.path("credit").asInt() > 0)
                    && chunks.stream().allMatch(event -> event.traceShape
                    && event.payload.path("bodyBytes").asLong(-1) > 0)
                    && end.traceShape
                    && end.payload.path("bodyBytes").asLong(-1)
                    == chunkBytes
                    && afterOrder < opens.get(0).order
                    && opens.get(0).order < response.order
                    && response.order < firstCredit.order
                    && firstCredit.order < firstChunk.order
                    && chunks.stream().allMatch(event ->
                    firstCredit.order < event.order
                            && event.order < end.order)
                    && end.order < beforeOrder;
            return new LiveTransportProbe(
                    opens.get(0).order,
                    end.order,
                    exact);
        }

        private FlowIpcEnvelopeTrace uniqueProductionHostEnvelope(
                String type,
                String direction,
                String windowId,
                String sessionId,
                String uiId,
                String requestId) {
            List<FlowIpcEnvelopeTrace> events = productionHostEnvelopes(
                    type, direction, windowId, sessionId, uiId).stream()
                    .filter(event -> requestId == null
                            || requestId.equals(event.requestId))
                    .toList();
            return events.size() == 1 ? events.get(0) : null;
        }

        private List<FlowIpcEnvelopeTrace> productionHostEnvelopes(
                String type,
                String direction,
                String windowId,
                String sessionId,
                String uiId) {
            return retiredScopeProductionHostEnvelopes.stream()
                    .filter(event -> type.equals(event.type)
                            && direction.equals(event.direction)
                            && windowId.equals(event.windowId)
                            && sessionId.equals(event.sessionId)
                            && uiId.equals(event.uiId))
                    .toList();
        }

        private record RetiredTransportProbe(
                int responseOrder,
                int pushOrder,
                int responseDropOrder,
                int pushDropOrder,
                boolean exact) {
            private int lastOrder() {
                return Math.max(
                        Math.max(responseOrder, pushOrder),
                        Math.max(responseDropOrder, pushDropOrder));
            }
        }

        private record LiveTransportProbe(
                int firstOrder,
                int lastOrder,
                boolean exact) {
        }

        private List<PushDeliveryTrace> acknowledgedPushes(
                String sessionId,
                int afterOrder,
                int beforeOrder) {
            return pushDeliveries.values().stream()
                    .filter(delivery -> delivery.scope.contains(
                            "\u0000capability-reopen-secondary\u0000"
                                    + sessionId
                                    + "\u0000capability-reopen-secondary\u0000")
                            && delivery.deliveryOrder > afterOrder
                            && delivery.acknowledgementOrder
                            > delivery.deliveryOrder
                            && delivery.acknowledgementOrder < beforeOrder
                            && delivery.scope.equals(
                            delivery.acknowledgementScope))
                    .toList();
        }

        private static boolean balancedCounts(
                JsonNode payload,
                String requestField,
                String responseField,
                int minimum) {
            int requests = payload.path(requestField).asInt(-1);
            return requests >= minimum
                    && requests == payload.path(responseField).asInt(-2);
        }

