        private void requireSandboxGrantPushDelivery(List<String> missing, OrderedEventTrace acceptance) {
            require(missing, navigationTimeoutInteger(acceptance.payload, "mainPushCount", pushDeliveries.size())
                            && pushDeliveryScopeConsistent, "sandbox DOM counts distinct reliably delivered pushes");
            for (Map.Entry<SidecarPushKey, PushDeliveryTrace> entry : pushDeliveries.entrySet()) {
                SidecarPushKey key = entry.getKey();
                PushDeliveryTrace delivery = entry.getValue();
                List<OrderedEventTrace> attempts = sandboxGrantPushes.stream().filter(event ->
                        pushScope(event.payload).equals(key.scope) && event.payload.path("pushSequence").asLong(-1) == key.sequence).toList();
                List<OrderedEventTrace> acknowledgements = sandboxGrantPushAcks.stream().filter(event ->
                        pushScope(event.payload).equals(key.scope) && event.payload.path("pushSequence").asLong(-1) == key.sequence).toList();
                require(missing, key.generation == 1 && key.sequence > 0 && !attempts.isEmpty()
                                && attempts.size() == delivery.maxDeliveryAttempt && acknowledgements.size() == attempts.size(),
                        "sandbox reliable push has exact generation and consecutive attempts with acknowledgements");
                if (attempts.isEmpty() || acknowledgements.size() != attempts.size()) continue;
                for (int index = 0; index < attempts.size(); index++) {
                    OrderedEventTrace attempt = attempts.get(index), ack = acknowledgements.get(index);
                    // The bridge emits ACK immediately after invoking Flow's onMessage;
                    // its lastSeen snapshot may precede asynchronous patch application.
                    // Typed DOM receipts and final stable state prove this gate's UI
                    // completion, not draining the separate reliable-push retry queue.
                    // A retry already in flight can reach the host before the prior
                    // ACK. Preserve ordinal delivery-before-ACK causality without
                    // requiring alternating delivery and acknowledgement events.
                    require(missing, navigationTimeoutInteger(attempt.payload, "deliveryAttempt", index + 1)
                                    && navigationTimeoutInteger(attempt.payload, "flowServerSyncId", delivery.flowServerSyncId)
                                    && navigationTimeoutInteger(attempt.payload, "uidlBytes", delivery.uidlBytes)
                                    && navigationTimeoutInteger(ack.payload, "flowServerSyncId", delivery.flowServerSyncId)
                                    && ack.payload.path("lastSeenServerSyncId").isIntegralNumber()
                                    && ack.payload.path("lastSeenServerSyncId").canConvertToInt()
                                    && ack.payload.path("lastSeenServerSyncId").asInt(-2) >= -1
                                    && attempt.order < ack.order,
                            "sandbox same-sequence retry preserves payload identity and ordered transport acknowledgements");
                }
            }
        }

