        private static boolean exactTextArray(
                JsonNode array, List<String> expected) {
            if (!array.isArray() || array.size() != expected.size()) {
                return false;
            }
            for (int index = 0; index < expected.size(); index++) {
                if (!expected.get(index).equals(array.path(index).asText())) {
                    return false;
                }
            }
            return true;
        }

