        private static OrderedEventTrace uniqueScopedEvent(
                List<OrderedEventTrace> events,
                String windowId,
                String sessionId,
                String uiId) {
            OrderedEventTrace match = null;
            for (OrderedEventTrace event : events) {
                if (!windowId.equals(text(event.payload, "windowId"))
                        || !sessionId.equals(text(event.payload, "sessionId"))
                        || !uiId.equals(text(event.payload, "uiId"))) {
                    continue;
                }
                if (match != null || !event.traceShape) {
                    return null;
                }
                match = event;
            }
            return match;
        }

        private void requireFlowClipboardOutcomes(List<String> missing) {
            JsonNode acceptance = flowClipboardOutcomesAcceptance;
            int firstCommandOrder = desktopCommands.stream()
                    .filter(command -> command.command.startsWith("clipboard."))
                    .mapToInt(command -> command.order).min().orElse(messageCount);
            String mainCommands = permissionManifestCommands("main", firstCommandOrder, missing);
            require(missing, List.of(mainCommands.split(",")).containsAll(
                    List.of("clipboard.readText", "clipboard.writeText")),
                    "clipboard main manifest grants read and write");
            require(missing, acceptance != null,
                    "clipboard outcomes acceptance result");
            if (acceptance != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode", "rootRendered",
                        "flowClientOwned", "opaqueRequestObserved",
                        "opaqueResponseObserved",
                        "mainNoTextOutcomeObserved",
                        "mainEmptyWriteOutcomeObserved",
                        "mainEmptyReadOutcomeObserved",
                        "secondaryDeniedWriteOutcomeObserved",
                        "secondaryDeniedReadOutcomeObserved",
                        "nativeSnapshotCapturedObserved",
                        "nativeNoTextSetupObserved",
                        "nativeNoTextReadNoSideEffectObserved",
                        "nativeEmptyTextObserved",
                        "nativeDeniedNoSideEffectObserved",
                        "nativeOwnershipTrackedObserved",
                        "nativeSnapshotRestoredObserved",
                        "scopeIsolatedObserved", "nativePointerObserved",
                        "nativePointerTrustedObserved",
                        "browserProgrammaticSetupObserved",
                        "semanticUidlCheckpointsObserved",
                        "balancedDrainObserved", "resultStableAfterDrain",
                        "errorFree")) {
                    require(missing, bool(acceptance, field),
                            "clipboard outcomes " + field);
                }
                requireClipboardContention(acceptance, missing);
                require(missing,
                        acceptance.path("pushObserved").isBoolean()
                                && !acceptance.path("pushObserved").asBoolean(),
                        "clipboard outcomes completed through UIDL without push");
                String secondarySessionId = text(
                        acceptance, "secondarySessionId");
                require(missing,
                        mainScope(acceptance,
                                "mainWindowId", "mainSessionId", "mainUiId")
                                && "clipboard-outcomes-secondary".equals(text(
                                acceptance, "secondaryWindowId"))
                                && validOwnerSessionId(secondarySessionId)
                                && "clipboard-outcomes-secondary".equals(text(
                                acceptance, "secondaryUiId"))
                                && !secondarySessionId.equals(text(
                                acceptance, "mainSessionId")),
                        "clipboard outcomes exact isolated scopes");
                require(missing,
                        expectedClipboardNoTextStatus().equals(text(
                                acceptance, "noTextStatus"))
                                && expectedClipboardEmptyStatus().equals(text(
                                acceptance, "emptyStatus"))
                                && expectedClipboardDeniedStatus().equals(text(
                                acceptance, "deniedStatus")),
                        "clipboard outcomes exact Java result statuses");
                require(missing,
                        acceptance.path("semanticUidlCheckpointCount")
                                .asInt(-1) == 3
                                && acceptance.path("deniedWriteProbeLength")
                                .asInt(-1) == CLIPBOARD_DENIED_PROBE.length()
                                && clipboardOutcomeStages().equals(text(
                                acceptance,
                                "semanticUidlCheckpointStages")),
                        "three clipboard semantic UIDL checkpoints");
                require(missing,
                        acceptance.path("nativePointerEventCount")
                                .asInt(-1) == 3
                                && acceptance.path(
                                "nativePointerTrustedEventCount")
                                .asInt(-1) == 3
                                && clipboardOutcomeStages().equals(text(
                                acceptance, "nativePointerStages")),
                        "clipboard outcomes trusted AppKit pointer stages");
                require(missing,
                        "route-navigate,secondary-open".equals(text(
                                acceptance, "browserProgrammaticStages")),
                        "clipboard outcomes browser-programmatic setup stages");
                int mainNoTextRequestBaseline = acceptance.path(
                        "mainNoTextRequestBaseline").asInt(-1);
                int mainNoTextResponseBaseline = acceptance.path(
                        "mainNoTextResponseBaseline").asInt(-1);
                int mainEmptyRequestBaseline = acceptance.path(
                        "mainEmptyRequestBaseline").asInt(-1);
                int mainEmptyResponseBaseline = acceptance.path(
                        "mainEmptyResponseBaseline").asInt(-1);
                int secondaryRequestBaseline = acceptance.path(
                        "secondaryRequestBaseline").asInt(-1);
                int secondaryResponseBaseline = acceptance.path(
                        "secondaryResponseBaseline").asInt(-1);
                int mainRequestCount = acceptance.path(
                        "mainRequestCount").asInt(-1);
                int mainResponseCount = acceptance.path(
                        "mainResponseCount").asInt(-1);
                int secondaryRequestCount = acceptance.path(
                        "secondaryRequestCount").asInt(-1);
                int secondaryResponseCount = acceptance.path(
                        "secondaryResponseCount").asInt(-1);
                require(missing,
                        mainNoTextRequestBaseline >= 0
                                && mainNoTextRequestBaseline
                                == mainNoTextResponseBaseline
                                && mainEmptyRequestBaseline
                                > mainNoTextRequestBaseline
                                && mainEmptyRequestBaseline
                                == mainEmptyResponseBaseline
                                && mainRequestCount > mainEmptyRequestBaseline
                                && mainRequestCount == mainResponseCount
                                && secondaryRequestBaseline >= 0
                                && secondaryRequestBaseline
                                == secondaryResponseBaseline
                                && secondaryRequestCount
                                > secondaryRequestBaseline
                                && secondaryRequestCount
                                == secondaryResponseCount,
                        "clipboard outcomes scoped UIDL request advances");
                require(missing,
                        acceptance.path("requestCount").asInt(-1)
                                == mainRequestCount + secondaryRequestCount
                                && acceptance.path("responseCount").asInt(-1)
                                == mainResponseCount + secondaryResponseCount
                                && acceptance.path("requestCount").asInt(-1)
                                == acceptance.path("responseCount").asInt(-2)
                                && acceptance.path("mainPushMessageCount")
                                .asInt(-1) >= 0
                                && acceptance.path("secondaryPushMessageCount")
                                .asInt(-1) >= 0,
                        "clipboard outcomes balanced scoped drain counts");
            }

            List<DesktopCommandTrace> commands = desktopCommands.stream()
                    .filter(command -> isClipboardCommand(command.command))
                    .toList();
            List<DesktopResultTrace> results = desktopResults.stream()
                    .filter(result -> isClipboardCommand(result.command))
                    .toList();
            int expectedCommands = bool(acceptance, "controlledContentionRequested") ? 7 : 5;
            require(missing, commands.size() == expectedCommands,
                    "exactly five clipboard outcome commands");
            require(missing, results.size() == expectedCommands,
                    "exactly five clipboard outcome results");
            require(missing,
                    results.stream().allMatch(DesktopResultTrace::traceShape),
                    "all clipboard results have exact Flow IPC trace shape");
            require(missing, clipboardOutcomesPointerEvents.size() == 3,
                    "three clipboard native pointer dispatch traces");
            require(missing, !clipboardDeniedProbeLeaked,
                    "clipboard denied probe never appears in the trace");
            require(missing, nativeCapabilityInvalidations.isEmpty(),
                    "no clipboard outcome operation invalidation");
            require(missing, nativeCapabilityCompletionDrops.isEmpty(),
                    "no clipboard outcome completion drop");
            require(missing, staleCapabilityResultDrops.isEmpty(),
                    "no clipboard outcome stale result drop");
            require(missing,
                    sidecarRecoveryScheduledAttempts.isEmpty()
                            && sidecarRecoveryReadyAttempts.isEmpty()
                            && sidecarRecoveryReadyEvents.isEmpty()
                            && sidecarReplacementRequestedCount == 0,
                    "no clipboard outcome replacement or recovery");

            OrderedEventTrace launch = uniqueGenerationEvent(
                    sidecarLaunches, 1);
            OrderedEventTrace start = uniqueGenerationEvent(sidecarStarts, 1);
            List<OrderedEventTrace> javaReadyEvents = sidecarReadyEvents.stream()
                    .filter(event -> "java-sidecar".equals(text(
                            event.payload, "source")))
                    .toList();
            OrderedEventTrace ready = javaReadyEvents.size() == 1
                    ? javaReadyEvents.getFirst() : null;
            require(missing,
                    sidecarLaunches.size() == 1 && launch != null
                            && exactSidecarLaunch(launch, 1),
                    "one clipboard outcome sidecar launch");
            require(missing,
                    sidecarStarts.size() == 1 && start != null
                            && exactSidecarStart(start, 1),
                    "one clipboard outcome sidecar start");
            require(missing,
                    javaReadyEvents.size() == 1 && ready != null
                            && ready.traceShape
                            && ready.payload.path(
                            "sidecarGeneration").asInt(-1) == 1
                            && "flow-ipc".equals(text(
                            ready.payload, "transport")),
                    "one clipboard outcome Java sidecar ready");

            if (commands.size() != expectedCommands || results.size() != expectedCommands
                    || clipboardOutcomesPointerEvents.size() != 3
                    || acceptance == null || launch == null || start == null
                    || ready == null) {
                return;
            }
            DesktopCommandTrace noTextRead = commands.get(0);
            DesktopCommandTrace emptyWrite = commands.get(1);
            DesktopCommandTrace emptyRead = commands.get(2);
            DesktopCommandTrace deniedWrite = commands.get(3);
            DesktopCommandTrace deniedRead = commands.get(4);
            DesktopResultTrace noTextResult = results.get(0);
            DesktopResultTrace emptyWriteResult = results.get(1);
            DesktopResultTrace emptyReadResult = results.get(2);
            DesktopResultTrace deniedWriteResult = results.get(3);
            DesktopResultTrace deniedReadResult = results.get(4);
            String secondarySessionId = text(
                    acceptance, "secondarySessionId");

            require(missing,
                    exactClipboardCommand(noTextRead,
                            "clipboard.readText", "main",
                            "flow-ipc-session", "main", -1)
                            && exactClipboardCommand(emptyWrite,
                            "clipboard.writeText", "main",
                            "flow-ipc-session", "main", 0)
                            && exactClipboardCommand(emptyRead,
                            "clipboard.readText", "main",
                            "flow-ipc-session", "main", -1)
                            && exactClipboardCommand(deniedWrite,
                            "clipboard.writeText",
                            "clipboard-outcomes-secondary",
                            secondarySessionId,
                            "clipboard-outcomes-secondary",
                            CLIPBOARD_DENIED_PROBE.length())
                            && exactClipboardCommand(deniedRead,
                            "clipboard.readText",
                            "clipboard-outcomes-secondary",
                            secondarySessionId,
                            "clipboard-outcomes-secondary", -1),
                    "exact ordered clipboard commands and redacted arguments");
            require(missing,
                    correlated(noTextRead, noTextResult)
                            && correlated(emptyWrite, emptyWriteResult)
                            && correlated(emptyRead, emptyReadResult)
                            && correlated(deniedWrite, deniedWriteResult)
                            && correlated(deniedRead, deniedReadResult)
                            && distinctCorrelations(commands),
                    "unique exact clipboard command/result correlations");
            require(missing,
                    exactNoTextClipboardPayload(noTextResult.payload, mainCommands),
                    "exact no-text clipboard result without redacted text");
            require(missing,
                    exactWrittenClipboardPayload(emptyWriteResult.payload, mainCommands),
                    "exact empty clipboard write result");
            require(missing,
                    exactEmptyTextClipboardPayload(emptyReadResult.payload, mainCommands),
                    "exact empty-text clipboard result with redacted text");
            require(missing,
                    exactDeniedClipboardPayload(
                            deniedWriteResult.payload,
                            "clipboard.writeText")
                            && exactDeniedClipboardPayload(
                            deniedReadResult.payload,
                            "clipboard.readText"),
                    "exact denied clipboard permission audit without side effect");

            OrderedEventTrace noTextPointer = uniqueStageEvent(
                    clipboardOutcomesPointerEvents, "main-no-text");
            OrderedEventTrace emptyPointer = uniqueStageEvent(
                    clipboardOutcomesPointerEvents, "main-empty");
            OrderedEventTrace deniedPointer = uniqueStageEvent(
                    clipboardOutcomesPointerEvents, "secondary-denied");
            require(missing,
                    exactClipboardPointer(noTextPointer, "main-no-text",
                            "main", "flow-ipc-session", "main")
                            && exactClipboardPointer(emptyPointer, "main-empty",
                            "main", "flow-ipc-session", "main")
                            && exactClipboardPointer(deniedPointer,
                            "secondary-denied",
                            "clipboard-outcomes-secondary",
                            secondarySessionId,
                            "clipboard-outcomes-secondary"),
                    "exact scoped clipboard native pointer dispatch stages");
            if (noTextPointer == null || emptyPointer == null
                    || deniedPointer == null) {
                return;
            }
            require(missing,
                    launch.order < start.order
                            && start.order < ready.order
                            && ready.order < noTextPointer.order
                            && noTextPointer.order < noTextRead.order
                            && noTextRead.order < noTextResult.order
                            && noTextResult.order < emptyPointer.order
                            && emptyPointer.order < emptyWrite.order
                            && emptyWrite.order < emptyWriteResult.order
                            && emptyWriteResult.order < emptyRead.order
                            && emptyRead.order < emptyReadResult.order
                            && emptyReadResult.order < deniedPointer.order
                            && deniedPointer.order < deniedWrite.order
                            && deniedWrite.order < deniedWriteResult.order
                            && deniedWriteResult.order < deniedRead.order
                            && deniedRead.order < deniedReadResult.order
                            && deniedReadResult.order
                            < flowClipboardOutcomesAcceptanceOrder,
                    "clipboard no-text, empty-text and denied operation order");
            require(missing,
                    commands.stream().allMatch(command -> command.order
                            < flowClipboardOutcomesAcceptanceOrder)
                            && results.stream().allMatch(result -> result.order
                            < flowClipboardOutcomesAcceptanceOrder),
                    "all clipboard commands and results before acceptance");
            require(missing,
                    shutdownSidecarCount == 1
                            && gracefulShutdownSidecarOrder
                            > flowClipboardOutcomesAcceptanceOrder,
                    "one graceful recv shutdown after clipboard outcomes acceptance");
        }

        private static boolean isClipboardCommand(String command) {
            return "clipboard.readText".equals(command)
                    || "clipboard.writeText".equals(command);
        }

        private static boolean exactClipboardCommand(
                DesktopCommandTrace command,
                String expectedCommand,
                String windowId,
                String sessionId,
                String uiId,
                int expectedTextLength) {
            boolean expectedArgs = "clipboard.readText".equals(expectedCommand)
                    ? command.args.isObject() && command.args.isEmpty()
                    : command.args.isObject() && command.args.size() == 2
                    && !command.args.has("text")
                    && command.args.path("textLength").asInt(-1)
                    == expectedTextLength
                    && bool(command.args, "textRedacted");
            return command.traceShape
                    && expectedCommand.equals(command.command)
                    && command.sidecarGeneration == 1
                    && !command.id.isBlank()
                    && command.id.equals(command.correlationId)
                    && windowId.equals(command.windowId)
                    && sessionId.equals(command.sessionId)
                    && uiId.equals(command.uiId)
                    && expectedArgs;
        }

        private static boolean distinctCorrelations(
                List<DesktopCommandTrace> commands) {
            Set<String> correlations = new java.util.HashSet<>();
            for (DesktopCommandTrace command : commands) {
                if (command.correlationId.isBlank()
                        || !correlations.add(command.correlationId)) {
                    return false;
                }
            }
            return true;
        }

        private void requireClipboardContention(JsonNode acceptance, List<String> missing) {
            if (!bool(acceptance, "controlledContentionRequested")) {
                require(missing, acceptance.path("nativePasteboardContendedObserved").isBoolean()
                                && !bool(acceptance, "nativePasteboardContendedObserved")
                                && clipboardContentionStarts.isEmpty() && clipboardContentionResults.isEmpty()
                                && clipboardContentionReads.isEmpty(),
                        "clipboard outcomes pasteboard remained uncontended");
                return;
            }
            require(missing, bool(acceptance, "nativePasteboardContendedObserved")
                            && clipboardContentionStarts.size() == 1 && clipboardContentionResults.size() == 1,
                    "clipboard controlled contention has one writer and result");
            if (clipboardContentionStarts.size() != 1 || clipboardContentionResults.size() != 1) return;
            OrderedEventTrace start = clipboardContentionStarts.getFirst();
            OrderedEventTrace result = clipboardContentionResults.getFirst();
            JsonNode p = result.payload;
            int before = p.path("beforeChangeCount").asInt(-1), cleared = p.path("clearedChangeCount").asInt(-1);
            int written = p.path("writtenChangeCount").asInt(-1), pid = p.path("processIdentifier").asInt(-1);
            List<DesktopCommandTrace> commands = desktopCommands.stream().filter(c -> isClipboardCommand(c.command)).toList();
            List<DesktopResultTrace> results = desktopResults.stream().filter(r -> isClipboardCommand(r.command)).toList();
            int lastCommandResult = results.size() >= 5 ? results.get(4).order : messageCount;
            require(missing, start.traceShape && result.traceShape && start.order > lastCommandResult
                            && result.order > start.order && result.order < flowClipboardOutcomesAcceptanceOrder
                            && pid > 0 && start.payload.path("processIdentifier").asInt(-1) == pid
                            && start.payload.path("ownedChangeCount").asInt(-1) == before
                            && p.equals(acceptance.path("controlledContention"))
                            && before >= 0 && cleared > before && written >= cleared
                            && p.path("writerExitStatus").asInt(-1) == 0 && bool(p, "fixtureMatches")
                            && p.path("oldOwnerRejectedAttempts").asInt(-1) == 2
                            && p.path("oldOwnerRestoreWrites").asInt(-1) == 0
                            && p.path("afterFirstRejectedChangeCount").asInt(-1) == written
                            && p.path("afterSecondRejectedChangeCount").asInt(-1) == written
                            && p.path("recoveryAttempts").asInt(-1) == 1
                            && p.path("freshReadAttempts").asInt(-1) == 2
                            && bool(p, "snapshotRestoredAndVerified")
                            && p.path("restoredChangeCount").asInt(-1) > written,
                    "clipboard controlled contention ordering, no-write retries and conditional verified recovery");
            require(missing, commands.size() == 7 && results.size() == 7 && clipboardContentionReads.size() == 2
                            && p.path("freshReadReceipts").isArray() && p.path("freshReadReceipts").size() == 2,
                    "clipboard contention has exactly two fresh public reads");
            if (commands.size() != 7 || results.size() != 7 || clipboardContentionReads.size() != 2) return;
            int previous = start.order;
            for (int i = 0; i < 2; i++) {
                DesktopCommandTrace c = commands.get(5 + i);
                DesktopResultTrace r = results.get(5 + i);
                OrderedEventTrace observed = clipboardContentionReads.get(i);
                JsonNode o = observed.payload;
                require(missing, exactClipboardCommand(c, "clipboard.readText", "main", "flow-ipc-session", "main", -1)
                                && correlated(c, r) && c.order > previous && observed.order > r.order
                                && observed.order < result.order && observed.traceShape && bool(r.payload, "success")
                                && bool(r.payload, "textPresent") && bool(r.payload, "textRedacted")
                                && r.payload.path("textLength").asInt(-1) == 20 && !r.payload.has("text")
                                && exactPermissionAudit(r.payload, "allowed", "manifest-allow", "window:main",
                                        permissionManifestCommands("main", c.order, missing))
                                && mainScope(o, "windowId", "sessionId", "uiId")
                                && o.path("attempt").asInt(-1) == i + 1
                                && "browser-programmatic-public-read".equals(text(o, "inputMode"))
                                && o.path("changeCount").asInt(-1) == written
                                && ("Clipboard no text: outcome=TEXT textPresent=true length=20 client=true count=" + (i + 2)).equals(text(o, "status"))
                                && o.path("requestCount").asInt(-1) > o.path("requestBaseline").asInt(-1)
                                && o.path("requestCount").asInt(-1) == o.path("responseCount").asInt(-2)
                                && o.equals(p.path("freshReadReceipts").path(i)),
                        "clipboard fresh read retry correlation, typed result and scoped UIDL");
                previous = observed.order;
            }
        }

