        private static DesktopCommandTrace fileDialogCommand(
                List<DesktopCommandTrace> commands,
                String title) {
            DesktopCommandTrace match = null;
            for (DesktopCommandTrace command : commands) {
                if (!title.equals(text(command.args, "title"))) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = command;
            }
            return match;
        }

        private static DesktopResultTrace correlatedResult(
                DesktopCommandTrace command,
                List<DesktopResultTrace> results) {
            if (command == null) {
                return null;
            }
            DesktopResultTrace match = null;
            for (DesktopResultTrace result : results) {
                if (!correlated(command, result)) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = result;
            }
            return match;
        }

