        private static boolean exactOwnerPointerEvent(
                OrderedEventTrace event,
                String stage,
                boolean owner,
                String ownerSessionId) {
            if (event == null || !event.traceShape
                    || !event.payload.isObject()
                    || !"appkit-window-pointer-event".equals(text(
                    event.payload, "inputMode"))
                    || !"primary".equals(text(event.payload, "button"))
                    || !stage.equals(text(event.payload, "stage"))
                    || !bool(event.payload, "activeApplication")
                    || !bool(event.payload, "keyWindow")
                    || !finiteCoordinate(event.payload, "webViewX")
                    || !finiteCoordinate(event.payload, "webViewY")
                    || !finiteCoordinate(event.payload, "windowX")
                    || !finiteCoordinate(event.payload, "windowY")) {
                return false;
            }
            return owner
                    ? ownerScope(event.payload,
                    "windowId", "sessionId", "uiId", ownerSessionId)
                    : mainScope(event.payload,
                    "windowId", "sessionId", "uiId");
        }

        private static boolean finiteCoordinate(
                JsonNode payload,
                String field) {
            return payload.path(field).isNumber()
                    && Double.isFinite(payload.path(field).asDouble());
        }

        private CapabilityGenerationCommandTrace capabilityGenerationCommand(
                int generation) {
            CapabilityGenerationCommandTrace match = null;
            for (CapabilityGenerationCommandTrace candidate
                    : capabilityGenerationCommands) {
                if (candidate.sidecarGeneration != generation) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = candidate;
            }
            return match;
        }

        private static List<OrderedEventTrace> capabilityOperationEvents(
                List<OrderedEventTrace> events) {
            return events.stream()
                    .filter(event -> "fileDialog.openFile".equals(text(
                            event.payload, "command")))
                    .toList();
        }

        private static OrderedEventTrace uniqueGenerationEvent(
                List<OrderedEventTrace> events,
                int generation) {
            OrderedEventTrace match = null;
            for (OrderedEventTrace event : events) {
                if (event.payload.path("generation").asInt(-1) != generation) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = event;
            }
            return match;
        }

        private OrderedEventTrace uniqueUnexpectedGenerationExit(
                int generation) {
            OrderedEventTrace match = null;
            for (OrderedEventTrace event : sidecarExits) {
                if (event.payload.path("generation").asInt(-1) != generation
                        || !event.payload.path("expected").isBoolean()
                        || event.payload.path("expected").asBoolean()) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = event;
            }
            return match;
        }

        private static boolean exactGenerationCommand(
                CapabilityGenerationCommandTrace command,
                int generation,
                String title) {
            return command.traceShape
                    && generation == command.sidecarGeneration
                    && "desktop-command-1".equals(command.id)
                    && command.id.equals(command.correlationId)
                    && "main".equals(command.windowId)
                    && "flow-ipc-session".equals(command.sessionId)
                    && "main".equals(command.uiId)
                    && title.equals(command.title);
        }

        private static boolean exactSidecarLaunch(
                OrderedEventTrace event,
                int generation) {
            return event.traceShape
                    && event.payload.path("generation").asInt(-1) == generation
                    && "flow-ipc".equals(text(event.payload, "transport"));
        }

        private static boolean exactSidecarStart(
                OrderedEventTrace event,
                int generation) {
            return exactSidecarLaunch(event, generation)
                    && event.payload.path("processIdentifier").asInt() > 0;
        }

        private static boolean correlated(
                CapabilityGenerationCommandTrace command,
                CapabilityGenerationResultTrace result) {
            return result.id.equals("capability-" + command.correlationId)
                    && result.correlationId.equals(command.correlationId)
                    && result.windowId.equals(command.windowId)
                    && result.sessionId.equals(command.sessionId)
                    && result.uiId.equals(command.uiId)
                    && result.order > command.order;
        }

        private static boolean emptyOrRedactedPanelPaths(JsonNode paths) {
            // Current production tracing redacts even an empty path list.
            // Outcome/selection state is independently checked in Java/UI receipts.
            return (paths.isArray() && paths.isEmpty())
                    || (paths.isTextual() && "[redacted]".equals(paths.asText()));
        }

