        private void acceptCapabilityPermissionCommand(
                JsonNode root,
                JsonNode payload) {
            JsonNode envelope = payload.path("envelope");
            JsonNode commandPayload = envelope.path("payload");
            if (!"window.setTitle".equals(text(commandPayload, "command"))) {
                return;
            }
            capabilityPermissionCommands.add(new CapabilityPermissionCommandTrace(
                    text(envelope, "id"),
                    text(envelope, "correlationId"),
                    text(envelope, "windowId"),
                    text(envelope, "sessionId"),
                    text(envelope, "uiId"),
                    text(commandPayload.path("args"), "title"),
                    messageCount,
                    "recv".equals(text(root, "direction"))
                            && "java-sidecar".equals(text(payload, "source"))
                            && "flow-ipc".equals(text(payload, "transport"))
                            && envelope.path("version").asInt(-1) == 1
                            && "command".equals(text(envelope, "type"))));
        }

        private void acceptCapabilityPermissionResult(
                JsonNode root,
                JsonNode payload) {
            JsonNode envelope = payload.path("envelope");
            JsonNode resultPayload = envelope.path("payload");
            String outerCommand = text(payload, "command");
            String resultCommand = text(resultPayload, "command");
            if (!"window.setTitle".equals(outerCommand)
                    && !"window.setTitle".equals(resultCommand)) {
                return;
            }
            capabilityPermissionResults.add(new CapabilityPermissionResultTrace(
                    text(envelope, "id"),
                    text(envelope, "correlationId"),
                    text(envelope, "windowId"),
                    text(envelope, "sessionId"),
                    text(envelope, "uiId"),
                    resultPayload,
                    messageCount,
                    "send".equals(text(root, "direction"))
                            && "java-sidecar".equals(text(payload, "target"))
                            && "flow-ipc".equals(text(payload, "transport"))
                            && "window.setTitle".equals(outerCommand)
                            && envelope.path("version").asInt(-1) == 1
                            && "capabilityResult".equals(text(envelope, "type"))
                            && envelope.path("error").isNull()));
        }

        private void requireFlowCapabilityPermission(List<String> missing) {
            JsonNode acceptance = flowCapabilityPermissionAcceptance;
            require(missing, acceptance != null,
                    "capability permission acceptance result");
            if (acceptance != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode",
                        "mainFlowClientOwned", "secondaryFlowClientOwned",
                        "mainOpaqueRequestObserved", "mainOpaqueResponseObserved",
                        "secondaryOpaqueRequestObserved",
                        "secondaryOpaqueResponseObserved",
                        "mainJavaListenerObserved", "secondaryJavaListenerObserved",
                        "mainUidlPatchObserved", "secondaryUidlPatchObserved",
                        "mainAllowedResultObserved", "secondaryDeniedResultObserved",
                        "mainTitleAppliedObserved", "secondaryTitleUnchangedObserved",
                        "permissionPayloadPreservedObserved",
                        "scopeIsolationObserved", "nativePointerObserved",
                        "nativePointerTrustedObserved",
                        "browserProgrammaticSetupObserved", "errorFree")) {
                    require(missing, bool(acceptance, field),
                            "capability permission " + field);
                }
                require(missing,
                        "main".equals(text(acceptance, "mainWindowId"))
                                && "permission-secondary".equals(
                                text(acceptance, "secondaryWindowId"))
                                && "window.setTitle".equals(
                                text(acceptance, "command"))
                                && "manifest-enforced".equals(
                                text(acceptance, "permissionMode")),
                        "capability permission acceptance identity");
                require(missing,
                        "allowed".equals(text(
                                acceptance, "mainPermissionDecision"))
                                && "manifest-allow".equals(text(
                                acceptance, "mainPermissionReason"))
                                && "window:main".equals(text(
                                acceptance, "mainPermissionScope")),
                        "capability permission main acceptance decision");
                require(missing,
                        "denied".equals(text(
                                acceptance, "secondaryPermissionDecision"))
                                && "manifest-denied".equals(text(
                                acceptance, "secondaryPermissionReason"))
                                && "window:permission-secondary".equals(text(
                                acceptance, "secondaryPermissionScope")),
                        "capability permission secondary acceptance decision");
                require(missing,
                        acceptance.path("nativePointerEventCount").asInt(-1) == 2
                                && acceptance.path("nativePointerTrustedEventCount")
                                .asInt(-1) == 2
                                && "main-invoke,secondary-invoke".equals(
                                text(acceptance, "nativePointerStages")),
                        "capability permission trusted native pointer stages");
                String browserStages = text(
                        acceptance, "browserProgrammaticStages");
                require(missing,
                        "navigate,open-secondary".equals(browserStages)
                                && !browserStages.contains("invoke"),
                        "capability permission browser-programmatic setup stages");
                String expectedMainStatus = "Capability permission result: "
                        + "success=true error=none permissionMode=manifest-enforced "
                        + "permissionDecision=allowed permissionReason=manifest-allow "
                        + "permissionScope=window:main command=window.setTitle "
                        + "client=true change=1";
                String expectedSecondaryStatus = "Capability permission result: "
                        + "success=false error=Command not allowed by "
                        + "desktop-capabilities.json permissionMode=manifest-enforced "
                        + "permissionDecision=denied permissionReason=manifest-denied "
                        + "permissionScope=window:permission-secondary "
                        + "command=window.setTitle client=true change=1";
                require(missing,
                        expectedMainStatus.equals(text(acceptance, "mainStatus"))
                                && expectedSecondaryStatus.equals(
                                text(acceptance, "secondaryStatus")),
                        "capability permission exact Java result status");
                require(missing,
                        "Capability permission allowed title".equals(
                                text(acceptance, "mainNativeTitle"))
                                && "Capability permission secondary".equals(
                                text(acceptance, "secondaryInitialNativeTitle"))
                                && "Capability permission secondary".equals(
                                text(acceptance, "secondaryFinalNativeTitle")),
                        "capability permission native title side effects");
            }

            require(missing, capabilityPermissionCommands.size() == 2,
                    "two full window.setTitle command traces");
            require(missing, capabilityPermissionResults.size() == 2,
                    "two full window.setTitle capability results");
            CapabilityPermissionCommandTrace mainCommand =
                    capabilityCommand("main");
            CapabilityPermissionCommandTrace secondaryCommand =
                    capabilityCommand("permission-secondary");
            CapabilityPermissionResultTrace mainResult =
                    capabilityResult("main");
            CapabilityPermissionResultTrace secondaryResult =
                    capabilityResult("permission-secondary");
            require(missing, mainCommand != null && secondaryCommand != null,
                    "one command per capability permission window");
            require(missing, mainResult != null && secondaryResult != null,
                    "one result per capability permission window");
            if (mainCommand == null || secondaryCommand == null
                    || mainResult == null || secondaryResult == null) {
                return;
            }

            require(missing,
                    mainCommand.traceShape && secondaryCommand.traceShape
                            && mainResult.traceShape && secondaryResult.traceShape,
                    "full command/result transport trace shape");
            require(missing,
                    "Capability permission allowed title".equals(mainCommand.title)
                            && mainCommand.title.equals(secondaryCommand.title),
                    "identical scoped window.setTitle command arguments");
            require(missing,
                    correlated(mainCommand, mainResult)
                            && correlated(secondaryCommand, secondaryResult)
                            && !mainCommand.correlationId.equals(
                            secondaryCommand.correlationId),
                    "dynamic command/result correlation, scope and order");
            require(missing,
                    !mainCommand.sessionId.isBlank()
                            && !secondaryCommand.sessionId.isBlank()
                            && !mainCommand.sessionId.equals(
                            secondaryCommand.sessionId)
                            && !mainCommand.uiId.isBlank()
                            && !secondaryCommand.uiId.isBlank()
                            && !mainCommand.uiId.equals(secondaryCommand.uiId),
                    "distinct main and secondary Flow IPC scopes");
            if (acceptance != null) {
                require(missing,
                        mainCommand.windowId.equals(text(
                                acceptance, "mainWindowId"))
                                && mainCommand.sessionId.equals(text(
                                acceptance, "mainSessionId"))
                                && mainCommand.uiId.equals(text(
                                acceptance, "mainUiId"))
                                && secondaryCommand.windowId.equals(text(
                                acceptance, "secondaryWindowId"))
                                && secondaryCommand.sessionId.equals(text(
                                acceptance, "secondarySessionId"))
                                && secondaryCommand.uiId.equals(text(
                                acceptance, "secondaryUiId")),
                        "acceptance and command scope correlation");
            }
            String mainGrants = permissionManifestCommands("main", mainCommand.order, missing);
            String secondaryGrants = permissionManifestCommands("permission-secondary", secondaryCommand.order, missing);
            require(missing, List.of(mainGrants.split(",")).contains("window.setTitle")
                            && !List.of(secondaryGrants.split(",")).contains("window.setTitle")
                            && !List.of(secondaryGrants.split(",")).contains("*"),
                    "loaded manifest independently allows main and denies secondary title");
            require(missing, exactAllowedPermissionPayload(mainResult.payload, mainGrants),
                    "exact main allowed permission payload");
            require(missing, exactDeniedPermissionPayload(secondaryResult.payload, secondaryGrants),
                    "exact secondary denied permission payload");
            require(missing,
                    flowCapabilityPermissionAcceptanceOrder > mainResult.order
                            && flowCapabilityPermissionAcceptanceOrder
                            > secondaryResult.order,
                    "capability results precede acceptance completion");
        }

        private void requireFlowCapabilityDefaultDeny(List<String> missing) {
            JsonNode acceptance = flowCapabilityDefaultDenyAcceptance;
            require(missing, acceptance != null,
                    "capability default-deny acceptance result");
            if (acceptance != null) {
                for (String field : List.of(
                        "complete", "standardBundleMode", "rootRendered",
                        "flowClientOwned", "opaqueRequestObserved",
                        "opaqueResponseObserved", "javaListenerObserved",
                        "uidlPatchObserved", "deniedResultObserved",
                        "titleUnchangedObserved",
                        "permissionPayloadPreservedObserved", "scopeObserved",
                        "nativePointerObserved", "nativePointerTrustedObserved",
                        "browserProgrammaticSetupObserved",
                        "balancedDrainObserved", "manifestFallbackObserved",
                        "errorFree")) {
                    require(missing, bool(acceptance, field),
                            "capability default-deny " + field);
                }
                require(missing,
                        acceptance.path("pushObserved").isBoolean()
                                && !acceptance.path("pushObserved").asBoolean(),
                        "capability default-deny focused push boundary");
                require(missing,
                        "main".equals(text(acceptance, "windowId"))
                                && !text(acceptance, "sessionId").isBlank()
                                && "main".equals(text(acceptance, "uiId"))
                                && "window.setTitle".equals(
                                text(acceptance, "command")),
                        "capability default-deny acceptance identity");
                require(missing,
                        "manifest-enforced".equals(text(
                                acceptance, "permissionMode"))
                                && "denied".equals(text(
                                acceptance, "permissionDecision"))
                                && "manifest-denied".equals(text(
                                acceptance, "permissionReason"))
                                && "window:main".equals(text(
                                acceptance, "permissionScope"))
                                && bool(acceptance, "permissionManifestLoaded")
                                && "$APP/Contents/Resources/desktop-capabilities.json"
                                .equals(text(
                                        acceptance,
                                        "permissionManifestPath"))
                                && text(acceptance,
                                "permissionManifestCommands").isEmpty(),
                        "capability default-deny empty enforced manifest");
                String expectedStatus = "Capability permission result: "
                        + "success=false error=Command not allowed by "
                        + "desktop-capabilities.json permissionMode=manifest-enforced "
                        + "permissionDecision=denied permissionReason=manifest-denied "
                        + "permissionScope=window:main command=window.setTitle "
                        + "client=true change=1";
                require(missing,
                        expectedStatus.equals(text(acceptance, "status")),
                        "capability default-deny exact Java result status");
                require(missing,
                        "Flow IPC Framework App".equals(text(
                                acceptance, "initialNativeTitle"))
                                && "Flow IPC Framework App".equals(text(
                                acceptance, "finalNativeTitle")),
                        "capability default-deny unchanged native title");
                require(missing,
                        acceptance.path("nativePointerEventCount").asInt(-1) == 1
                                && acceptance.path("nativePointerTrustedEventCount")
                                .asInt(-1) == 1
                                && "invoke".equals(text(
                                acceptance, "nativePointerStages")),
                        "capability default-deny trusted native pointer stage");
                String browserStages = text(
                        acceptance, "browserProgrammaticStages");
                require(missing,
                        "navigate".equals(browserStages)
                                && !browserStages.contains("invoke"),
                        "capability default-deny browser-programmatic setup stage");
            }

            require(missing, capabilityPermissionCommands.size() == 1,
                    "one full default-deny window.setTitle command trace");
            require(missing, capabilityPermissionResults.size() == 1,
                    "one full default-deny window.setTitle capability result");
            require(missing, capabilityManifests.size() == 1,
                    "one default-deny capability manifest trace");
            if (capabilityPermissionCommands.size() != 1
                    || capabilityPermissionResults.size() != 1
                    || capabilityManifests.size() != 1) {
                return;
            }
            CapabilityPermissionCommandTrace command =
                    capabilityPermissionCommands.getFirst();
            CapabilityPermissionResultTrace result =
                    capabilityPermissionResults.getFirst();
            CapabilityManifestTrace manifest = capabilityManifests.getFirst();
            require(missing,
                    manifest.traceShape
                            && exactDefaultDenyManifest(manifest.payload),
                    "exact loaded empty enforced default-deny manifest trace");
            require(missing, manifest.order < command.order,
                    "default-deny manifest precedes capability command");
            require(missing,
                    command.traceShape && result.traceShape,
                    "full default-deny command/result transport trace shape");
            require(missing,
                    "main".equals(command.windowId)
                            && !command.sessionId.isBlank()
                            && "main".equals(command.uiId)
                            && "Capability permission allowed title".equals(
                            command.title),
                    "default-deny scoped window.setTitle command");
            require(missing, correlated(command, result),
                    "dynamic default-deny command/result correlation, scope and order");
            require(missing, exactDefaultDeniedPermissionPayload(result.payload),
                    "exact default-deny capability result payload");
            if (acceptance != null) {
                require(missing,
                        command.windowId.equals(text(acceptance, "windowId"))
                                && command.sessionId.equals(text(
                                acceptance, "sessionId"))
                                && command.uiId.equals(text(
                                acceptance, "uiId")),
                        "default-deny acceptance and command scope correlation");
            }
            require(missing,
                    flowCapabilityDefaultDenyAcceptanceOrder > result.order,
                    "default-deny capability result precedes acceptance completion");
            require(missing,
                    shutdownSidecarCount == 1
                            && gracefulShutdownSidecarOrder
                            > flowCapabilityDefaultDenyAcceptanceOrder,
                    "one graceful recv shutdown after default-deny acceptance");
        }

        private CapabilityPermissionCommandTrace capabilityCommand(
                String windowId) {
            CapabilityPermissionCommandTrace match = null;
            for (CapabilityPermissionCommandTrace candidate
                    : capabilityPermissionCommands) {
                if (!windowId.equals(candidate.windowId)) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = candidate;
            }
            return match;
        }

        private CapabilityPermissionResultTrace capabilityResult(
                String windowId) {
            CapabilityPermissionResultTrace match = null;
            for (CapabilityPermissionResultTrace candidate
                    : capabilityPermissionResults) {
                if (!windowId.equals(candidate.windowId)) {
                    continue;
                }
                if (match != null) {
                    return null;
                }
                match = candidate;
            }
            return match;
        }

        private static boolean correlated(
                CapabilityPermissionCommandTrace command,
                CapabilityPermissionResultTrace result) {
            return !command.correlationId.isBlank()
                    && command.id.equals(command.correlationId)
                    && result.id.equals("capability-" + command.correlationId)
                    && result.correlationId.equals(command.correlationId)
                    && result.windowId.equals(command.windowId)
                    && result.sessionId.equals(command.sessionId)
                    && result.uiId.equals(command.uiId)
                    && result.order > command.order;
        }

        private String permissionManifestCommands(String window, int beforeOrder, List<String> missing) {
            require(missing, capabilityManifests.size() == 1, "one loaded permission manifest");
            if (capabilityManifests.size() != 1) return "";
            CapabilityManifestTrace manifest = capabilityManifests.getFirst();
            JsonNode p = manifest.payload;
            require(missing, manifest.traceShape && manifest.order < beforeOrder
                            && bool(p, "loaded") && text(p, "parseError").isEmpty()
                            && "manifest-enforced".equals(text(p, "permissionMode"))
                            && "$APP/Contents/Resources/desktop-capabilities.json".equals(text(p, "path")),
                    "valid permission manifest precedes command");
            JsonNode entries = p.path("commandsByWindow").path(window);
            List<String> commands = new ArrayList<>();
            boolean canonical = entries.isArray();
            for (JsonNode entry : entries) {
                canonical &= entry.isTextual() && !entry.asText().isBlank() && !entry.asText().contains(",");
                commands.add(entry.asText());
            }
            canonical &= commands.equals(commands.stream().distinct().sorted().toList());
            require(missing, canonical, "canonical permission manifest commands for " + window);
            return String.join(",", commands);
        }

        private static boolean exactAllowedPermissionPayload(JsonNode payload, String commands) {
            return payload.isObject() && payload.size() == 11
                    && bool(payload, "success")
                    && "window.setTitle".equals(text(payload, "command"))
                    && "Capability permission allowed title".equals(
                    text(payload, "title"))
                    && "native-appkit".equals(text(payload, "mode"))
                    && exactPermissionAudit(
                    payload,
                    "allowed",
                    "manifest-allow",
                    "window:main",
                    commands);
        }

        private static boolean exactDeniedPermissionPayload(JsonNode payload, String commands) {
            return payload.isObject() && payload.size() == 10
                    && payload.path("success").isBoolean()
                    && !payload.path("success").asBoolean()
                    && "window.setTitle".equals(text(payload, "command"))
                    && "Command not allowed by desktop-capabilities.json".equals(
                    text(payload, "error"))
                    && exactPermissionAudit(
                    payload,
                    "denied",
                    "manifest-denied",
                    "window:permission-secondary",
                    commands);
        }

        private static boolean exactDefaultDeniedPermissionPayload(
                JsonNode payload) {
            return payload.isObject() && payload.size() == 10
                    && payload.path("success").isBoolean()
                    && !payload.path("success").asBoolean()
                    && "window.setTitle".equals(text(payload, "command"))
                    && "Command not allowed by desktop-capabilities.json".equals(
                    text(payload, "error"))
                    && exactPermissionAudit(
                    payload,
                    "denied",
                    "manifest-denied",
                    "window:main",
                    "");
        }

        private static boolean exactDefaultDenyManifest(JsonNode payload) {
            JsonNode commandsByWindow = payload.path("commandsByWindow");
            return payload.isObject() && payload.size() == 5
                    && "$APP/Contents/Resources/desktop-capabilities.json".equals(
                    text(payload, "path"))
                    && bool(payload, "loaded")
                    && "manifest-enforced".equals(text(
                    payload, "permissionMode"))
                    && commandsByWindow.isObject()
                    && commandsByWindow.isEmpty()
                    && text(payload, "parseError").isEmpty();
        }

        private static boolean exactPermissionAudit(
                JsonNode payload,
                String decision,
                String reason,
                String scope,
                String manifestCommands) {
            return "manifest-enforced".equals(text(payload, "permissionMode"))
                    && decision.equals(text(payload, "permissionDecision"))
                    && reason.equals(text(payload, "permissionReason"))
                    && scope.equals(text(payload, "permissionScope"))
                    && bool(payload, "permissionManifestLoaded")
                    && "$APP/Contents/Resources/desktop-capabilities.json".equals(
                    text(payload, "permissionManifestPath"))
                    && manifestCommands.equals(text(
                    payload, "permissionManifestCommands"));
        }

