        private static final List<String> GRID_REMOVAL_STAGES = List.of("initial", "selected", "off-viewport", "removed",
                "removal-revisited", "survivor-selected", "survivor-off-viewport", "survivor-revisited");
        private static final List<String> GRID_REMOVAL_POINTERS = List.of("select-L-060", "remove-selected-L-060", "select-L-061");
        private static final List<String> GRID_REMOVAL_LABELS = List.of("L-060", "delete-selected-L-060", "L-061");
        private static final List<String> GRID_REMOVAL_SETUP = List.of("navigate", "scroll-select-target", "position-select-L-060",
                "scroll-selected-off-viewport", "position-remove-selected-L-060", "scroll-removed-neighborhood",
                "position-select-L-061", "scroll-survivor-off-viewport", "scroll-survivor-revisit");

        private static String gridRemovalSelection(int change) {
            return "Lazy grid selection: " + switch (change) {
                case 0 -> "none; change=0, added=none, removed=none, client=false";
                case 1 -> "L-060; change=1, added=L-060, removed=none, client=true";
                case 2 -> "none; change=2, added=none, removed=L-060, client=false";
                default -> "L-061; change=3, added=L-061, removed=none, client=true";
            };
        }

        private static String gridRemovalStatus(int fetchBaseline, int countBaseline) {
            return "Lazy grid selected removal: operation=deselect>remove>refreshAll; policy=PRESERVE_ALL, removed=L-060,"
                    + " removedSelected=true, beforeTotal=80, afterTotal=79, beforeSelected=L-060, afterDeselect=none, afterRefresh=none,"
                    + " selectionChangesBefore=1, selectionChangesAfterDeselect=2, selectionChangesAfterRefresh=2, removeSucceeded=true,"
                    + " removalChanges=1, dataChangeEvents=1, dataRefreshEvents=0, fetchBaseline=" + fetchBaseline
                    + ", countBaseline=" + countBaseline + ", client=true";
        }

        private void requireLazyGridSelectedRemoval(List<String> missing) {
            List<OrderedEventTrace> stages = lazyGridSelectedRemovalEvents.getOrDefault("stageObserved", List.of()),
                    pointers = lazyGridSelectedRemovalEvents.getOrDefault("nativePointerDispatch", List.of()),
                    finals = lazyGridSelectedRemovalEvents.getOrDefault("frameworkAcceptance", List.of());
            require(missing, stages.size() == 8 && pointers.size() == 3 && finals.size() == 1,
                    "selected-item removal exact eight viewport snapshots, three pointers and one acceptance");
            if (stages.size() != 8 || pointers.size() != 3 || finals.size() != 1) return;
            OrderedEventTrace accepted = finals.getFirst();
            JsonNode finalValue = accepted.payload;
            int host = finalValue.path("hostProcessIdentifier").asInt(-1), pid = finalValue.path("processIdentifier").asInt(-1),
                    window = finalValue.path("windowNumber").asInt(-1);
            require(missing, host > 0 && pid > 0 && host != pid && window > 0 && sidecarStarts.size() == 1
                            && sidecarStarts.getFirst().traceShape && navigationTimeoutInteger(sidecarStarts.getFirst().payload, "generation", 1)
                            && navigationTimeoutInteger(sidecarStarts.getFirst().payload, "processIdentifier", pid)
                            && sidecarStarts.getFirst().order < stages.getFirst().order && sidecarRecoveryScheduledEvents.isEmpty()
                            && sidecarRecoveryReadyEvents.isEmpty() && sidecarFailureInjections.isEmpty() && !sidecarReplacementRequested
                            && desktopCommands.isEmpty() && desktopResults.isEmpty(),
                    "selected-item removal one uninterrupted main owner without capability substitutes");
            int[] actionStages = {1, 3, 5};
            for (int index = 0; index < 3; index++) {
                OrderedEventTrace pointer = pointers.get(index);
                int stage = actionStages[index];
                require(missing, pointer.traceShape && gridRemovalFrame(pointer.payload, host, pid, window)
                                && navigationTimeoutInteger(pointer.payload, "windowNumber", window)
                                && navigationTimeoutInteger(pointer.payload, "eventCount", 2)
                                && bool(pointer.payload, "activeApplication") && bool(pointer.payload, "keyWindow")
                                && bool(pointer.payload, "nativeResponderOwned")
                                && "primary".equals(text(pointer.payload, "button"))
                                && "appkit-window-pointer-event".equals(text(pointer.payload, "inputMode"))
                                && GRID_REMOVAL_POINTERS.get(index).equals(text(pointer.payload, "stage"))
                                && GRID_REMOVAL_LABELS.get(index).equals(text(pointer.payload, "label"))
                                && stages.get(stage - 1).order < pointer.order && pointer.order < stages.get(stage).order,
                        "selected-item removal real ordered native click " + index);
            }
            for (int stage = 0; stage < 8; stage++) {
                OrderedEventTrace receipt = stages.get(stage);
                boolean action = stage == 1 || stage == 3 || stage == 5;
                require(missing, receipt.traceShape && gridRemovalFrame(receipt.payload, host, pid, window)
                                && GRID_REMOVAL_STAGES.get(stage).equals(text(receipt.payload, "stage"))
                                && receipt.order < accepted.order && (stage == 0 || stages.get(stage - 1).order < receipt.order)
                                && receipt.payload.path("quietPollCount").isIntegralNumber() && receipt.payload.path("quietPollCount").asInt(-1) >= 2
                                && receipt.payload.path("actionUidlRoundTripObserved").isBoolean()
                                && bool(receipt.payload, "actionUidlRoundTripObserved") == action,
                        "selected-item removal ordered stable scoped viewport " + stage);
                requireGridRemovalSnapshot(missing, receipt.payload, stage);
                requireLocalizedNumberTransport(missing, receipt, true);
                int requests = receipt.payload.path("requestCount").asInt(-1), responses = receipt.payload.path("responseCount").asInt(-1),
                        baseline = receipt.payload.path("requestBaseline").asInt(-1), responseBaseline = receipt.payload.path("responseBaseline").asInt(-1);
                require(missing, navigationTimeoutInteger(receipt.payload, "requestBaseline", baseline)
                                && navigationTimeoutInteger(receipt.payload, "responseBaseline", responseBaseline)
                                && baseline >= 0 && baseline <= requests && responseBaseline >= 0 && responseBaseline <= responses
                                && (stage != 0 || baseline == requests && responseBaseline == responses),
                        "selected-item removal honest action request baselines");
                if (stage > 0) for (String field : List.of("requestCount", "responseCount", "pushMessageCount", "queryCallCount", "countCallCount"))
                    require(missing, receipt.payload.path(field).asInt(-1) >= stages.get(stage - 1).payload.path(field).asInt(-1),
                            "selected-item removal monotonic actual counter " + field);
                if (action) {
                    OrderedEventTrace pointer = pointers.get((stage - 1) / 2);
                    require(missing, baseline >= stages.get(stage - 1).payload.path("requestCount").asInt(-1)
                                    && responseBaseline >= stages.get(stage - 1).payload.path("responseCount").asInt(-1)
                                    && requests > baseline && responses > responseBaseline
                                    && baseline <= externalFileDropEnvelopes.stream().filter(e -> e.type.equals("opaqueHttpStreamOpen") && e.order < pointer.order).count()
                                    && responseBaseline <= externalFileDropEnvelopes.stream().filter(e -> e.type.equals("opaqueHttpStreamResponseEnd") && e.order < pointer.order).count(),
                            "selected-item removal independent post-click transport advancement " + stage);
                    require(missing, externalFileDropEnvelopes.stream().anyMatch(open -> open.type.equals("opaqueHttpStreamOpen")
                                    && pointer.order < open.order && open.order < receipt.order && "POST".equals(text(open.payload, "method"))
                                    && text(open.payload, "url").matches("https://app\\.vatori\\.invalid/[^#]*[?&]v-r=uidl(?:&.*)?")
                                    && externalFileDropEnvelopes.stream().anyMatch(end -> end.type.equals("opaqueHttpStreamResponseEnd")
                                    && end.requestId.equals(open.requestId) && open.order < end.order && end.order < receipt.order
                                    && end.payload.path("bodyBytes").asLong(0) > 0)),
                            "selected-item removal native listener has a completed opaque UIDL response " + stage);
                }
            }
            JsonNode before = stages.get(2).payload, removed = stages.get(3).payload;
            require(missing, removed.path("refreshFetchBaseline").asInt(-1) >= before.path("queryCallCount").asInt(-1)
                            && removed.path("refreshCountBaseline").asInt(-1) >= before.path("countCallCount").asInt(-1)
                            && removed.path("queryCallCount").asInt(-1) > removed.path("refreshFetchBaseline").asInt(-1)
                            && removed.path("countCallCount").asInt(-1) > removed.path("refreshCountBaseline").asInt(-1),
                    "selected-item removal fresh count and fetch after explicit deselect/remove and before-refresh baselines");
            for (int stage = 4; stage < 8; stage++) for (String field : List.of("removalStatus", "refreshFetchBaseline", "refreshCountBaseline"))
                require(missing, removed.path(field).equals(stages.get(stage).payload.path(field)), "selected-item removal operation evidence remains frozen");
            require(missing, accepted.traceShape && gridRemovalFrame(finalValue, host, pid, window)
                            && stages.getLast().order < accepted.order && "survivor-revisited".equals(text(finalValue, "stage"))
                            && falseField(finalValue, "actionUidlRoundTripObserved") && exactTextArray(finalValue, "observedStages", GRID_REMOVAL_STAGES)
                            && finalValue.path("drainQuietPollCount").isIntegralNumber() && finalValue.path("drainQuietPollCount").asInt(-1) >= 3,
                    "selected-item removal final unchanged survivor and quiet drain");
            requireGridRemovalSnapshot(missing, finalValue, 7);
            requireLocalizedNumberTransport(missing, accepted, true);
            requireNativeEditStreams(missing, accepted);
            for (String field : List.of("removalStatus", "refreshFetchBaseline", "refreshCountBaseline"))
                require(missing, removed.path(field).equals(finalValue.path(field)), "selected-item removal final frozen operation evidence");
            for (String field : List.of("requestCount", "responseCount", "pushMessageCount", "queryCallCount", "countCallCount"))
                require(missing, finalValue.path(field).asInt(-1) >= stages.getLast().payload.path(field).asInt(-1),
                        "selected-item removal final monotonic counter " + field);
            for (String field : List.of("complete", "errorFree", "standardBundleMode", "rootRendered", "flowClientOwned",
                    "opaqueRequestBridgeObserved", "opaqueResponseBridgeObserved", "generatedAppKitInput", "explicitApplicationDeselectionObserved",
                    "removedItemAbsentObserved", "survivorSelectionObserved", "recycledSurvivorSelectionObserved"))
                require(missing, bool(finalValue, field), "selected-item removal " + field);
            for (String field : List.of("pushObserved", "physicalInputClaimed", "assistiveTechnologyClaimed"))
                require(missing, falseField(finalValue, field), "selected-item removal does not claim " + field);
            List<FlowIpcEnvelopeTrace> pushes = externalFileDropEnvelopes.stream().filter(e -> e.type.equals("opaquePush") || e.type.equals("opaquePushAck")).toList();
            if (!pushes.isEmpty()) requireWriteEpochPushes(missing, "flow-ipc-session", 0, accepted.order, accepted.order, accepted.order, "main");
            require(missing, navigationTimeoutInteger(finalValue, "pushMessageCount", (int) pushes.stream().filter(e -> e.type.equals("opaquePush"))
                            .map(e -> writeExitPushKey(e, 0)).distinct().count()), "selected-item removal actual ambient push count");
            requireGridRemovalShutdown(missing, accepted, stages.getFirst(), pid);
        }

        private boolean gridRemovalFrame(JsonNode value, int host, int pid, int window) {
            return localizedNumberFrame(value, host, pid) && navigationTimeoutInteger(value, "windowNumber", window)
                    && bool(value, "contextRetained") && bool(value, "windowRetained") && bool(value, "webViewRetained");
        }

        private void requireGridRemovalSnapshot(List<String> missing, JsonNode value, int stage) {
            int changes = stage == 0 ? 0 : stage < 3 ? 1 : stage < 5 ? 2 : 3, total = stage < 3 ? 80 : 79;
            int pointerCount = changes, setupCount = new int[]{1, 3, 4, 5, 6, 7, 8, 9}[stage];
            List<String> history = new ArrayList<>();
            for (int i = 1; i <= changes; i++) history.add(gridRemovalSelection(i));
            require(missing, bool(value, "routeReady") && bool(value, "firstMeaningfulPaint") && bool(value, "balancedDrainObserved")
                            && mainScope(value, "browserWindowId", "browserSessionId", "browserUiId")
                            && navigationTimeoutInteger(value, "flowClientCount", 1) && navigationTimeoutInteger(value, "gridSize", total)
                            // The Flow connector clears its local selected-item
                            // projection when cached rows are discarded. The
                            // Java history, not this cache, owns selection.
                            && navigationTimeoutInteger(value, "selectedItemsCount", stage == 1 || stage == 5 || stage == 7 ? 1 : 0)
                            && bool(value, "selectionColumnObserved") && bool(value, "ariaMultiSelectableObserved")
                            && value.path("filterValue").isTextual() && text(value, "filterValue").isEmpty()
                            && "Lazy grid refresh: pending".equals(text(value, "refreshStatus"))
                            && "Lazy grid refresh all: pending".equals(text(value, "refreshAllStatus"))
                            && gridRemovalSelection(changes).equals(text(value, "selectionStatus"))
                            && ("Lazy grid selection history: " + (changes == 0 ? "pending" : String.join(" | ", history))).equals(text(value, "selectionHistory"))
                            && value.path("removeButtonDisabled").isBoolean() && bool(value, "removeButtonDisabled") == (stage == 0 || stage >= 3),
                    "selected-item removal exact public Java history and actual Grid selection cardinality " + stage);
            for (String field : List.of("browserError", "requestError", "responseError", "pushError", "markerError"))
                require(missing, value.path(field).isTextual() && text(value, field).isEmpty(), "selected-item removal no " + field);
            require(missing, exactTextArray(value, "pointerStages", GRID_REMOVAL_POINTERS.subList(0, pointerCount))
                            && exactTextArray(value, "pointerLabels", GRID_REMOVAL_LABELS.subList(0, pointerCount))
                            && exactTextArray(value, "domEventOrder", GRID_REMOVAL_POINTERS.subList(0, pointerCount).stream().map(s -> "pointer:" + s).toList())
                            && exactTextArray(value, "browserProgrammaticStages", GRID_REMOVAL_SETUP.subList(0, setupCount))
                            && navigationTimeoutInteger(value, "nativePointerEventCount", pointerCount)
                            && navigationTimeoutInteger(value, "nativePointerTrustedEventCount", pointerCount),
                    "selected-item removal exact trusted pointer and scripted viewport boundaries " + stage);
            int fetch = value.path("queryCallCount").asInt(-1), count = value.path("countCallCount").asInt(-1),
                    fetchBaseline = value.path("refreshFetchBaseline").asInt(-1), countBaseline = value.path("refreshCountBaseline").asInt(-1);
            require(missing, navigationTimeoutInteger(value, "queryCallCount", fetch) && fetch > 0
                            && navigationTimeoutInteger(value, "countCallCount", count) && count > 0
                            && navigationTimeoutInteger(value, "refreshFetchBaseline", fetchBaseline)
                            && navigationTimeoutInteger(value, "refreshCountBaseline", countBaseline)
                            && (stage < 3 ? fetchBaseline == 0 && countBaseline == 0
                            && "Lazy grid selected removal: pending".equals(text(value, "removalStatus"))
                            : fetchBaseline > 0 && countBaseline > 0 && gridRemovalStatus(fetchBaseline, countBaseline).equals(text(value, "removalStatus"))),
                    "selected-item removal actual operation and callback baselines");
            require(missing, gridRemovalCallbackStatus(text(value, "queryStatus"), true, fetch, total, stage)
                            && gridRemovalCallbackStatus(text(value, "countStatus"), false, count, total, stage),
                    "selected-item removal anchored provider count/fetch syntax and actual numeric metadata");
            List<String> rendered = gridRemovalLabels(value.path("renderedLabels")), visible = gridRemovalLabels(value.path("visibleLabels"));
            int rows = value.path("renderedRowCount").asInt(-1);
            boolean top = stage == 0 || stage == 2 || stage == 6;
            // Positioning the lower delete button can move the Grid outside
            // the browser viewport. The subsequent revisit, not this response
            // receipt, proves visible row absence and neighborhood continuity.
            require(missing, rendered != null && visible != null && (stage == 3 || !visible.isEmpty()) && rendered.containsAll(visible)
                            && navigationTimeoutInteger(value, "renderedRowCount", rows) && rows >= rendered.size() && rows > 0 && rows < total
                            && (stage < 3 || !rendered.contains("L-060"))
                            && (!top || visible.contains("L-001") && !rendered.contains("L-060") && !rendered.contains("L-061"))
                            && (stage != 1 || visible.contains("L-060"))
                            && (stage != 4 && stage != 5 && stage != 7 || visible.contains("L-059") && visible.contains("L-061")
                            && rendered.indexOf("L-061") == rendered.indexOf("L-059") + 1),
                    "selected-item removal real recycled viewport and adjacent survivor neighborhood " + stage);
            List<String> selected = stage == 1 ? List.of("L-060") : stage == 5 || stage == 7 ? List.of("L-061") : List.of();
            for (String field : List.of("selectedRowLabels", "checkedRowLabels", "ariaSelectedRowLabels"))
                require(missing, exactTextArray(value, field, selected), "selected-item removal actual selected row identity " + field);
            for (String field : List.of("selectedRenderedRowCount", "checkedRenderedRowCount", "ariaSelectedRenderedRowCount"))
                require(missing, navigationTimeoutInteger(value, field, selected.size()), "selected-item removal no ghost selected rows " + field);
        }

        private static List<String> gridRemovalLabels(JsonNode values) {
            if (!values.isArray()) return null;
            List<String> labels = new ArrayList<>();
            for (JsonNode value : values) {
                if (!value.isTextual() || !value.asText().matches("L-(?:0[0-7][0-9]|080)") || "L-000".equals(value.asText())
                        || labels.contains(value.asText())) return null;
                labels.add(value.asText());
            }
            return labels;
        }

        private static boolean gridRemovalCallbackStatus(String status, boolean fetch, int count, int total, int stage) {
            String number = "(0|[1-9][0-9]*)";
            Matcher matcher = Pattern.compile(fetch
                    ? "^Lazy grid query " + number + ": range=" + number + "-" + number + " sort=none filter=all matches=" + total + " selected=(none|L-060|L-061)$"
                    : "^Lazy Grid selection count " + number + ": filter=all matches=" + total + " selected=(none|L-060|L-061)$").matcher(status);
            if (!matcher.matches()) return false;
            try {
                if (Integer.parseInt(matcher.group(1)) != count) return false;
                if (fetch) {
                    int offset = Integer.parseInt(matcher.group(2)), end = Integer.parseInt(matcher.group(3));
                    if (end > total || (offset < total ? end <= offset : end != total)) return false;
                }
            } catch (NumberFormatException ignored) { return false; }
            String selected = matcher.group(fetch ? 4 : 2);
            return "none".equals(selected) || stage > 0 && stage < 3 && "L-060".equals(selected)
                    || stage >= 5 && "L-061".equals(selected);
        }

        private void requireGridRemovalShutdown(List<String> missing, OrderedEventTrace accepted, OrderedEventTrace initial, int pid) {
            OrderedEventTrace create = uniqueScopedEvent(windowCreateEvents, "main", "flow-ipc-session", "main"),
                    load = uniqueScopedEvent(webViewLoadedEvents, "main", "flow-ipc-session", "main"),
                    close = uniqueScopedEvent(windowCloseRequests, "main", "flow-ipc-session", "main"),
                    closed = uniqueScopedEvent(windowClosedEvents, "main", "flow-ipc-session", "main");
            require(missing, windowCreateEvents.size() == 1 && webViewLoadedEvents.size() == 1 && windowCloseRequests.size() == 1 && windowClosedEvents.size() == 1
                            && create != null && load != null && close != null && closed != null
                            && nativeResourceDrainStarted.size() == 1 && nativeResourceDrainCompleted.size() == 1
                            && sidecarShutdownRequests.size() == 1 && shutdownSidecarCount == 1,
                    "selected-item removal exact main lifecycle, empty resource drain and shutdown");
            if (create == null || load == null || close == null || closed == null || nativeResourceDrainStarted.size() != 1
                    || nativeResourceDrainCompleted.size() != 1 || sidecarShutdownRequests.size() != 1) return;
            OrderedEventTrace drain = nativeResourceDrainStarted.getFirst(), drained = nativeResourceDrainCompleted.getFirst(), shutdown = sidecarShutdownRequests.getFirst();
            require(missing, exactMainCreate(create) && load.traceShape && exactMainCloseRequest(close) && exactMainWindowClosed(closed)
                            && create.order < load.order && load.order < initial.order && accepted.order < close.order && close.order < closed.order
                            && drain.traceShape && drained.traceShape && shutdown.traceShape && closed.order < drain.order
                            && navigationTimeoutInteger(drain.payload, "pendingCount", 0) && navigationTimeoutInteger(drain.payload, "timeoutSeconds", 2)
                            && bool(drained.payload, "drained") && navigationTimeoutInteger(drained.payload, "pendingCount", 0)
                            && navigationTimeoutInteger(drained.payload, "failureCount", 0) && drain.order < drained.order
                            && drained.order < shutdown.order && shutdown.order < gracefulShutdownSidecarOrder
                            && "java-sidecar".equals(text(shutdown.payload, "target")) && "flow-ipc".equals(text(shutdown.payload, "transport"))
                            && "host-terminate".equals(text(shutdown.payload, "reason")), "selected-item removal evidence before clean main teardown");
            require(missing, sidecarExits.size() <= 1 && sidecarExits.stream().allMatch(e -> e.traceShape && bool(e.payload, "expected")
                            && navigationTimeoutInteger(e.payload, "generation", 1) && navigationTimeoutInteger(e.payload, "processIdentifier", pid)
                            && navigationTimeoutInteger(e.payload, "status", 0) && e.order > shutdown.order), "selected-item removal no unexpected sidecar exit");
        }

