        private static final List<String> EDIT_REOPEN_STAGES = List.of("main-initial", "main-insert", "opened-a", "a-insert", "a-retired", "opened-b", "b-empty-undo", "b-insert", "b-undo", "b-redo", "main-undo", "main-redo");
