                String owner = editReopenOwner(stage);
                requireEditReopenDispatch(missing, pointer, EDIT_REOPEN_POINTERS.get(stage - 1), owner, finalValue, a, b, false);
                require(missing, stages.get(stage - 1).order < pointer.order && pointer.order < receipt.order,
                        "native edit reopen pointer belongs to its own checkpoint");
